id {\n    // change the page\n    const { orderBy, orderType } = this.props.paymentMethod.options;\n    this.props.getPaymentMethodThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { paymentMethod: IPaymentMethodState }) => {\n  return {\n    paymentMethod: state.paymentMethod\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getPaymentMethodThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getPaymentMethodThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createPaymentMethodThunkAction: (paymentMethod: IPaymentMethod) => dispatch(createPaymentMethodThunkAction(paymentMethod)),\n    updatePaymentMethodThunkAction: (paymentMethod: IPaymentMethod) => dispatch(updatePaymentMethodThunkAction(paymentMethod)),\n    deletePaymentMethodThunkAction: (paymentMethod: IPaymentMethod) => dispatch(deletePaymentMethodItemThunkAction(paymentMethod)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ paymentMethod: IPaymentMethodState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(PaymentMethodListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, FieldArray, InjectedFormProps, reduxForm, WrappedFieldArrayProps } from 'redux-form';\nimport { IReasonsState } from '../../actions/reasons.types';\nimport BootstrapSwitchField from '../Utils/forms/BootsrapSwitchField';\nimport CheckBoxField from '../Utils/forms/CheckBoxField';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\nconst renderQuestion: React.FunctionComponent<WrappedFieldArrayProps<{}>> = ({\n  fields,\n  meta: { error, submitFailed }\n}) => {\n  return (\n    <React.Fragment>\n      {\n        fields.length === 0 ?\n          <div className=\"col-md-12\">\n            <p\n              className=\"text-center text-muted\"\n              style={{padding: '20px 0'}}\n            >\n              No hay preguntas personalizadas para agregar una <a href=\"javascript:void(0)\" onClick={() => fields.push({})}>haz click aquí.</a>\n            </p>\n          </div> :\n          fields.map((question, index) => {\n            return (\n              <div style={{\n                borderBottom: index + 1 !== fields.length ? '1px solid #ededed' : '',\n                margin: '0',\n                marginBottom:  index + 1 !== fields.length ? '5px': '0'\n              }}\n                key={index} className=\"row\"\n              >\n                <div className=\"col-md-11 col-sm-11 col-xs-10\">\n                  <Field\n                    name={`${question}.name`}\n                    label={`Pregunta ${index + 1} *`}\n                    component={InputField}\n                    validate={[inputStringRequired]}\n                  />\n                  <Field\n                    name={`${question}.required`}\n                    label=\"Hacer obligatoria\"\n                    type=\"checkbox\"\n                    component={CheckBoxField}\n                    validate={[]}\n                  />\n                </div>\n                <div className=\"col-md-1 col-sm-1 col-xs-2 text-left\" style={{ paddingLeft: '0' }}>\n                  <button\n                    type=\"button\"\n                    style={{ marginTop: '25px' }}\n                    className=\"btn btn-sm btn-danger\"\n                    onClick={() => fields.remove(index)}\n                  >\n                    <i className=\"fa fa-trash\" />\n                  </button>\n                </div>\n                {/* <div className=\"col-md-2 col-sm-2 col-xs-2\" /> */}\n              </div>\n            );\n          })\n      }\n      {\n        fields.length >= 1 ?\n          <div className=\"col-md-12 col-sm-12 col-xs-12 text-right\">\n            <button\n              type=\"button\"\n              className=\"btn btn-sm btn-success\"\n              onClick={() => fields.push({})}\n            >\n              <i className=\"fa fa-fw fa-plus\" /> Agregar pregunta\n        </button>\n            {submitFailed && error && <span>{error}</span>}\n          </div>\n          : null\n      }\n    </React.Fragment>\n  );\n};\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-10\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-4\">\n            <Field\n              name=\"file.active\"\n              label=\"Requerir archivos\"\n              type=\"checkbox\"\n              component={BootstrapSwitchField}\n              validate={[]}\n            />\n          </div>\n          <div className=\"col-md-8\">\n            <Field\n              name=\"file.required\"\n              label=\"Archivos obligatorios\"\n              type=\"checkbox\"\n              component={BootstrapSwitchField}\n              validate={[]}\n            />\n          </div>\n          <div className=\"col-md-12\" style={{marginTop: '10px'}}>\n            <h4>Preguntas personalizadas</h4>\n          </div>\n          <FieldArray\n            name=\"questions\"\n            component={renderQuestion}\n          />\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst ReasonForm = reduxForm({\n  form: 'reasonForm'\n})(Form);\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(ReasonForm);","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { ISalesChannel } from '../../../../../../src/request/interfaces/salesChannel.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { ISalesChannelState, RequestChannelReduxActions } from '../../actions/requestChannel.types';\nimport {\n  createRequestChannelThunkAction,\n  deleteRequestChannelItemThunkAction,\n  getRequestChannelThunkAction,\n  updateRequestChannelThunkAction\n} from '../../actions/requestChannel.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ChannelForm from './ChannelForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<RequestChannelReduxActions | FormAction>;\n  requestChannel: ISalesChannelState;\n\n  getRequestChannelThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): RequestChannelReduxActions;\n  createRequestChannelThunkAction(requestChannel: ISalesChannel): RequestChannelReduxActions;\n  updateRequestChannelThunkAction(requestChannel: ISalesChannel): RequestChannelReduxActions;\n  deleteRequestChannelThunkAction(requestChannel: ISalesChannel): RequestChannelReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestChannelListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de Canales';\n    this.changePage = this.changePage.bind(this);\n    this.createRequestChannel = this.createRequestChannel.bind(this);\n    this.processCreateRequestChannel = this.processCreateRequestChannel.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateRequestChannel = this.processUpdateRequestChannel.bind(this);\n    this.deleteRequestChannel = this.deleteRequestChannel.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.requestChannel;\n    const { orderBy, orderType } = this.props.requestChannel.options;\n    this.props.getRequestChannelThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-status-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.requestChannel;\n        const { orderBy, orderType } = this.props.requestChannel.options;\n        this.props.getRequestChannelThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.requestChannel.pagination !== prevProps.requestChannel.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestChannel.source) {\n      this.props.requestChannel.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, channels, pagination } = this.props.requestChannel;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Canales\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item active\">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item \">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Canales <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                          onClick={this.createRequestChannel}\n                        ><i className=\"fa fa-plus\" />  Crear canal</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '98%' }} className=\"middle\">Nombre</th>\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        channels.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className=\"middle\">{item.name}</td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(item)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deleteRequestChannel(item) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\" />\n                                  </td> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createRequestChannel(): void {\n    this.props.loadDataAction(\n      'Agregar Canal',\n      <ChannelForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateRequestChannel}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('channelForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateRequestChannel(requestChannel: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createRequestChannelThunkAction(requestChannel);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar Canal',\n      <ChannelForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateRequestChannel}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('channelForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateRequestChannel(requestChannel: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateRequestChannelThunkAction(requestChannel);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteRequestChannel(requestChannel: ISalesChannel): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el canal: ${requestChannel.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRequestChannelThunkAction(requestChannel);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.requestChannel.options;\n    this.props.getRequestChannelThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { requestChannel: ISalesChannelState }) => {\n  return {\n    requestChannel: state.requestChannel\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestChannelThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestChannelThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createRequestChannelThunkAction: (requestChannel: ISalesChannel) => dispatch(createRequestChannelThunkAction(requestChannel)),\n    updateRequestChannelThunkAction: (requestChannel: ISalesChannel) => dispatch(updateRequestChannelThunkAction(requestChannel)),\n    deleteRequestChannelThunkAction: (requestChannel: ISalesChannel) => dispatch(deleteRequestChannelItemThunkAction(requestChannel)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ requestChannel: ISalesChannelState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestChannelListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IReason } from '../../../../../../src/request/interfaces/reason.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  createReasonThunkAction,\n  deleteReasonThunkAction,\n  getReasonsThunkAction, updateReasonThunkAction\n} from '../../actions/reasons.actions';\nimport { IReasonsState, ReasonsReduxActions } from '../../actions/reasons.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ReasonForm from './ReasonForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ReasonsReduxActions | FormAction>;\n  reasons: IReasonsState;\n\n  getReasonsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): ReasonsReduxActions;\n  createReasonThunkAction(reason: IReason): ReasonsReduxActions;\n  updateReasonThunkAction(reason: IReason): ReasonsReduxActions;\n  deleteReasonThunkAction(reason: IReason): ReasonsReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestReasonListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de Motivos';\n    this.changePage = this.changePage.bind(this);\n    this.createReason = this.createReason.bind(this);\n    this.processCreateReason = this.processCreateReason.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateReason = this.processUpdateReason.bind(this);\n    this.deleteReason = this.deleteReason.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.reasons;\n    const { orderBy, orderType } = this.props.reasons.options;\n    this.props.getReasonsThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `reasons-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.reasons;\n        const { orderBy, orderType } = this.props.reasons.options;\n        this.props.getReasonsThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.reasons.pagination !== prevProps.reasons.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.reasons.source) {\n      this.props.reasons.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    // const { exporing } = this.state;\n    const { loading, reasons, pagination } = this.props.reasons;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Motivos\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item active\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item \">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item \">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Motivos <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                        onClick={this.createReason}\n                        ><i className=\"fa fa-plus\" /> Crear motivo</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '50%' }} className=\"middle\">Nombre</th>\n                        <th style={{ width: '15%' }} className=\"middle-center\">Archivos</th>\n                        <th style={{ width: '15%' }} className=\"middle-center\">Preguntas</th>\n                        {/* <th style={{ width: '20%' }} className=\"middle hidden-xs\">Modificado</th> */}\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        reasons.map((reason) => {\n                          return (\n                            <tr key={reason._id}>\n                              <td>{reason.name}</td>\n                              <td className=\"middle-center\">\n                                <i\n                                  className={\n                                    reason.file.active ?\n                                      'fa fa-check-circle text-green' :\n                                      'fa fa-times-circle text-red'\n                                  }\n                                />\n                              </td>\n                              <td className=\"middle-center\">{reason.questions.length}</td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(reason)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deleteReason(reason) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\" />\n                                  </td> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createReason(): void {\n    this.props.loadDataAction(\n      'Agregar Motivo',\n      <ReasonForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateReason}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('reasonForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateReason(reason: IReason): void {\n    statusFooterButttonsModal(true);\n    this.props.createReasonThunkAction(reason);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: IReason): void {\n    this.props.loadDataAction(\n      'Editar Motivo',\n      <ReasonForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateReason}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('reasonForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateReason(reason: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateReasonThunkAction(reason);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteReason(reason: IReason): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el motivo: ${reason.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteReasonThunkAction(reason);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.reasons.options;\n    this.props.getReasonsThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getReasonsThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getReasonsThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createReasonThunkAction: (reason: IReason) => dispatch(createReasonThunkAction(reason)),\n    updateReasonThunkAction: (reason: IReason) => dispatch(updateReasonThunkAction(reason)),\n    deleteReasonThunkAction: (reason: IReason) => dispatch(deleteReasonThunkAction(reason)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestReasonListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IRequestStatus } from '../../../../../../src/request/interfaces/requestStatus.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  createRequestStatusThunkAction,\n  deleteRequestStatusItemThunkAction,\n  getRequestStatusThunkAction,\n  updateRequestStatusThunkAction\n} from '../../actions/requestStatus.actions';\nimport { IRequestStatusState, RequestStatusReduxActions } from '../../actions/requestStatus.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport StatusForm from './StatusForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<RequestStatusReduxActions | FormAction>;\n  requestStatus: IRequestStatusState;\n\n  getRequestStatusThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): RequestStatusReduxActions;\n  createRequestStatusThunkAction(requestStatus: IRequestStatus): RequestStatusReduxActions;\n  updateRequestStatusThunkAction(requestStatus: IRequestStatus): RequestStatusReduxActions;\n  deleteRequestStatusThunkAction(requestStatus: IRequestStatus): RequestStatusReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestStatusListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de Status';\n    this.changePage = this.changePage.bind(this);\n    this.createRequestStatus = this.createRequestStatus.bind(this);\n    this.processCreateRequestStatus = this.processCreateRequestStatus.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateRequestStatus = this.processUpdateRequestStatus.bind(this);\n    this.deleteRequestStatus = this.deleteRequestStatus.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.requestStatus;\n    const { orderBy, orderType } = this.props.requestStatus.options;\n    this.props.getRequestStatusThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-status-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.requestStatus;\n        const { orderBy, orderType } = this.props.requestStatus.options;\n        this.props.getRequestStatusThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.requestStatus.pagination !== prevProps.requestStatus.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestStatus.source) {\n      this.props.requestStatus.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, status, pagination } = this.props.requestStatus;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Estados\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item\">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item active\">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Estados <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                        onClick={this.createRequestStatus}\n                        ><i className=\"fa fa-plus\" />  Crear estado</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '70%' }} className=\"middle\">Nombre</th>\n                        <th style={{ width: '10%' }} className=\"middle\">Peso</th>\n                        <th style={{ width: '18%' }} className=\"middle text-center\">Default</th>\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        status.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className=\"middle\">{item.name}</td>\n                              <td className=\"middle\">{item.weigth}</td>\n                              <td className=\"middle text-center\">\n                                <i\n                                  className={\n                                    item.default ?\n                                      'fa fa-check-circle text-green':\n                                      'fa fa-times-circle text-red'\n                                  }\n                                />\n                              </td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(item)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                !item.default && canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deleteRequestStatus(item) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\"/>\n                                  </td> : canDelete ?\n                                    <td/> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createRequestStatus(): void {\n    this.props.loadDataAction(\n      'Agregar Estado',\n      <StatusForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateRequestStatus}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('statusForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateRequestStatus(requestStatus: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createRequestStatusThunkAction(requestStatus);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar Estado',\n      <StatusForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateRequestStatus}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('statusForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateRequestStatus(requestStatus: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateRequestStatusThunkAction(requestStatus);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteRequestStatus(requestStatus: IRequestStatus): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el estado: ${requestStatus.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRequestStatusThunkAction(requestStatus);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.requestStatus.options;\n    this.props.getRequestStatusThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { requestStatus: IRequestStatusState }) => {\n  return {\n    requestStatus: state.requestStatus\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestStatusThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestStatusThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(createRequestStatusThunkAction(requestStatus)),\n    updateRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(updateRequestStatusThunkAction(requestStatus)),\n    deleteRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(deleteRequestStatusItemThunkAction(requestStatus)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ requestStatus: IRequestStatusState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestStatusListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IRequestStatusState } from '../../actions/requestStatus.types';\nimport BootstrapSwitchField from '../Utils/forms/BootsrapSwitchField';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid, submitFailed } = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-12\">\n            <Field\n              name=\"weigth\"\n              label=\"Peso *\"\n              placeholder=\"Peso\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-12\">\n            <Field\n              name={`default`}\n              label=\"Por defecto\"\n              type=\"checkbox\"\n              component={BootstrapSwitchField}\n              validate={[]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{ marginTop: '20px' }}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst StatusForm = reduxForm({\n  form: 'statusForm'\n})(Form);\n\nconst mapStateToProps = (state: { requestStatus: IRequestStatusState }) => {\n  return {\n    requestStatus: state.requestStatus\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ requestStatus: IRequestStatusState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(StatusForm);","import { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport AppContainer from '../../container/AppContainer';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as Raven from 'raven-js';\nimport { connect } from 'react-redux';\nimport {\n  changeTempStudioAction,\n  createStudioAction,\n  deleteStudioAction,\n  editStudioAction,\n  getStudiosAction,\n  IStatsDashboardState,\n  ITempStudio,\n  loadStudioUsersAction,\n  StatsDashboardReducerAction\n} from '../../actions/statsDashboard.actions';\nimport { DashboardTypesDictionary, StatsDashboardTypes } from '../../../../../../src/stats/models/studio.types';\nimport { IStudio } from '../../../../../../src/stats/interfaces/studio.interface';\nimport { hasPermission } from '../../utils/common';\nimport * as moment from 'moment';\nimport Paginator from '../Utils/Paginator';\nimport ModalView from '../Modal/ModalView';\nimport { IWindow } from '../../interfaces/window';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport * as swal from 'sweetalert';\nimport StudioFormView from './StudioFormView';\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<StatsDashboardReducerAction>;\n  dashboard: IStatsDashboardState;\n  getStudiosAction(type?: StatsDashboardTypes | null): void;\n  loadStudioUsers(): void;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  changeTempStudioAction(studio: ITempStudio): void;\n  deleteStudio(studio: IStudio): void;\n  processCreateStudio(): void;\n  processEditStudio(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  type: StatsDashboardTypes | null;\n}\n\ndeclare let window: IWindow;\n\nclass DashboardStatsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  state = {\n    error: null,\n    type: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = \"Configuración de Studios\";\n\n    this.processEditStudio = this.processEditStudio.bind(this);\n    this.createStudio = this.createStudio.bind(this);\n    this.processCreateStudio = this.processCreateStudio.bind(this);\n    this.deleteStudio = this.deleteStudio.bind(this);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    this.props.getStudiosAction(this.state.type);\n    this.props.loadStudioUsers();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  private showStudioModal(studio?: IStudio): void {\n    this.props.changeTempStudioAction(studio ?? {\n      name: \"\",\n      team: window.user.team._id,\n      _id: '',\n      embedURL: '',\n      type: '',\n      users: []\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        studio ? 'Editar Studio' : 'Agregar Studio',\n        <StudioFormView\n          changeTempStudioAction={this.props.changeTempStudioAction}\n          users={this.props.dashboard.users}\n          types={Object.keys(DashboardTypesDictionary).map(key => {\n            return {id: key, name: DashboardTypesDictionary[key]}\n          })}\n          dashboard={this.props.dashboard}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={studio ? this.processEditStudio : this.processCreateStudio}>Grabar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  public createStudio(studio: IStudio){\n\n  }\n\n  private processCreateStudio(): void {\n    const {tempStudio} = this.props.dashboard;\n    if (!tempStudio.name || !tempStudio.name.trim()) {\n      swal('Agregar Studio', 'El nombres es requerido', 'error');\n    } else if (!tempStudio.embedURL || !tempStudio.embedURL.trim()){\n      swal('Agregar Studio', 'El URL es requerido', 'error');\n    } else {\n      this.props.processCreateStudio();\n    }\n  }\n\n  private processEditStudio(): void {\n    const {tempStudio} = this.props.dashboard;\n    if (!tempStudio.name || !tempStudio.name.trim()) {\n      swal('Editar Studio', 'El nombres es requerido', 'error');\n    } else if (!tempStudio.embedURL || !tempStudio.embedURL.trim()){\n      swal('Editar Studio', 'El URL es requerido', 'error');\n    } else {\n      this.props.processEditStudio();\n    }\n  }\n\n  private deleteStudio(studio: IStudio) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el Dashboard: ${studio.name || ''}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteStudio(studio);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n  }\n\n\n  public render(): React.ReactElement<IPropsType> {\n    const {studios, loading, pagination} = this.props.dashboard;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"200\" cSubMenu=\"200.3\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Studios <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                {\n                  hasPermission(window.user, 'addStatsDashboard') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={() => this.showStudioModal()}><i className=\"fa fa-plus\" />  Agregar</button>\n                    : null\n                }\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                <tr>\n                  <th style={{width: '30%'}} className=\"middle\">Nombre</th>\n                  <th style={{width: '30%'}} className=\"middle\">Tipo</th>\n                  <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                  {\n                    hasPermission(window.user, 'changeStatsDashboard') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    hasPermission(window.user, 'deleteStatsDashboard') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && !studios.length?\n                    <tr>\n                      <td\n                        colSpan={2 + (hasPermission(window.user, 'deleteStatsDashboard') ? 1 : 0) +( hasPermission(window.user, 'changeStatsDashboard') ? 1 : 0)}\n                      >\n                        No se han creado análisis estadisticos\n                      </td>\n                    </tr>\n                    :null\n                }\n                {\n                  studios.map((studio: IStudio) => {\n                    return (\n                      <tr\n                        key={studio._id}\n                        id={`studio-${studio._id}`}\n                        className={'background-transition'}\n                      >\n                        <td className=\"middle\">{studio.name}</td>\n                        <td className=\"middle\">{DashboardTypesDictionary[studio.type]}</td>\n                        <td className=\"middle hidden-xs\">{moment(studio.updatedAt).format('LLL')}</td>\n                        {\n                          hasPermission(window.user, 'changeStatsDashboard') ?\n                            <td\n                              className=\"middle text-blue pointer\"\n                              onClick={() => this.showStudioModal(studio)}\n                            >\n                              <i className=\"fa fa-pencil\"/>\n                            </td> : null\n                        }\n                        {\n                          hasPermission(window.user, 'deleteStatsDashboard') ?\n                            <td\n                              className={'middle text-red pointer'}\n                              onClick={() => this.deleteStudio(studio)}\n                            ><i className=\"fa fa-minus-circle\"/></td> : null\n                        }\n                      </tr>\n                    );\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>)\n  }\n}\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard,\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getStudiosAction: (type?: StatsDashboardTypes) => dispatch(getStudiosAction(type)),\n    changeTempStudioAction: (studio: ITempStudio) => dispatch(changeTempStudioAction(studio)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    deleteStudio: (studio: IStudio) => dispatch(deleteStudioAction(studio._id)),\n    loadStudioUsers: () => dispatch(loadStudioUsersAction()),\n    processCreateStudio: () => dispatch(createStudioAction()),\n    processEditStudio: () => dispatch(editStudioAction()),\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardStatsListView);\n\n","import { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport AppContainer from '../../container/AppContainer';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as Raven from 'raven-js';\nimport { connect } from 'react-redux';\nimport { getMyStudiosAction, IStatsDashboardState, StatsDashboardReducerAction } from '../../actions/statsDashboard.actions';\nimport { IStudio } from '../../../../../../src/stats/interfaces/studio.interface';\nimport Row from '../Utils/Row';\nimport { StatsDashboardTypes } from '../../../../../../src/stats/models/studio.types';\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<StatsDashboardReducerAction>;\n  dashboard: IStatsDashboardState;\n  getMyStudiosAction(type?: StatsDashboardTypes): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  menu: string;\n  cSubmenu: string;\n  type: StatsDashboardTypes;\n  tab: String;\n}\n\nclass DashboardStatsView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  state = {\n    error: null,\n    menu: \"\",\n    cSubmenu: \"\",\n    tab: \"0\",\n    type: StatsDashboardTypes.UNIT_CONTROL,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = \"Dashboard de Estadísticas\";\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    this.props.getMyStudiosAction(this.state.type)\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    if (prevProps.dashboard.loading && !this.props.dashboard.loading && this.props.dashboard.studios.length > 0){\n      this.setState({\n        tab: this.props.dashboard.studios[0]._id as String\n      })\n    }\n  }\n\n  private changeTab(name: string): void {\n    this.setState({\n      tab: name\n    });\n  }\n\n\n  render() {\n    const {studios, loading} = this.props.dashboard;\n    const { tab } = this.state;\n    const selectedStudio : IStudio | undefined = studios.find((studio: IStudio) => studio._id === tab);\n    return <AppContainer title=\"\" cMenu={this.state.menu} cSubMenu={this.state.cSubmenu}>\n      <section className=\"content\">\n        <div className=\"box\">\n          <div className=\"box-header with-border\">\n            <h3 className=\"box-title\">Dashboard de Estadísticas</h3>\n          </div>\n          <div className=\"box-body\">\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n            {\n              !loading && studios.length == 0 &&\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <p>No se han encontrado resultados.</p>\n                </div>\n              </div>\n            }\n            {!loading && studios.length > 0 &&\n              <div className=\"col-md-12 col-lg-12\">\n                <div className=\"box box-solid\">\n                  <div className=\"nav-tabs-custom\">\n                    <ul className=\"nav nav-tabs\">\n                      {\n                        studios.map((studio: any) => {\n                          return (\n                            <li className={tab === studio._id ? 'active' : ''} key={studio._id}>\n                              <a\n                                href=\"javascript:void(0);\"\n                                className={tab === studio._id ? 'background-transition' : ''}\n                                style={{borderTop: '0', marginBottom: '0'}}\n                                onClick={() => this.changeTab(studio._id)}\n                              >{studio.name}</a>\n                            </li>\n                          )\n                        })\n                      }\n                    </ul>\n                  </div>\n                </div>\n              </div>\n            }\n            { selectedStudio &&\n              <Row>\n                <div className=\"col-md-12\">\n                  <div className=\"box\">\n                    <div className=\"box-body\">\n                      <iframe src={selectedStudio.embedURL} style={{width: \"100%\", minWidth: \"1000px\" ,minHeight: \"500px\", height: \"100vh\"}} allowFullScreen={true}  frameBorder={0} security={\"\"}/>\n                    </div>\n                  </div>\n                </div>\n              </Row>\n            }\n          </div>\n        </div>\n      </section>\n    </AppContainer>\n  }\n}\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard,\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getMyStudiosAction: (type?: StatsDashboardTypes) => dispatch(getMyStudiosAction(type))\n  };\n};\n\n\nclass InventoryDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"2\",\n    cSubmenu: \"2.5\",\n    type: StatsDashboardTypes.INVENTORY,\n    tab: \"\",\n  };\n}\n\nclass UnitControlDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"1\",\n    cSubmenu: \"1.7\",\n    type: StatsDashboardTypes.UNIT_CONTROL,\n    tab: \"\",\n  };\n}\n\nclass DistributionDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"3\",\n    cSubmenu: \"3.5\",\n    type: StatsDashboardTypes.DISTRIBUTION,\n    tab: \"\",\n  };\n}\n\nclass PlanificationDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"3\",\n    cSubmenu: \"3.5\",\n    type: StatsDashboardTypes.PLANIFICATION,\n    tab: \"\",\n  };\n}\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardStatsView);\nlet VInventoryDashboardStatsView =  connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryDashboardStatsView);\nlet VUnitControlDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UnitControlDashboardStatsView);\nlet VDistributionDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DistributionDashboardStatsView);\nlet VPlanificationDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(PlanificationDashboardStatsView);\nexport { VInventoryDashboardStatsView, VUnitControlDashboardStatsView, VDistributionDashboardStatsView, VPlanificationDashboardStatsView };\n","import * as React from \"react\";\nimport {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport {\n  IStatsDashboardState, ITempStudio,\n} from \"../../actions/statsDashboard.actions\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {IBaseVenue, IUser, IVenue} from \"../../../../../../src/app/interfaces\";\nimport {IStudio} from \"../../../../../../src/stats/interfaces/studio.interface\";\nimport {ErrorInfo} from \"react\";\nimport * as Raven from \"raven-js\";\nimport {connect} from \"react-redux\";\n\ninterface IPropsType {\n  dashboard: IStatsDashboardState;\n  users: IUser[];\n  types: any[];\n  changeTempStudioAction(studio: ITempStudio): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass StudioFormView extends React.Component<IPropsType, IStateType>{\n\n  readonly state = {\n    error: null,\n    selectedUsers: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount() {\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n\n    ($('#id-types') as any).chosen(chosenOptions).change((e: React.ChangeEvent<HTMLSelectElement>) => {\n      this.chooseType(e.target.value);\n    });\n\n    ($('#id-users') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addUser(e.target.value);\n      });\n  }\n\n\n\n  componentDidUpdate() {\n    $('#id-users').trigger('chosen:updated');\n    $('#id-types').trigger('chosen:updated');\n  }\n\n  private chooseType(type: string) {\n    const {changeTempStudioAction} = this.props;\n    const {tempStudio} = this.props.dashboard;\n    changeTempStudioAction({...tempStudio, type});\n  }\n\n  private addUser(id: string) {\n    let user = this.props.users.find((user: IUser) => user._id === id);\n    const {tempStudio} = this.props.dashboard;\n    let {users} = tempStudio;\n    if (user != undefined && !users.find((u: IUser) => u._id === user!!._id)) {\n      users.push(user);\n      this.props.changeTempStudioAction({\n          ...tempStudio,\n          users\n        }\n      )\n    }\n  }\n\n  private deleteUser(user: IUser){\n    const {tempStudio} = this.props.dashboard;\n    this.props.changeTempStudioAction({\n      ...tempStudio,\n      users: tempStudio.users.filter((u: IUser) => u._id !== user._id)\n      }\n    )\n  }\n\n  public render() {\n    const { changeTempStudioAction, users, types } = this.props;\n    const { tempStudio } = this.props.dashboard;\n\n    return (\n      <React.Fragment>\n        <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n          <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n        </ul>\n        <div className=\"tab-content\">\n          <div id=\"general\" className=\"tab-pane fade in active\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Nombre</label>\n                  <input\n                    type=\"text\"\n                    name=\"name\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempStudio ? tempStudio.name : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      name: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>URL</label>\n                  <input\n                    type=\"text\"\n                    name=\"embedURL\"\n                    className=\"form-control\"\n                    defaultValue={tempStudio ? tempStudio.embedURL : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      embedURL: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-types\">Tipo</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-types\"\n                    name=\"type\"\n                    defaultValue={tempStudio ? tempStudio.type : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      type: e.target.value})}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      types.map((type) => (\n                        <option key={type.id} value={type.id}>{type.name}</option>\n                      ))\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-users\">Usuarios</label>\n                  <select\n                    id=\"id-users\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      users.filter(user => !tempStudio.users.find(u => u._id == user._id)).map((user) => {\n                        return (\n                          <option key={user._id} value={user._id}>{user.firstName} {user.lastName}</option>\n                        );\n                      })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                  <tr>\n                    <th style={{width: '90%'}}>Name</th>\n                    <th style={{width: '10%'}}/>\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    tempStudio.users.length ? tempStudio.users.map((user: IUser) => {\n                        return (\n                          <tr key={user._id}>\n                            <td>{user.firstName} {user.lastName}</td>\n                            <td\n                              className=\"text-center text-red pointer\"\n                              onClick={() => this.deleteUser(user)}\n                            >\n                              <i className=\"fa fa-minus-circle\"/>\n                            </td>\n                          </tr>\n                        );\n                      }) :\n                      <tr>\n                        <td colSpan={2}>Aún no se han seleccionado usuarios.</td>\n                      </tr>\n                  }\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n        </div>\n      </React.Fragment>\n    );\n  }\n}\n\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(StudioFormView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\n\ninterface IPropsType {\n  car: any;\n  // increaseWarning(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass StockCarDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {car} = this.props;\n    return (\n      <tr className={car.created ? \"text-green\" : \"\"}>\n        <td style={{fontSize: \"12px\"}}>\n          {\n            car.hasWarnings && car.warning.vin ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"El vin debe tener al menos 17 dígitos.\"\n              /> : null\n          }{\n            car.created ?\n              <i\n                className=\"fa fa-plus-circle text-green pointer\"\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"Este vehículo se agregará al stock.\"\n              /> : null\n          } {car.vin}\n        </td>\n        <td style={{fontSize: \"12px\"}}>\n          {\n            car.hasWarnings && car.warning.patent ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"La patente debe tener al menos 6 dígitos.\"\n              /> : null\n          } {car.patent}\n        </td>\n        <td style={{fontSize: \"12px\"}}>{car.brand}</td>\n        <td style={{fontSize: \"12px\"}}>{car.denomination}</td>\n        <td style={{fontSize: \"12px\"}}>{car.type}</td>\n      </tr>\n    );\n  }\n}\n\nexport default StockCarDetail;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo, RefObject} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport {AxiosError, AxiosResponse} from \"axios\";\nimport {\n  getStockAction,\n  IStockState,\n  StockReducerAction\n} from \"../../actions/stock.actions\";\nimport ShowIf from \"../Utils/ShowIf\";\nimport StockVenueDetail from \"./StockVenueDetail\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<StockReducerAction>;\n  stock: IStockState;\n  getStockAction(): StockReducerAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  loadingSettings: boolean;\n  carsByVenue: any[];\n  totalCars: number;\n  createdCard: number;\n  deletedCard: number;\n  venues: any[];\n  loading: boolean;\n  sending: boolean;\n  file: File | null;\n}\n\nclass StockImportView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    loadingSettings: false,\n    carsByVenue:[],\n    venues: [],\n    totalCars: 0,\n    createdCard: 0,\n    deletedCard: 0,\n    loading: false,\n    sending: false,\n    file: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importar Stock';\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.getVenues = this.getVenues.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n    this.inputFile = React.createRef();\n  }\n\n  public componentWillMount() {\n    // set the title of the page\n    document.title = 'OSA Andes | Importar Stock';\n    this.getVenues();\n    this.props.getStockAction();\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, sending, loading, carsByVenue, totalCars, createdCard, deletedCard\n    } = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.4\" cAction=\"Importar\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Importar stock</h3>\n              <div className=\"pull-right box-tools\">\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  onClick={this.downloadTemplate}\n                >\n                  <i className=\"fa fa-fw fa-download\"/> Descargar Formato\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              {\n                carsByVenue.length ?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <div\n                      style={{\n                        backgroundColor: \"#f0f0f0\",\n                        padding: \"10px 10px 2px  10px\",\n                        marginBottom: \"10px\"\n                      }}>\n                        <p className=\"text-green\">\n                          <i className=\"fa fa-fw fa-plus-circle\"/> Se {createdCard > 1 ? \"agregarán\" : \"agregará\"} {createdCard} {createdCard > 1 ? \"unidades\" : \"unidad\"} al stock.\n                        </p>\n                        <p className=\"text-red\">\n                          <i className=\"fa fa-fw fa-minus-circle\" /> Se {deletedCard > 1 ? \"eliminarán\" : \"eliminará\"} {deletedCard} {deletedCard > 1 ? \"unidades\" : \"unidad\"} del stock.\n                        </p>\n                      </div>\n                    </div>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label>Configuración cargada</label>\n                        <div className=\"box-group\" id=\"accordion\" style={{margin: '2px 0 10px 0'}}>\n                          {\n                            carsByVenue.map((venue: any, index) => {\n                              return (\n                                <StockVenueDetail\n                                  index={index}\n                                  venue={venue}\n                                  key={venue.name}\n                                  deleteVenue={this.deleteVenue}\n                                />\n                              );\n                            })\n                          }\n                        </div>\n                      </div>\n                    </div>\n                    <div className=\"col-md-6\">\n                      <p><strong>Total de sucursales:</strong> {carsByVenue.length}</p>\n                      <p><strong>Total de unidades:</strong> {totalCars}</p>\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      {/*<button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile}>*/}\n                      {/*  <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración*/}\n                      {/*</button>*/}\n                    </div>\n                  </div> :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile}\n                accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n            </div>\n            <ShowIf condition={carsByVenue.length > 0}>\n              <div className=\"box-footer text-right\">\n                <button\n                  className=\"btn btn-sm btn-default\"\n                  onClick={() => this.props.history.push('/stock/')}\n                >\n                  Cancelar\n                </button>\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  style={{marginLeft: '5px'}}\n                  onClick={this.sendCreate}\n                  disabled={sending}\n                >\n                  {\n                    sending || loading ?\n                      <React.Fragment>\n                        <i className=\"fa fa-fw fa-spin fa-spinner\"/> Creando...\n                      </React.Fragment>\n                      : 'Crear'\n                  }\n                </button>\n              </div>\n            </ShowIf>\n            {\n              sending || loading || loadingSettings ?\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div> : null\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private deleteVenue(venueName: string): void {\n    const {carsByVenue} = this.state;\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal \"${venueName}\"`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.setState({\n          carsByVenue: carsByVenue.filter((venue: any) => venue.name !== venueName)\n        });\n      }\n    });\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private downloadTemplate(): void {\n    /* headers worksheet */\n    const data = [{\n      sucursal: '',\n      NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: ''\n    }];\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_stock_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    const {vinInStock} = this.props.stock;\n    const {venues} = this.state;\n    let createdCard = 0;\n    let totalCars = 0;\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        if (e.target) {\n          let data = e.target.result;\n          if (!rABS) {\n            data = new Uint8Array(data);\n          }\n          const workbook: XLSX.WorkBook = XLSX.read(data, {\n            type: rABS ? 'binary' : 'array'\n          });\n          const excelData = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n          const carsByVenue: any = {};\n          if (excelData.length >= 1) {\n            excelData.forEach((item: any) => {\n              if (item.hasOwnProperty('vin') && item.vin && item.hasOwnProperty('sucursal') && item.sucursal) {\n                totalCars++;\n                const vinWarning = item.vin.length < 17;\n                const patentWarning = item.patente && item.patente.length < 6;\n                const inStock = vinInStock.hasOwnProperty(item.vin.trim());\n                if(!inStock){\n                  createdCard++;\n                }\n                const car = {\n                  vin: item.vin.trim(),\n                  internalNumber: item.NInterno ? item.NInterno.trim() : '',\n                  color: item.color ? item.color.trim() : '',\n                  denomination: item.denominacion ? item.denominacion.trim() : '',\n                  brand: item.marca ? item.marca.trim() : '',\n                  patent: item.patente ? item.patente.trim() : '',\n                  property: item.propiedad ? item.propiedad.trim().toUpperCase() : '',\n                  type: item.tipo ? item.tipo.trim() : '',\n                  hasWarnings: vinWarning || patentWarning,\n                  created: !inStock,\n                  warning: {\n                    vin: vinWarning,\n                    patent: patentWarning\n                  }\n                };\n                if (!carsByVenue.hasOwnProperty(item.sucursal)) {\n                  carsByVenue[item.sucursal] = {\n                    cars: []\n                  };\n                }\n                carsByVenue[item.sucursal].cars.push(car);\n              } else {\n                /* tslint:disable:no-console */\n                console.log('Error en linea:');\n                console.log(item.__rowNum__);\n              }\n            });\n            const carsByVenueArray: any[] = [];\n            for (const cv in carsByVenue) {\n              if (carsByVenue.hasOwnProperty(cv)) {\n                const existVenue = venues.length ? venues.some((venue: any) => {\n                  return venue.name.trim().toLowerCase() === cv.trim().toLowerCase()\n                }) : false;\n                carsByVenueArray.push({\n                  name: cv.trim(),\n                  warningNoExist: !existVenue,\n                  cars: carsByVenue[cv].cars.sort((x: any, y: any) => {\n                    return (x.hasWarnings === y.hasWarnings) ? 0 : x.hasWarnings ? -1 : 1;\n                  })\n                });\n              }\n            }\n            this.setState({\n              file,\n              createdCard,\n              deletedCard: (Object.keys(vinInStock).length  - (totalCars- createdCard)),\n              totalCars,\n              carsByVenue: carsByVenueArray,\n              loadingSettings: false\n            });\n          } else {\n            swal(\n              'Importador de configuración',\n              `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n              'error'\n            );\n            this.setState({\n              loadingSettings: false\n            });\n          }\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    } else {\n      swal('Importador de configuración', 'Este archivo no cumple con los requisitos mínimos o no tiene autos.', 'error');\n      this.setState({\n        loadingSettings: false\n      });\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private getVenues(){\n    this.setState({loading: true});\n    const api: ApiService = new ApiService();\n    api.getVenues({ page: 1, pageSize: 200 })\n      .then((response: AxiosResponse):void =>{\n        this.setState({\n          venues: response.data.results,\n          loading: false\n        });\n      })\n    .catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  }\n\n  private sendCreate(): void {\n    const {carsByVenue, totalCars, file} = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    if (!totalCars) {\n      swal('Importación de stock', 'No se ha importado la configuración o no contiene sucursales.', 'error');\n      this.setState({\n        sending: false\n      });\n    } else if (file) {\n      const api = new ApiService();\n      api.getSource();\n      api\n        .loadStock({\n          carsByVenue\n        })\n        .then((response: any) => {\n          const { message } = response.data;\n          setTimeout(() => {\n            swal('Importación de stock', message, 'success');\n          }, 200);\n          history.push('/stock/');\n          this.setState({\n            sending: false\n          });\n        })\n        .catch((e) => {\n          console.log('e', e);\n          swal('Importación de stock', 'Se produjo un error al cargar el stock.', 'error');\n          this.setState({\n            sending: false\n          });\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { stock: IStockState }) => {\n  return {\n    stock: state.stock\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getStockAction: () => dispatch(getStockAction()),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(StockImportView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport * as moment from 'moment-timezone';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport {\n  changeFilter,\n  changeFilterText,\n  getStockAction,\n  IStockState,\n  StockReducerAction\n} from \"../../actions/stock.actions\";\nimport filterFactory from \"react-bootstrap-table2-filter\";\nimport paginationFactory from \"react-bootstrap-table2-paginator\";\nimport BootstrapTable from \"react-bootstrap-table-next\";\nimport * as XLSX from \"xlsx\";\nimport BootstrapSelect from \"../Utils/BootstrapSelect\";\nimport Row from \"../Utils/Row\";\nimport {IFilterStock} from \"../../reducers/stock.reducer\";\nimport ShowIf from \"../Utils/ShowIf\";\nimport ImageLazyLoad from \"../Utils/ImageLazyLoad\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {hasPermission} from \"../../utils/common\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  dispatch: Dispatch<StockReducerAction>;\n  stock: IStockState;\n\n  getStockAction(): StockReducerAction;\n\n  changeFilter(filter: IFilterStock): StockReducerAction;\n\n  changeFilterText(filter: IFilterStock): StockReducerAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\n\nclass StockView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private paginationOption: any = {\n    paginationSize: 4,\n    showTotal: true,\n    paginationTotalRenderer: this.customTotal,\n    sizePerPageList: [{\n      text: '20', value: 20\n    },{\n      text: '50', value: 50\n    }, {\n      text: '100', value: 100\n    }, {\n      text: '200', value: 200\n    }],\n    onPageChange: () => {\n      window.scrollTo(0, 0);\n      setTimeout(() => {\n        $('[data-toggle=\"tooltip\"]').tooltip();\n      }, 200);\n    }\n  };\n\n  private socket: Socket;\n\n  readonly columns: any[] = [];\n\n  readonly defaultSorted = [{\n    dataField: 'status',\n    order: 'asc'\n  }];\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Stock Actual';\n    this.xlsExport = this.xlsExport.bind(this);\n    this.daysInVenue = this.daysInVenue.bind(this);\n    this.repcetionVenue = this.repcetionVenue.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllBrands = this.filterAllBrands.bind(this);\n    this.filterBrands = this.filterBrands.bind(this);\n    this.filterAllDenominations = this.filterAllDenominations.bind(this);\n    this.filterDenominations = this.filterDenominations.bind(this);\n    this.filterAllColors = this.filterAllColors.bind(this);\n    this.filterColors = this.filterColors.bind(this);\n    this.filterType = this.filterType.bind(this);\n    this.venueFormatter = this.venueFormatter.bind(this);\n    this.filterProperty = this.filterProperty.bind(this);\n    this.handleChangeSearchText = this.handleChangeSearchText.bind(this);\n    this.clearFilter = this.clearFilter.bind(this);\n    this.columns = [{\n      dataField: 'vin',\n      text: 'VIN',\n      // formatter: this.brandFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'internalNumber',\n      text: 'Nº Interno',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'brand',\n      text: 'Marca',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'denomination',\n      text: 'Modelo',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'color',\n      text: 'Color',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'venueFound',\n      text: 'Sucursal',\n      formatter: this.venueFormatter,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'receptionVenue',\n      text: 'Fecha Recepción',\n      formatter: this.repcetionVenue,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'daysInVenue',\n      text: 'Días en Sucursal',\n      formatter: this.daysInVenue,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }];\n  }\n\n  public componentWillMount(): void {\n    this.props.getStockAction();\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `stock-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        this.props.getStockAction();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.stock.source) {\n      this.props.stock.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    $('.react-bootstrap-table-pagination')\n      .css({padding: '3px 15px'});\n    $('.react-bootstrap-table-pagination div')\n      .removeClass('col-xs-6')\n      .addClass('col-xs-12')\n      .css({padding: '3px 15px'});\n    $('.react-bootstrap-table-pagination div:last-child')\n      .removeClass('text-right')\n      .addClass('text-right');\n    $('#pageDropDown')\n      .removeClass('btn-sm')\n      .addClass('btn-sm');\n    $('.bs-searchbox input')\n      .removeClass('input-sm')\n      .addClass('input-sm');\n    $('.pagination')\n      .removeClass('pagination-sm')\n      .addClass('pagination-sm')\n      .css({margin: 0});\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, carsTable, dataFilters, filter, searching, message} = this.props.stock;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.4\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Stock Actual</h3>\n              <ShowIf condition={!loading && message.length < 1}>\n                {\n                  hasPermission(window.user, 'importStock') ?\n                    <div className=\"box-tools pull-right\">\n                      <button\n                        className=\"btn btn-sm btn-primary  hidden-xs\"\n                        onClick={() => this.props.history.push(`/stock/import/`)}\n                      >\n                        <i className=\"fa fa-fw fa-cloud-upload\"/> Importar\n                      </button>\n                    </div> : null\n                }\n              </ShowIf>\n            </div>\n            <div className=\"box-body no-padding\">\n              <ShowIf condition={message.length > 1}>\n                <p className=\"text-center text-muted\" style={{paddingBottom: \"10px\"}}>\n                  <ImageLazyLoad\n                    url=\"/images/not_found.png\"\n                    height={'200px'}\n                    style={{\n                      opacity: 0.5,\n                      maxHeight: '200px',\n                      marginBottom: '20px',\n                      marginTop: '35x'\n                    }}\n                    replaceLoading={\n                      <i\n                      className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                      style={{padding: '30px'}}\n                      />\n                    }\n                  /><br/>\n                  <strong>{message}</strong>\n                </p>\n              </ShowIf>\n              <ShowIf condition={!loading && message.length < 1}>\n                <React.Fragment>\n                  <div className=\"row\" style={{margin: '5px 0'}}>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"cars\" className=\"control-label\">Buscador</label>\n                        <input\n                          type=\"text\"\n                          className=\"form-control\"\n                          id=\"cars\"\n                          placeholder=\"Busca por VIN, Nº interno, patente, marca o modelo.\"\n                          onChange={this.handleChangeSearchText}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"venues\" className=\"control-label\">Sucursales</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"sucursales seleccionadas.\"\n                          selected={filter.venues}\n                          allOption={true}\n                          selectAll={this.filterAllVenues}\n                          options={dataFilters.venues.map(venue => ({\n                            value: venue._id,\n                            text: venue.name\n                          }))}\n                          onClick={this.filterVenues}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"types\" className=\"control-label\">Tipo</label>\n                          <BootstrapSelect\n                            noneSelectedText=\"Todos\"\n                            displayItems={4}\n                            selectedText=\"estados seleccionados.\"\n                            separator=\" - \"\n                            options={dataFilters.types\n                              .map((type) => ({\n                                value: type,\n                                text: type\n                              }))}\n                            selected={[filter.type]}\n                            autoClouse={true}\n                            onClick={this.filterType}\n                          />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"properties\" className=\"control-label\">Propiedad</label>\n                          <BootstrapSelect\n                            noneSelectedText=\"Todos\"\n                            displayItems={4}\n                            selectedText=\"estados seleccionados.\"\n                            separator=\" - \"\n                            options={dataFilters.properties\n                              .map((property) => ({\n                                value: property,\n                                text: property\n                              }))}\n                            selected={[filter.property]}\n                            autoClouse={true}\n                            onClick={this.filterProperty}\n                          />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"brands\" className=\"control-label\">Marca</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"marcas seleccionadas.\"\n                          selected={filter.brands}\n                          allOption={true}\n                          selectAll={this.filterAllBrands}\n                          options={dataFilters.brands.map(brand => ({\n                            value: brand,\n                            text: brand\n                          }))}\n                          onClick={this.filterBrands}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"denominations\" className=\"control-label\">Modelo</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"modelos seleccionadas.\"\n                          selected={filter.denominations}\n                          allOption={true}\n                          selectAll={this.filterAllDenominations}\n                          options={dataFilters.denominations.map(denomination => ({\n                            value: denomination,\n                            text: denomination\n                          }))}\n                          onClick={this.filterDenominations}\n                        />\n                      </div>\n                    </div>\n                     <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"denominations\" className=\"control-label\">Color</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"colores seleccionadas.\"\n                          selected={filter.colors}\n                          allOption={true}\n                          selectAll={this.filterAllColors}\n                          options={dataFilters.colors.map(color => ({\n                            value: color,\n                            text: color\n                          }))}\n                          onClick={this.filterColors}\n                        />\n                      </div>\n                    </div>\n                  </div>\n                  <Row style={{margin: '5px 0'}}>\n                    <div\n                      className=\"col-md-6 col-md-push-6 text-right\"\n                      style={{marginBottom: '10px'}}\n                    >\n                      <button\n                        className=\"btn btn-default btn-sm\"\n                        onClick={this.clearFilter}\n                        disabled={!searching}\n                      >\n                        <i className=\"fa fa-fw fa-eraser\"/> Limpiar Filtros\n                      </button>\n                      <button\n                        className=\"btn btn-sm btn-primary hidden-xs hidden-sm\"\n                        onClick={this.xlsExport}\n                        style={{marginLeft: '5px'}}\n                      >\n                        <i className=\"fa fa-fw fa-download\"/> Exportar Excel\n                      </button>\n                    </div>\n                  </Row>\n                </React.Fragment>\n              </ShowIf>\n              <ShowIf condition={carsTable.length > 0 && !loading}>\n                <div className=\"stock-table\">\n                  <BootstrapTable\n                    keyField=\"_id\"\n                    data={carsTable}\n                    columns={this.columns}\n                    filter={filterFactory()}\n                    pagination={paginationFactory(this.paginationOption)}\n                    defaultSorted={this.defaultSorted}\n                  />\n                </div>\n              </ShowIf>\n              <ShowIf condition={searching && carsTable.length < 1 && !loading}>\n                <p className=\"text-center text-muted\">\n                  <ImageLazyLoad\n                    url=\"/images/not_found.png\"\n                    height={'200px'}\n                    style={{\n                      opacity: 0.5,\n                      maxHeight: '200px',\n                      marginBottom: '10px'\n                    }}\n                    replaceLoading={\n                      <i\n                      className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                      style={{padding: '30px'}}\n                      />\n                    }\n                  /><br/>\n                  <strong>No hay información para mostrar</strong>\n                </p>\n              </ShowIf>\n            </div>\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private handleChangeSearchText(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    const {filter} = this.props.stock;\n    this.props.changeFilterText({\n      ...filter,\n      text: value ? e.target.value : ''\n    });\n  }\n\n  private filterAllVenues(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      venues: value ? dataFilters.venues.map((venue: any) => venue._id) : []\n    });\n  }\n\n  private filterVenues(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      venues: filter.venues.includes(value)\n        ? filter.venues.filter((venue) => venue !== value)\n        : [value, ...filter.venues]\n    });\n  }\n\n  private filterAllBrands(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      brands: value ? dataFilters.brands.map((brand: any) => brand) : []\n    });\n  }\n\n  private filterBrands(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      brands: filter.brands.includes(value)\n        ? filter.brands.filter((brand) => brand !== value)\n        : [value, ...filter.brands]\n    });\n  }\n\n  private filterAllDenominations(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      denominations: value ? dataFilters.denominations.map((denomination: any) => denomination) : []\n    });\n  }\n\n  private filterDenominations(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      denominations: filter.denominations.includes(value)\n        ? filter.denominations.filter((denomination) => denomination !== value)\n        : [value, ...filter.denominations]\n    });\n  }\n\n  private filterAllColors(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      colors: value ? dataFilters.colors.map((color: any) => color) : []\n    });\n  }\n\n  private filterColors(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      colors: filter.colors.includes(value)\n        ? filter.colors.filter((color) => color !== value)\n        : [value, ...filter.colors]\n    });\n  }\n\n  private filterType(value: string): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      type: filter.type !== value ? value : ''\n    });\n  }\n\n  private filterProperty(value: string): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      property: filter.property !== value ? value : ''\n    });\n  }\n\n  private clearFilter(): void {\n    this.props.changeFilter({\n      venues: [],\n      colors: [],\n      brands: [],\n      denominations: [],\n      property: '',\n      type: '',\n      text: ''\n    });\n    $('#cars').val('');\n  }\n\n  private xlsExport(): void {\n    this.trackClick(\"Exportar\");\n    const {cars} = this.props.stock;\n    const data: any = [];\n    // order data\n    if (cars.length) {\n      for (const car of cars) {\n        data.push({\n          VIN: car.car.vin,\n          Patente: car.car.patent && car.car.patent.length ? car.car.patent : '-',\n          ['Nº interno']: car.car.internalNumber && car.car.internalNumber.length ? car.car.internalNumber : '-',\n          Marca: car.car.brand && car.car.brand.length ? car.car.brand : '-',\n          ['Denominación']: car.car.denomination && car.car.denomination.length ? car.car.denomination : '-',\n          Color: car.car.color && car.car.color.length ? car.car.color : '-',\n          Tipo: car.car.type && car.car.type ? car.car.type : '-',\n          Propiedad: car.car.property && car.car.property ? car.car.property : '-',\n          Sucursal: car.venueFound && car.venueFound.hasOwnProperty('name') ? car.venueFound.name : '-',\n        });\n      }\n    }\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Detalle');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, `Stock ${moment().format('YYYYMMDD')}.xlsx`);\n  }\n\n  private customTotal(from: any, to: any, size: any) {\n    return(\n      <span className=\"react-bootstrap-table-pagination-total text-ellipsis\" style={{fontSize: '75%'}}>\n        &nbsp;&nbsp;Mostrando registros del {from} al {to} de {size} registros.\n      </span>\n    );\n  }\n\n  private daysInVenue(cell: string, row: any) {\n    return row.daysInVenue ?? '-'\n  }\n\n  private repcetionVenue(cell: string, row: any) {\n    return row.receptionVenue ? moment(row.receptionVenue).format('L')  : '-'\n  }\n\n  private venueFormatter(cell: string, row: any) {\n    return row.venueFound !== \"-\" ? row.venueFound : row.venue;\n  }\n}\n\nconst mapStateToProps = (state: { stock: IStockState }) => {\n  return {\n    stock: state.stock\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getStockAction: () => dispatch(getStockAction()),\n    changeFilter: (filter: IFilterStock) => dispatch(changeFilter(filter)),\n    changeFilterText: (filter: IFilterStock) => dispatch(changeFilterText(filter)),\n  };\n};\n\nexport default connect<{ stock: IStockState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(StockView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport slugify from 'slugify';\nimport StockCarDetail from './StockCarDetail';\n\ninterface IPropsType {\n  venue: any;\n  index: number;\n\n  deleteVenue(venueName: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass StockVenueDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {venue, index} = this.props;\n    const warnings = venue.cars.filter((car: any) => car.hasWarnings).length;\n    const created = venue.cars.filter((car: any) => car.created).length;\n    return (\n      <div className=\"panel box box-default\" style={{borderTopWidth: '2px'}}>\n        <div className=\"box-header with-border\" style={{padding: '10px 6px'}}>\n          <h4 className=\"box-title\" style={{\n            fontSize: '15px',\n            display: 'block'\n          }}>\n            <a data-toggle=\"collapse\"\n               data-parent=\"#accordion\"\n               href={`#${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`}\n               aria-expanded=\"false\"\n               className=\"collapsed\">\n              {index + 1} {venue.name} ({venue.cars.length} Unidades)\n\n            {/*<i*/}\n            {/*  className=\"fa fa-minus-circle text-red pull-right pointer\"*/}\n            {/*  onClick={() => this.props.deleteVenue(venue.name)}*/}\n            {/*/>*/}\n            {\n              venue.warningNoExist ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> Esta sucursal se creará.\n                </span> : null\n            }\n            {\n              warnings ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> {warnings} alertas.\n                </span> : null\n            }\n            {\n              created ?\n                <span className=\"text-muted  text-green pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-plus-circle text-green\"/> {created} {created > 1 ? \"unidades\" : \"unidad\"}.\n                </span> : null\n            }\n            </a>\n          </h4>\n        </div>\n        <div\n          id={`${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`}\n          className=\"panel-collapse collapse\"\n          aria-expanded=\"false\"\n        >\n          <div className=\"box-body no-padding\">\n            <table className=\"table table-striped\">\n              <thead>\n              <tr>\n                <th style={{width: '18%'}}>VIN</th>\n                <th style={{width: '10%'}}>PATENTE</th>\n                <th style={{width: '15%'}}>MARCA</th>\n                <th>DENOMINACION</th>\n                <th style={{width: '15%'}}>TIPO</th>\n              </tr>\n              </thead>\n              <tbody>\n              {\n                venue.cars.map((car: any, index: any) => {\n                  return (\n                    <StockCarDetail car={car} key={index}/>\n                  );\n                })\n              }\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default StockVenueDetail;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { Dispatch, ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport TransmittalActions from '../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../actions/transmittal.types';\nimport TransmittalForm from './TransmittalForms/TransmittalForm';\nimport ShowIf from '../Utils/ShowIf';\nimport ApiService from '../../utils/axios';\nimport { AxiosError, AxiosResponse } from 'axios';\nimport * as swal from 'sweetalert';\nimport { imageStatus } from '../Utils/MultiUploadFiles';\nimport { ITransmittal } from '../../../../../../src/distribution/interfaces/transmittal.interface';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loading: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass TransmittalCreateView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    loading: false\n  };\n\n  private socket: Socket;\n\n  private readonly api: ApiService;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Crear orden de transporte';\n    this.processForm = this.processForm.bind(this);\n    this.cancel = this.cancel.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentWillMount(): void {\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `distribution-create-${window.user.team._id}`\n      });\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `distribution-create-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalActions } = this.props;\n    const { loading } = this.props.transmittal;\n\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.4' cAction='Crear Order'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Crear orden de transporte</h3>\n            </div>\n            <div className='box-body'>\n              <TransmittalForm\n                initialValues={{\n                  files: [],\n                  items: []\n                }}\n                onSubmit={this.processForm}\n              />\n            </div>\n            <div className='box-footer text-right'>\n              <button\n                type='button'\n                className='btn btn-sm btn-default'\n                onClick={this.cancel}\n              >\n                Cancelar\n              </button>\n              <button\n                type='button'\n                className='btn btn-sm btn-primary'\n                disabled={this.state.loading}\n                style={{ marginLeft: '5px' }}\n                onClick={() => transmittalActions.submit('transmittalForm')}\n              >\n                <ShowIf condition={this.state.loading}>\n                  <i className='fa fa-spinner fa-spin ' />\n                </ShowIf> Crear\n              </button>\n            </div>\n            <ShowIf condition={loading || this.state.loading}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private cancel(): void {\n    this.props.history.push('/transmittals/');\n  }\n\n  private processForm(data: ITransmittal) {\n    const { history } = this.props;\n    const isUploadingFiles = data.files?.filter((file: any) => file.status !== imageStatus.complete).length;\n    const hasItemsLoaded = data.items?.length >= 1;\n    if (isUploadingFiles) {\n      swal!('Orden de transporte', 'Aún se estan cargando archivos, espera que terminen para enviar.', 'error');\n    } else if (!hasItemsLoaded) {\n      swal!('Orden de transporte', 'Debes agregar al menos un vehículo para poder crear una order.', 'error');\n    } else {\n      this.setState({ loading: true });\n      this.api.createTransmittals({\n        ...data,\n        items: data.items.map((item) => ({\n          ...item,\n          request: item.request?._id,\n          requestItem: (item as any).type === 'request' ? item?._id : null\n        })),\n        files: data.files.map((file) => file._id)\n      })\n        .then((response: AxiosResponse): void => {\n          swal('Orden de transporte', 'Se ha creado satisfactoriamente.', 'success')\n            .then(() => {\n              this.setState({ loading: false });\n              history.push('/transmittals/');\n            });\n        })\n        .catch((err: AxiosError): void => {\n          this.setState({ loading: false });\n          this.api.errorHandler(err);\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(TransmittalCreateView);\n","import * as React from 'react';\nimport ShowIf from '../../Utils/ShowIf';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport SearchCarInRequests from './SearchCarInRequest';\nimport SearchCarInCars from './SearchCarInCars';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { hasPermission } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\n\ntype Tabs = 'cars' | 'requests'\n\ninterface IPropsType {\n  fields?: FieldArrayFieldsProps<any>;\n  slimView?: boolean;\n\n  onClickRequest(item: IRequestItem): void;\n\n  onClickCar(car: ICar): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tab: Tabs;\n}\n\ndeclare let window: IWindow;\n\n\nclass AddItemsToTransmittal extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    tab: 'requests'\n  };\n\n  public render(): React.ReactElement<IPropsType> {\n    const { tab } = this.state;\n    const { fields, onClickRequest, onClickCar, slimView } = this.props;\n    return (\n      <div>\n        <ShowIf condition={hasPermission(window.user, 'addCarOnTransmittal')}>\n          <ul className='nav nav-pills nav-justified' style={{ marginTop: '10px', marginBottom: '10px', border: '1px solid #f4f4f4' }}>\n            <li className={tab === 'requests' ? 'active' : ''}>\n              <a\n                className={tab === 'requests' ? 'background-transition' : ''}\n                href='javascript:void(0);'\n                style={{ borderTop: '0', marginBottom: '0' }}\n                onClick={() => this.changeTab('requests')}\n              >Solicitudes</a>\n            </li>\n            <li className={tab === 'cars' ? 'active' : ''}>\n              <a\n                href='javascript:void(0);'\n                className={tab === 'cars' ? 'background-transition' : ''}\n                style={{ borderTop: '0', marginBottom: '0' }}\n                onClick={() => this.changeTab('cars')}\n              >Unidades</a>\n            </li>\n          </ul>\n        </ShowIf>\n        <ShowIf condition={tab === 'requests'}>\n          <SearchCarInRequests fields={fields!} onClick={onClickRequest} slimView={slimView} />\n        </ShowIf>\n        <ShowIf condition={tab === 'cars'}>\n          <SearchCarInCars fields={fields!} slimView={slimView} onClick={onClickCar} />\n        </ShowIf>\n      </div>\n    );\n  }\n\n  private changeTab(tab: Tabs) {\n    this.setState({\n      tab\n    });\n  }\n}\n\nexport default AddItemsToTransmittal;\n\n\n","import { Dispatch } from 'redux';\nimport * as React from 'react';\nimport { CarReduxAction, getCarsAction, ICarsState } from '../../../actions/cars.actions';\nimport { connect } from 'react-redux';\nimport { debounce } from 'throttle-debounce';\nimport Paginator from '../../Utils/Paginator';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\n\ninterface IExternarlPropsType {\n  slimView?: boolean\n  fields?: FieldArrayFieldsProps<any>;\n  onClick(item: ICar): void;\n}\n\ninterface IPropsType  extends IExternarlPropsType {\n  dispatch: Dispatch<CarReduxAction>;\n  cars: ICarsState;\n\n  getCarsAction(page: number, search?: string): CarReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n}\n\n\nclass SearchCarInCars extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    searchText: ''\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  public componentWillMount() {\n    const { pagination } = this.props.cars;\n    this.props.getCarsAction(pagination.page);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, cars, pagination } = this.props.cars;\n    const { slimView, onClick, fields } = this.props;\n    const addedItems = fields?.getAll() ? fields.getAll().map(field => field.car.vin) : [];\n    return (\n      <div className='row'>\n        <div className='col-md-12'>\n          <div className='table-container-overlay'>\n            <div className='row'>\n              <div className='col-md-12'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Vehículo\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Busca por VIN, marca, modelo o material.'\n                    onChange={this.onChangeSearch}\n                  />\n                </div>\n              </div>\n              <div className='col-md-12'>\n                <div className='table-responsive'>\n                  <table className='table table-xs table-hover' style={!slimView ? { minWidth: '1000px' } : {}}>\n                  <thead>\n                  <tr className='bg-primary' style={{ height: '45px' }}>\n                    <th className='middle' style={{ width: '120px' }}>VIN</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle'> Vehículo</th>\n                          <th className='middle'> Color</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle'>Marca</th>\n                          <th className='middle'>Modelo</th>\n                          <th className='middle'>Color</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '28px' }} />\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    cars\n                      .filter(item => !addedItems.includes(item.vin))\n                      .map((car) => {\n                      return (\n                        <tr key={car._id}>\n                          <td className='middle' style={{ width: '120px' }}>{car.vin}</td>\n                          {\n                            slimView ?\n                              <React.Fragment>\n                                <td className='middle'>\n                                  <strong>{car?.brand}</strong> {car?.denomination}\n                                </td>\n                                <td className='middle'>\n                                  {car?.color}\n                                </td>\n                              </React.Fragment>\n                              : <React.Fragment>\n                                <td className='middle'>{car.brand}</td>\n                                <td className='middle'>{car.denomination}</td>\n                                <td className='middle'>{car.color}</td>\n                              </React.Fragment>\n                          }\n                          <td className='middle'>\n                            <a\n                              className='btn btn-success btn-xs'\n                              href={'javascript:void(0);'}\n                              onClick={() => onClick(car)}\n                            >\n                              <i className='fa fa-plus' /> Agregar\n                            </a>\n                          </td>\n                        </tr>\n                      );\n                    })\n                  }\n                  </tbody>\n                </table>\n                </div>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='row'>\n                <div className='col-md-6' style={{ padding: '20px 15px' }}>\n              <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n              </span>\n                </div>\n                <div className='col-md-6'>\n                  <div className='text-right' style={{ marginRight: '15px' }}>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                </div>\n              </div>\n            }\n          </div>\n          {\n            loading &&\n            <div className='overlay' style={{\n              position: 'absolute',\n              top: 0,\n              left: 0,\n              height: '100%',\n              width: '100%',\n              zIndex: 50,\n              background: 'rgba(255,255,255,0.7)'\n            }}>\n              <i className='fa fa-spinner fa-spin text-purple' style={{\n                position: 'absolute',\n                top: '50%',\n                left: '50%',\n                marginLeft: '-15px',\n                marginTop: '-15px',\n                color: '#000',\n                fontSize: '30px'\n              }} />\n            </div>\n          }\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.setState({\n      searchText: value\n    });\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const { searchText } = this.state;\n    if (searchText && searchText.length) {\n      this.props.getCarsAction(1, searchText);\n    } else {\n      this.props.getCarsAction(1);\n    }\n  }\n\n  private changePage(page: number): void {\n    const { searchText } = this.state;\n    this.props.getCarsAction(page, searchText);\n  }\n}\n\nconst mapStateToProps = (state: { cars: ICarsState }) => {\n  return {\n    cars: state.cars\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getCarsAction: (page: number, search?: string) => dispatch(getCarsAction(page, search))\n  };\n};\n\nexport default connect<{}, {}, IExternarlPropsType | any>(mapStateToProps, mapDispatchToProps)(SearchCarInCars);\n\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as moment from 'moment-timezone';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { Dispatch } from 'redux';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\nimport Paginator from '../../Utils/Paginator';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport { debounce } from 'throttle-debounce';\nimport { IUser } from '../../../../../../../src/app/interfaces/user.interface';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { IWindow } from '../../../interfaces/window';\nimport ShowIf from '../../Utils/ShowIf';\n\n\ninterface IExternarlPropsType {\n  fields?: FieldArrayFieldsProps<any>;\n  slimView?: boolean;\n\n  onClick(item: IRequestItem): void;\n}\n\ninterface IPropsType extends RouteComponentProps<{}>, IExternarlPropsType {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass SearchCarInRequests extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changePage = this.changePage.bind(this);\n    this.getRequestItemDebounced = debounce(800, this.getRequestItemDebounced.bind(this));\n  }\n\n  public componentWillMount(): void {\n    this.props.transmittalActions.getRequestItemThunkAction(1);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `transmittal-list-${window.user.team._id}`\n      });\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL_ITEM', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL_ITEM', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n    this.socket.on('DELETE_TRANSMITTAL', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n  }\n\n  public componentWillUnmount(): void {\n    //cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalActions, transmittal, fields, slimView } = this.props;\n    const { requestItems, requestItemsfilters, requestItemsPagination, requestItemsLoading } = transmittal;\n    const addedItems = fields?.getAll() ? fields.getAll().map(field => field._id) : [];\n    return (\n      <div className='row'>\n        <div className='col-md-12'>\n          <div className='table-container-overlay'>\n            <div className='row'>\n              <div className='col-md-8'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Vehículo\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Busca por VIN, marca, modelo, material o nº de solicitud.'\n                    defaultValue={requestItemsfilters.text}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('text', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-2'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Nº Solicitudes\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Nº de solicitudes ejemplo: 2, 8, 10'\n                    defaultValue={requestItemsfilters.request}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('request', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-2'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Partida\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Nº de partida ejemplo: J-2136'\n                    defaultValue={requestItemsfilters.entry}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('entry', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-12'>\n                <div className='table-responsive'>\n                  <table className='table table-xs table-hover' style={!slimView ? { minWidth: '1000px' } : {}}>\n                  <thead>\n                  <tr className='bg-primary' style={{ height: '45px' }}>\n                    <th className='middle-center' style={{ width: '45px' }}>ID Sol.</th>\n                    <th className='middle' style={{ width: '120px' }}>VIN</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle'> Vehículo</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle'>Marca</th>\n                          <th className='middle'>Modelo</th>\n                          <th className='middle'>Color</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '100px' }}>Partida</th>\n                    <th className='middle' style={{ width: '100px' }}>Factura</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle' style={{ width: '150px' }}>Solicitante</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle' style={{ width: '150px' }}>Solicitante</th>\n                          <th className='middle' style={{ width: '150px' }}>Origen</th>\n                          <th className='middle' style={{ width: '150px' }}>Destino</th>\n                          <th className='middle' style={{ width: '100px' }}>Fecha</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '28px' }} />\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    requestItems\n                      .filter(item => !addedItems.includes(item._id))\n                      .map((item) => {\n                        return (\n                          <tr key={item._id}>\n                            <td className={`middle-center`}>\n                              #{item.request?.number}\n                            </td>\n                            <td className={`middle`}>\n                              {item.car?.vin}\n                            </td>\n                            {\n                              slimView ?\n                                <React.Fragment>\n                                  <td className='middle'>\n                                    <strong>{item.car?.brand}</strong> {item.car?.denomination}< br />\n                                    {item.car?.color}\n                                  </td>\n                                </React.Fragment> :\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {item.car?.brand}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.car?.denomination}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.car?.color}\n                                  </td>\n                                </React.Fragment>\n                            }\n\n                            <td className={`middle`}>\n                              {item.car?.entry ?? '-'}\n                            </td>\n                            <td className={`middle`}>\n                              {item.car?.invoice ?? '-'}\n                            </td>\n                            {\n                              slimView ?\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {this.createdBy(item.request?.createdBy) ?? '-'}<br />\n                                    {moment(item.request?.createdAt).format('DD/MM/YY') ?? '-'}\n                                  </td>\n                                </React.Fragment> :\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {this.createdBy(item.request?.createdBy) ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.origin?.name ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.destination?.name ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {moment(item.request?.createdAt).format('DD/MM/YY') ?? '-'}\n                                  </td>\n                                </React.Fragment>\n                            }\n                            <td className={`middle`}>\n                              <ShowIf condition={!!item.car?.vin?.trim()}>\n                                <a\n                                  className='btn btn-success btn-xs'\n                                  href={'javascript:void(0);'}\n                                  onClick={() => this.props.onClick(item)}\n                                >\n                                  <i className='fa fa-plus' /> Agregar\n                                </a>\n                              </ShowIf>\n                            </td>\n                          </tr>\n                        );\n                      })\n                  }\n                  </tbody>\n                </table>\n                </div>\n              </div>\n            </div>\n            {\n              requestItemsPagination.pages > 1 &&\n              <div className='row'>\n                <div className='col-md-6' style={{ padding: '20px 15px' }}>\n              <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                &nbsp;&nbsp;Mostrando registros del {(requestItemsPagination.page - 1) * 20 + 1} al {(requestItemsPagination.page) * 20} de {requestItemsPagination.count} registros.\n              </span>\n                </div>\n                <div className='col-md-6'>\n                  <div className='text-right' style={{ marginRight: '15px' }}>\n                    <Paginator changePage={this.changePage} page={requestItemsPagination.page} pages={requestItemsPagination.pages} />\n                  </div>\n                </div>\n              </div>\n            }\n          </div>\n          {\n            requestItemsLoading &&\n            <div className='overlay' style={{\n              position: 'absolute',\n              top: 0,\n              left: 0,\n              height: '100%',\n              width: '100%',\n              zIndex: 50,\n              background: 'rgba(255,255,255,0.7)'\n            }}>\n              <i className='fa fa-spinner fa-spin text-purple' style={{\n                position: 'absolute',\n                top: '50%',\n                left: '50%',\n                marginLeft: '-15px',\n                marginTop: '-15px',\n                color: '#000',\n                fontSize: '30px'\n              }} />\n            </div>\n          }\n        </div>\n      </div>\n    );\n  }\n\n  private createdBy(createdBy: IUser): string | null {\n    return createdBy ? `${createdBy.firstName} ${createdBy.lastName}` : null;\n  }\n\n  private getRequestItemDebounced() {\n    this.props.transmittalActions.getRequestItemThunkAction(1, false);\n  }\n\n  private changePage(page: number): void {\n    // window.scrollTo(0, 0);\n    this.props.transmittalActions.getRequestItemThunkAction(page);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IExternarlPropsType | any>(mapStateToProps, mapDispatchToProps)(SearchCarInRequests);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {Field, FieldArray, formValueSelector, InjectedFormProps, reduxForm} from 'redux-form';\nimport {ITransmittalState} from '../../../actions/transmittal.types';\nimport InputField from '../../Utils/forms/InputField';\nimport {inputStringRequired} from '../../Utils/forms/validations';\nimport MultiUploadFiles, {imageStatus} from \"../../Utils/MultiUploadFiles\";\nimport TransmittalActions from \"../../../actions/transmittal.actions\";\nimport tramittalRenderItem, {IRenderItemProps} from \"./renders/TramittalRenderItem\";\nimport BootstrapSelectField from \"../../Utils/forms/BootstrapSelectField\";\nimport ShowIf from '../../Utils/ShowIf';\nimport TextAreaField from \"../../Utils/forms/TextAreaField\";\n\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n  transmittal: ITransmittalState;\n  formValues: any;\n  transmittalActions: TransmittalActions\n}\n\ninterface IStateType {\n  filesCache: any[];\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    filesCache: [],\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentWillMount(): void {\n    this.props.transmittalActions.getFormBaseData();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {handleSubmit, valid, submitFailed, transmittal, formValues} = this.props;\n    const {filesCache} = this.state;\n    const filesCompleted = filesCache.filter((file: any) => file.status === imageStatus.complete);\n    const isUploadingFiles = filesCache.length > 0 && filesCompleted.length < filesCache.length;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"row\">\n              <div className=\"col-md-6\">\n                <Field\n                  name=\"transporter.driver\"\n                  label=\"Chofer *\"\n                  component={BootstrapSelectField}\n                  validate={[inputStringRequired]}\n                  props={{\n                    noneSelectedText: \"Selecciona un chofer\",\n                    displayItems: 2,\n                    sm: true,\n                    selectedText: \"choferes seleccionadas.\",\n                    autoClouse: true,\n                    allOption: false,\n                    search: true,\n                    options: [\n                      ...transmittal.drivers.map((driver) => ({\n                        value: driver._id,\n                        text: `${driver.firstName} ${driver.lastName} - ${driver.company.name}`\n                      }))\n                    ],\n                    onClick: (value: string) => this.props.autofill('transporter.driver', value)\n                  }}\n                >\n                </Field>\n              </div>\n              <div className=\"col-md-6\">\n                <Field\n                  name=\"transporter.carrier\"\n                  label=\"Transportista *\"\n                  component={BootstrapSelectField}\n                  validate={[inputStringRequired]}\n                  props={{\n                    noneSelectedText: \"Selecciona un transportista\",\n                    displayItems: 2,\n                    selectedText: \"transportistas seleccionadas.\",\n                    autoClouse: true,\n                    sm: true,\n                    allOption: false,\n                    search: true,\n                    options: [\n                      ...transmittal.carriers.map((carrier) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))\n                    ],\n                    onClick: (value: string) => this.props.autofill('transporter.carrier', value)\n                  }}\n                >\n                </Field>\n              </div>\n            </div>\n          </div>\n          <div className=\"col-md-6\">\n            <Field\n              name=\"transporter.patent\"\n              label=\"Patente del camión\"\n              placeholder=\"ABCD12\"\n              type=\"text\"\n              component={InputField}\n              // validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-6'>\n            <Field\n              name='type'\n              label='Tipo de transporte *'\n              component={BootstrapSelectField}\n              validate={[inputStringRequired]}\n              props={{\n                noneSelectedText: 'Selecciona un tipo',\n                displayItems: 2,\n                selectedText: 'tipo seleccionad0.',\n                autoClouse: true,\n                sm: true,\n                allOption: false,\n                search: true,\n                options: [\n                  ...transmittal.milestoneTypes.map((milestoneType) => ({\n                    value: milestoneType._id,\n                    text: milestoneType.name\n                  }))\n                ],\n                onClick: (value: string) => this.props.autofill('type', value)\n              }}\n            >\n            </Field>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label className=\"control-label label-left\">Adjuntar Documentos</label>\n              <div>\n                <MultiUploadFiles\n                  url={'/api/v1/transmittals/upload-file/'}\n                  onChange={(files) => {\n                    this.setState({filesCache: files});\n                    this.props.autofill('files', files)\n                  }}\n                  files={filesCache}\n                />\n                <ShowIf condition={isUploadingFiles}>\n                  <p>\n                    Se están cargando sus archivos, llevamos {filesCompleted.length} de {filesCache.length} <i className=\"fa fa-spinner fa-spin\"/>.\n                  </p>\n                </ShowIf>\n              </div>\n            </div>\n          </div>\n          <div className=\"col-md-12 m-t-10\">\n            <h4>Unidades Cargadas ({formValues.items ? formValues.items.length : ''})</h4>\n          </div>\n          <FieldArray<IRenderItemProps>\n            name=\"items\"\n            component={tramittalRenderItem}\n            props={{\n              transmittal\n            }}\n          />\n          <div className=\"col-md-12 m-t-10\">\n            <Field\n              name={`observation`}\n              label=\"Observación\"\n              component={TextAreaField}\n              type=\"text\"\n              rows={4}\n              props={{\n                resize: 'none'\n              }}\n            />\n          </div>\n          {\n            submitFailed && !valid &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger m-t-20\"\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst TransmittalForm = reduxForm({\n  form: 'transmittalForm'\n})(Form);\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('transmittalForm');\n  return {\n    formValues: selector(state, 'carrier', 'driver', 'files', 'items'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\nexport default connect<{ transmittal: ITransmittalState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(TransmittalForm);\n","import * as React from 'react';\nimport { Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport { ITransmittalState } from '../../../../actions/transmittal.types';\nimport TransmittalActions from '../../../../actions/transmittal.actions';\nimport { connect } from 'react-redux';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport { IRequestItem } from '../../../../../../../../src/request/interfaces/requestItem.interface';\nimport InputField from '../../../Utils/forms/InputField';\nimport BootstrapSwitchField from '../../../Utils/forms/BootsrapSwitchField';\nimport ShowIf from '../../../Utils/ShowIf';\nimport AddItemsToTransmittal from '../AddItemsToTransmittal';\nimport { ICar } from '../../../../../../../../src/app/interfaces/car.interface';\nimport SelectField from '../../../Utils/forms/SelectField';\n\n\nexport interface IRenderItemProps {\n  transmittal: ITransmittalState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IRenderItemProps {\n  transmittalActions: TransmittalActions;\n  formValues: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  openTabs: string[];\n  oneOrigin: boolean;\n  oneDestination: boolean;\n}\n\nclass TramittalRenderItem extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    exporing: false,\n    openTabs: [],\n    oneOrigin: true,\n    oneDestination: true\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.toogleTab = this.toogleTab.bind(this);\n    this.pushItem = this.pushItem.bind(this);\n    this.pushItemCar = this.pushItemCar.bind(this);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, transmittal } = this.props;\n    const { openTabs, oneOrigin, oneDestination } = this.state;\n    return (\n      <React.Fragment>\n        {\n          fields.length === 0 ?\n            <div className='col-md-12'>\n              <p\n                className='text-center text-muted'\n                style={{ padding: '20px 0' }}\n              >\n                No se han agregado unidades aún.\n              </p>\n            </div> :\n            <div className='col-md-12'>\n              <div className='table-responsive'>\n                <table className='table table-xs' style={{ minWidth: '1000px' }}>\n                <thead>\n                <tr className='bg-primary' style={{ height: '45px' }}>\n                  <th className='middle-center' style={{ width: '45px' }}>ID Sol.</th>\n                  <th className='middle' style={{ width: '120px' }}>VIN</th>\n                  <th className='middle'>Marca</th>\n                  <th className='middle'>Modelo</th>\n                  <th className='middle'>Color</th>\n                  <th className='middle' style={{ width: '100px' }}>Partida</th>\n                  <th className='middle' style={{ width: '100px' }}>Factura</th>\n                  <th className='middle' style={{ width: '150px' }}>Origen</th>\n                  <th className='middle' style={{ width: '150px' }}>Destino</th>\n                  <th className='middle' style={{ width: '40px' }} />\n                  <th className='middle' style={{ width: '28px' }} />\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  fields.map((item, index) => {\n                    const value: IRequestItem = fields.get(index) as IRequestItem;\n                    const openTab = openTabs.includes(value._id);\n                    return (\n                      <React.Fragment key={value._id}>\n                        <tr>\n                          <td className={`middle-center`}>\n                            <ShowIf condition={!!value?.request?.number}>\n                              #{this.padNumber(value.request?.number)}\n                            </ShowIf>\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.vin}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.brand}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.denomination}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.color}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.entry ?? '-'}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.invoice ?? '-'}\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.origin`}\n                              label='Origen *'\n                              component={SelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                labelOff: true,\n                                disabled: true\n                              }}\n                            >\n                              <option value={\"\"} disabled={true} >Seleccione</option>\n                              {\n                                transmittal.venues.map((venue) => (\n                                  <option key={venue._id} value={venue._id}>{venue.name}</option>\n                                ))\n                              }\n                            </Field>\n                            {/*<Field\n                              name={`${item}.origin`}\n                              label='Origen *'\n                              component={BootstrapSelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                noneSelectedText: 'Seleccione...',\n                                displayItems: 2,\n                                selectedText: 'origenes seleccionados.',\n                                autoClouse: true,\n                                sm: true,\n                                disabled: oneOrigin,\n                                labelOff: true,\n                                allOption: false,\n                                search: true,\n                                options: [\n                                  ...transmittal.venues.map((venue) => ({\n                                    value: venue._id,\n                                    text: venue.name\n                                  }))\n                                ],\n                                onClick: (value: string) => this.props.transmittalActions.autofill(`${item}.origin`, value)\n                              }}\n                            >\n                            </Field>*/}\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.destination`}\n                              label='Origen *'\n                              component={SelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                labelOff: true,\n                                disabled: true\n                              }}\n                            >\n                              <option value={\"\"} disabled={true} >Seleccione</option>\n                              {\n                                transmittal.venues.map((venue) => (\n                                  <option key={venue._id} value={venue._id}>{venue.name}</option>\n                                ))\n                              }\n                            </Field>\n                            {/*<Field\n                              name={`${item}.destination`}\n                              label='Destino *'\n                              component={BootstrapSelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                noneSelectedText: 'Seleccione...',\n                                displayItems: 2,\n                                selectedText: 'destinos seleccionados.',\n                                autoClouse: true,\n                                sm: true,\n                                right: true,\n                                disabled: oneDestination,\n                                labelOff: true,\n                                allOption: false,\n                                search: true,\n                                options: [\n                                  ...transmittal.venues.map((venue) => ({\n                                    value: venue._id,\n                                    text: venue.name\n                                  }))\n                                ],\n                                onClick: (value: string) => this.props.transmittalActions.autofill(`${item}.destination`, value)\n                              }}\n                            >\n                            </Field>*/}\n                          </td>\n                          <td className={`middle-center pointer`} onClick={() => this.toogleTab(value._id)}>\n                            {\n                              openTab ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n                            }\n                          </td>\n                          <td className={`middle`}>\n                            <button\n                              type='button'\n                              className='btn btn-sm btn-danger'\n                              onClick={() => fields.remove(index)}\n                            >\n                              <i className='fa fa-trash' />\n                            </button>\n                          </td>\n                        </tr>\n                        {\n                          openTab ?\n                            <tr style={{ borderTop: 'none' }}>\n                              <td colSpan={11} className={'b-t-0'}>\n                                <table className={'table'} style={{ marginBottom: 0 }}>\n                                  <thead>\n                                  <tr style={{ backgroundColor: '#f9f9f9' }}>\n                                    <th className={'middle width-20'}>Cliente</th>\n                                    <th className={'middle width-20'}>BL</th>\n                                    <th className={'middle width-20'}>Tipo</th>\n                                    <th className={'middle width-20'}>Tipo Operación (Motivo)</th>\n                                    <th className={'middle width-20'}>Observación</th>\n                                  </tr>\n                                  </thead>\n                                  <tbody>\n                                  <tr>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.car.client`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.car.bl`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                    <td className={'middle'}>{value.car?.type ?? '-'}</td>\n                                    <td className={'middle'}>{value.reason?.name ?? '-'}</td>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.observation`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                  </tr>\n                                  </tbody>\n                                </table>\n                              </td>\n                            </tr> : null\n                        }\n                      </React.Fragment>\n                    );\n                  })\n                }\n                <tr>\n                  <td colSpan={7} />\n                  <td colSpan={2}>\n                    <div className='flex flex-row'>\n                      <div className='flex-1' style={{ paddingRight: '3px' }}>\n                        <ShowIf condition={false}>\n                          <Field\n                            name='oneOrigin'\n                            label='Un solo origen'\n                            type='checkbox'\n                            checked={oneOrigin}\n                            component={BootstrapSwitchField}\n                            onChange={(e: any) => {\n                              const { checked } = e.target;\n                              if (!checked) {\n                                this.props.transmittalActions.autofill(`all.origin`, null);\n                              }\n                              this.setState({\n                                oneOrigin: checked\n                              });\n                            }}\n                            validate={[]}\n                          />\n                        </ShowIf>\n                        <Field\n                          name={`all.origin`}\n                          label=''\n                          component={SelectField}\n                          validate={[inputStringRequired]}\n                          props={{\n                            labelOff: true,\n                          }}\n                          input={{\n                            defaultValue:\"\",\n                            onChange: (e:any) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.origin`, e.target.value);\n                                this.props.transmittalActions.autofill(`all.origin`, e.target.value);\n                              });\n                            }\n                          }}\n                        >\n                          <option value={\"\"} disabled={true} >Seleccione</option>\n                          {\n                            transmittal.venues.map((venue) => (\n                              <option\n                                key={venue._id}\n                                value={venue._id}\n                              >\n                                {venue.name}\n                              </option>\n                            ))\n                          }\n                        </Field>\n                       {/* <Field\n                          name={`all.origin`}\n                          label=''\n                          component={BootstrapSelectField}\n                          props={{\n                            noneSelectedText: 'Seleccione...',\n                            displayItems: 2,\n                            selectedText: 'destinos seleccionados.',\n                            autoClouse: true,\n                            sm: true,\n                            disabled: !oneOrigin,\n                            labelOff: true,\n                            allOption: false,\n                            search: true,\n                            options: [\n                              ...transmittal.venues.map((venue) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))\n                            ],\n                            onClick: (value: string) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.origin`, value);\n                                this.props.transmittalActions.autofill(`all.origin`, value);\n                              });\n                            }\n                          }}\n                        >\n                        </Field>*/}\n                      </div>\n                      <div className='flex-1' style={{ paddingLeft: '3px' }}>\n                        <ShowIf condition={false}>\n                          <Field\n                            name='oneDestination'\n                            label='Un solo destino'\n                            type='checkbox'\n                            checked={oneDestination}\n                            component={BootstrapSwitchField}\n                            onChange={() => {\n                              // const { checked } = e.target;\n                              // if (!checked) {\n                              //   this.props.transmittalActions.autofill(`all.destination`, null);\n                              // }\n                              // this.setState({\n                              //   oneDestination: checked\n                              // });\n                            }}\n                            validate={[]}\n                          />\n                        </ShowIf>\n                        <Field\n                          name={`all.destination`}\n                          label=''\n                          component={SelectField}\n                          validate={[inputStringRequired]}\n                          props={{\n                            labelOff: true,\n                          }}\n                          input={{\n                            defaultValue:\"\",\n                            onChange: (e:any) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.destination`, e.target.value);\n                                this.props.transmittalActions.autofill(`all.destination`, e.target.value);\n                              });\n                            }\n                          }}\n                        >\n                          <option value={\"\"} disabled={true} >Seleccione</option>\n                          {\n                            transmittal.venues.map((venue) => (\n                              <option\n                                key={venue._id}\n                                value={venue._id}\n                              >\n                                {venue.name}\n                              </option>\n                            ))\n                          }\n                        </Field>\n                        {/*<Field\n                          name={`all.destination`}\n                          label=''\n                          component={BootstrapSelectField}\n                          props={{\n                            noneSelectedText: 'Seleccione...',\n                            displayItems: 2,\n                            selectedText: 'destinos seleccionados.',\n                            autoClouse: true,\n                            right: true,\n                            disabled: !oneDestination,\n                            sm: true,\n                            labelOff: true,\n                            allOption: false,\n                            search: true,\n                            options: [\n                              ...transmittal.venues.map((venue) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))\n                            ],\n                            onClick: (value: string) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.destination`, value);\n                                this.props.transmittalActions.autofill(`all.destination`, value);\n                              });\n                            }\n                          }}\n                        >\n                        </Field>*/}\n                      </div>\n                    </div>\n                  </td>\n                </tr>\n\n                </tbody>\n              </table>\n              </div>\n            </div>\n        }\n        <div className='col-md-12' style={{ marginTop: '10px' }}>\n          <h4>Agregar Unidades</h4>\n        </div>\n        <div className='col-md-12'>\n          <AddItemsToTransmittal fields={fields} onClickRequest={this.pushItem} onClickCar={this.pushItemCar} />\n        </div>\n        {submitFailed && error && <span>{error}</span>}\n      </React.Fragment>\n    );\n  }\n\n  private pushItemCar(car: ICar) {\n    const { formValues } = this.props;\n    this.props.transmittalActions.pushItem({\n      _id: car._id,\n      car: car,\n      type: 'car',\n      request: null,\n      // reason: item.reason,\n      origin: formValues?.all?.origin,\n      // destination: formValues?.all?.destination ?? item.destination?._id\n      destination: formValues?.all?.destination\n    });\n  }\n\n  private pushItem(item: IRequestItem) {\n    const { formValues } = this.props;\n    this.props.transmittalActions.pushItem({\n      _id: item._id,\n      type: 'request',\n      car: {\n        ...item.car,\n        bl: item.car.bl ?? '',\n        client: item.car.client ?? ''\n      },\n      request: item.request,\n      reason: item.reason,\n      origin: formValues?.all?.origin,\n      // destination: formValues?.all?.destination ?? item.destination?._id\n      destination: formValues?.all?.destination\n    });\n  }\n\n  private toogleTab(id: string) {\n    const { openTabs } = this.state;\n    if (openTabs.includes(id)) {\n      this.setState({\n        openTabs: [...openTabs.filter(tab => tab !== id)]\n      });\n    } else {\n      this.setState({\n        openTabs: [...openTabs, id]\n      });\n    }\n  }\n\n  private padNumber(n: number): string {\n    const s = '000' + n;\n    return s.substr(s.length - 4);\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('transmittalForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IRenderItemProps>(mapStateToProps, mapDispatchToProps)(TramittalRenderItem);\n","import * as React from 'react';\nimport { Dispatch } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { ITransmittalModel } from '../../../../../../../src/distribution/models/transmittal.model';\nimport TransmitalListItem from './TransmittalListItem';\nimport ShowIf from '../../Utils/ShowIf';\nimport { loadDataAction, ModalReduxAction } from '../../../actions/modal.actions';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport ApiService from '../../../utils/axios';\nimport { AxiosError } from 'axios';\nimport { hasPermission } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport { getParticipant } from '../../../actions/dashboard.actions';\nimport { IParticipant } from '../../../../../../../src/form/interfaces/participant.interface';\nimport UploadTransmittalFile from './UploadTransmittalFile';\nimport AddItemsToTransmittal from '../TransmittalForms/AddItemsToTransmittal';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { debounce } from 'throttle-debounce';\nimport {IMilestone} from \"../../../../../../../src/distribution/interfaces\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  item: ITransmittalModel;\n  evidenceMilestones: IMilestone[];\n  transmittalActions: TransmittalActions;\n  getParticipant(id: string): void;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass TransmitalListDetail extends React.Component<IPropsType, IStateType> {\n\n  private readonly api: ApiService;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.openDialogAddCar = this.openDialogAddCar.bind(this);\n    this.pushItem = this.pushItem.bind(this);\n    this.pushItemCar = this.pushItemCar.bind(this);\n    this.statusIcon = this.statusIcon.bind(this);\n    this.downloadFiles = this.downloadFiles.bind(this);\n    this.debouncedUpdateTransmittalThunkAction = debounce(2000, this.debouncedUpdateTransmittalThunkAction.bind(this));\n    this.api = new ApiService();\n  }\n\n  private debouncedUpdateTransmittalThunkAction(transmittal: any){\n    this.props.transmittalActions.updateTransmittalThunkAction(transmittal)\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { item: transmittal, transmittalActions, evidenceMilestones } = this.props;\n    const { carriers, drivers, milestoneTypes } = this.props.transmittal;\n    const open = this.props.transmittal.transmittalOpen.includes(transmittal._id);\n    return (\n      <React.Fragment>\n        <div id={`transmittal-${transmittal._id}`} className='row transmittal bg-transmittal-title background-transition pointer'>\n          <div\n            onClick={() => transmittalActions.toogleTab(transmittal._id)}\n            className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 center head-sorted'\n          >\n            <strong className='text-underline'>#{this.padNumber(transmittal.number)}</strong>&nbsp;\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <input\n                    className='form-control input-sm'\n                    defaultValue={transmittal.transporter?.patent}\n                    onChange={(e) => {\n                      this.debouncedUpdateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.patent': e.target.value\n                      });\n                    }}\n                  />\n                ) :\n                (\n                  `${transmittal.transporter?.patent}`\n                )\n            }\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.transporter.driver?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.driver': e.target.value\n                      });\n                    }}\n                  >\n                    {/*<option value='' disabled={true}>-</option>*/}\n                    {\n                      drivers.map((driver) => (\n                        <option key={driver._id} value={driver._id}>{`${driver.firstName} ${driver.lastName}`}</option>\n                      ))\n                    }\n                  </select>\n                  /*<BootstrapSelect\n                    noneSelectedText='Selecciona un chófer'\n                    displayItems={2}\n                    sm={true}\n                    selectedText='choferes seleccionadas.'\n                    selected={transmittal.transporter.driver ? [transmittal.transporter.driver._id] : []}\n                    autoClouse={true}\n                    allOption={false}\n                    search={true}\n                    options={drivers.map((driver: any) => ({\n                      value: driver._id,\n                      text: `${driver.firstName} ${driver.lastName}`\n                    }))}\n                    onClick={(e: string) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.driver': e\n                      });\n                    }}\n                  />*/\n                ) :\n                (\n                  `${transmittal.transporter.driver.firstName} ${transmittal.transporter.driver.lastName}`\n                )\n            }\n            {/*{transmittal.transporter.driver._id}*/}\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.transporter.carrier?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.carrier': e.target.value\n                      });\n                    }}\n                  >\n                    {/*<option value='' disabled={true}>-</option>*/}\n                    {\n                      carriers.map((carrier) => (\n                        <option key={carrier._id} value={carrier._id}>{`${carrier.name}`}</option>\n                      ))\n                    }\n                  </select>\n                ) :\n                (\n                  `${transmittal.transporter.carrier.name}`\n                )\n            }\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {transmittal.items.length} unidades.\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.type?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'type': e.target.value\n                      });\n                    }}\n                  >\n                    <option value='' disabled={true}>-</option>\n                    {\n                      milestoneTypes.map((milestoneType) => (\n                        <option key={milestoneType._id} value={milestoneType._id}>{`${milestoneType.name}`}</option>\n                      ))\n                    }\n                  </select>\n                  /*<BootstrapSelect\n                    noneSelectedText='Selecciona un transportista'\n                    displayItems={2}\n                    sm={true}\n                    selectedText='transportistas seleccionadas.'\n                    selected={transmittal.transporter.carrier ? [transmittal.transporter.carrier._id] : []}\n                    autoClouse={true}\n                    allOption={false}\n                    search={true}\n                    options={carriers.map((carrier: any) => ({\n                      value: carrier._id,\n                      text: carrier.name\n                    }))}\n                    onClick={(e: string) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.carrier': e\n                      });\n                    }}\n                  />*/\n                ) :\n                (\n                  `${transmittal.type?.name}`\n                )\n            }\n\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            <UploadTransmittalFile transmittal={transmittal} />\n            <ShowIf condition={transmittal.files.length >= 1}>\n              <button\n                className='btn btn-xs btn-default'\n                onClick={() => this.downloadFiles(transmittal)}\n              >\n                <i\n                  className='fa fa-paperclip'\n                  data-toggle='tooltip'\n                  data-placement='top'\n                  title={`${transmittal.files.length} archivos adjuntos.`}\n                /> {`(${transmittal.files.length})`}\n              </button>\n            </ShowIf>\n          </div>\n          {\n            evidenceMilestones.map((milestone: IMilestone, index: number) => {\n              let tmp = transmittal.evidenceFullLoad.filter(e => {\n                if (e.milestone != undefined) {\n                  let is_in: Boolean = evidenceMilestones.filter(em => em._id == e.milestone).length > 0;\n                  return is_in ? e.milestone == milestone._id : index == 0;\n                } else\n                  return index == 0;\n              });\n              return (\n                <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 text-center' key={`${transmittal._id}-${milestone._id}`}>\n                  {\n                    tmp.map((image: any, index: number) => (\n                      <div\n                        key={`${transmittal._id}-${index}${image._id}`}\n                        className={'text-center'} style={{ display: index === 0 ? '' : 'none' }}\n                      >\n                        <a href={decodeURI(image.file.url)}\n                           data-toggle='lightbox'\n                           data-gallery={`${transmittal._id}-${milestone._id}`}\n                           data-title={`#${this.padNumber(transmittal.number)}`}\n                           data-footer={`Conductor ${transmittal.transporter.driver ? `${transmittal.transporter.driver.firstName} ${transmittal.transporter.driver.lastName}` : ''} (${transmittal.transporter?.patent})`}\n                        >\n                          <button className='btn btn-xs btn-default'>\n                            <i className='fa fa-fw fa-image' /> {tmp.length}\n                          </button>\n                        </a>\n                      </div>\n                    ))\n                  }\n                </div>\n              );\n            })\n          }\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              transmittal?.revision ?\n                this.statusIcon(transmittal.revision) :\n                null\n            }\n          </div>\n          <div\n            className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 chevron pointer'\n            onClick={() => transmittalActions.toogleTab(transmittal._id)}\n          >\n            {\n              open ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n            }\n          </div>\n        </div>\n        <ShowIf condition={open}>\n          <div className='table-transmittal'>\n            <table className='table table-hover m-0'>\n              <thead>\n              <tr style={{ backgroundColor: '#f9f9f9' }}>\n                <th className='middle' style={{ width: '28px' }}>SOL</th>\n                <th className='middle' style={{ width: '140px' }}>VIN</th>\n                <th className='middle' style={{ width: '160px' }}>Descripción</th>\n                <th className='middle' style={{ width: '70px' }}>Factura</th>\n                <th className='middle' style={{ width: '70px' }}>Partida</th>\n                <th className='middle' style={{ width: '70px' }}>BL</th>\n                <th className='middle' style={{ minWidth: '100px' }}>Origen</th>\n                <th className='middle' style={{ minWidth: '100px' }}>Destino</th>\n                <th className='middle' style={{ width: '105px' }}>Fecha emisión</th>\n                <th className='middle' style={{ width: '105px' }}>Fecha arribo</th>\n                <th className='middle' style={{ width: '20px' }}></th>\n                <th className='middle-center' style={{ width: '40px' }}>Cargado</th>\n                <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n                  <th className='middle' style={{ width: '30px' }} />\n                </ShowIf>\n              </tr>\n              </thead>\n              <tbody>\n              {\n                transmittal.items.map((transmittalItem, index) => (\n                  <TransmitalListItem\n                    history={this.props.history}\n                    item={transmittal}\n                    transmittalItem={transmittalItem}\n                    key={`${index}${transmittalItem._id}`}\n                  />\n                ))\n              }\n              <ShowIf condition={false && transmittal.items.length > 1}>\n                <tr className='no-striped'>\n                  <td colSpan={8} className='middle text-right'>\n                    {/*Masivo*/}\n                  </td>\n                  <td className='middle'>\n                    <DateRangePicker\n                      className={'input-sm'}\n                      value={''}\n                      format={'DD-MM-YY'}\n                      onChange={(e) => {\n                        this.props.transmittalActions.updateTransmittalThunkAction({\n                          _id: transmittal._id,\n                          allLoadingDate: e?.toDate() ?? ''\n                        });\n                      }}\n                    />\n                  </td>\n                  <td className='middle'>\n                    <DateRangePicker\n                      className={'input-sm'}\n                      value={''}\n                      format={'DD-MM-YY'}\n                      onChange={(e) => {\n                        // allArrivalDate\n                        this.props.transmittalActions.updateTransmittalThunkAction({\n                          _id: transmittal._id,\n                          allArrivalDate: e?.toDate() ?? ''\n                        });\n                      }}\n                    />\n                  </td>\n                </tr>\n              </ShowIf>\n              </tbody>\n            </table>\n            <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n              <div className='row'>\n                <div className='col-md-12 text-right m-b-10 m-t-10'>\n                  <button className='btn btn-sm btn-success' onClick={this.openDialogAddCar}>\n                    <i className='fa fa-fw fa-plus-square' /> Cargar vehículo\n                  </button>\n                </div>\n              </div>\n            </ShowIf>\n          </div>\n        </ShowIf>\n      </React.Fragment>\n    );\n  }\n\n  private statusIcon(revision: IParticipant) {\n    if (revision.hasDamages) {\n      return (\n        <button\n          className='btn btn-xs btn-default'\n          data-toggle='tooltip'\n          data-placement='top'\n          title={`Ver detalle`}\n          onClick={() => this.props.getParticipant(revision._id)}\n        >\n          <i className='fa fa-warning text-red' />\n        </button>\n      );\n    } else {\n      return (\n        <button\n          className='btn btn-xs btn-default'\n          data-toggle='tooltip'\n          data-placement='top'\n          title={`Ver detalle`}\n          onClick={() => this.props.getParticipant(revision._id)}\n        >\n          <i className='fa fa-check-circle text-primary' />\n        </button>\n      );\n    }\n  }\n\n  private openDialogAddCar() {\n    const { item: transmittal } = this.props;\n    this.props.loadDataAction(\n      `Agregar vehículo a orden #${this.padNumber(transmittal.number)}`,\n      <AddItemsToTransmittal onClickRequest={this.pushItem} onClickCar={this.pushItemCar} slimView={true} />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cerrar</button>\n      </React.Fragment>\n    );\n  }\n\n  private downloadFiles(transmittal: ITransmittalModel) {\n    window.open(`/transmittals/${transmittal._id}/download-files/`, '_blank');\n  }\n\n  private pushItemCar(car: ICar) {\n    const { item: transmittal } = this.props;\n    this.api.addTransmittalItem({\n      requestItem: null,\n      car: car._id,\n      request: null,\n      // origin: requestItem.origin?._id,\n      // destination: requestItem.destination?._id,\n      transmittal: transmittal._id\n    })\n      .then((): void => {})\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n\n  private pushItem(requestItem: IRequestItem) {\n    const { item: transmittal } = this.props;\n    this.props.transmittalActions.loadingRequestItemAction(true);\n    this.api.addTransmittalItem({\n      requestItem: requestItem._id,\n      car: requestItem.car._id,\n      request: requestItem.request._id,\n      origin: requestItem.origin?._id,\n      destination: requestItem.destination?._id,\n      transmittal: transmittal._id\n    })\n      .then((): void => {})\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private padNumber(n: number): string {\n    const s = '0000' + n;\n    return s.substr(s.length - 5);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions,\n    getParticipant: (id: string) => dispatch(getParticipant(id)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(TransmitalListDetail);\n","import * as React from 'react';\nimport { Dispatch } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport * as moment from 'moment-timezone';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { ITransmittalItem } from '../../../../../../../src/distribution/interfaces/transmittalItem.interface';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport ShowIf from '../../Utils/ShowIf';\nimport * as swal from 'sweetalert';\nimport ApiService from '../../../utils/axios';\nimport CopyText from '../../Utils/CopyText';\nimport { ITransmittal } from '../../../../../../../src/distribution/interfaces/transmittal.interface';\nimport { IParticipant } from '../../../../../../../src/form/interfaces/participant.interface';\nimport { getParticipant } from '../../../actions/dashboard.actions';\nimport { debounce } from 'throttle-debounce';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  item: ITransmittal;\n  transmittalItem: ITransmittalItem;\n  transmittalActions: TransmittalActions;\n\n  getParticipant(id: string): void;\n}\n\ntype RecursivePartial<T> = {\n  [P in keyof T]?: RecursivePartial<T[P]>;\n};\n\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass TransmitalListItem extends React.Component<IPropsType, IStateType> {\n  private api: ApiService;\n  title: string;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.delete = this.delete.bind(this);\n    this.statusIcon = this.statusIcon.bind(this);\n    this.debounceUpdateTransmittalItem = debounce(300, this.debounceUpdateTransmittalItem);\n    this.api = new ApiService();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalItem, transmittal: { venues } } = this.props;\n    return (\n      <tr id={`transmittal-item-${transmittalItem._id}`} className='background-transition'>\n        <td\n          className={'middle-center pointer'}\n          onClick={transmittalItem.request?._id ? () => {\n            this.props.history.push(`/requests/vehicles/${transmittalItem.request._id}/`);\n          } : undefined}\n        >\n          <strong className=\"text-underline\">\n            <ShowIf condition={!!transmittalItem?.request?.number}>\n              #{transmittalItem.request?.number}\n            </ShowIf>\n          </strong>\n        </td>\n        <td\n          className={'middle text-primary'}\n\n        >\n          <CopyText value={transmittalItem.car.vin}>\n            <strong\n              className={'text-underline pointer'}\n              onClick={()=>{this.props.history.push(`/settings/cars/${transmittalItem.car._id}/`)}}\n            >\n              {transmittalItem.car.vin}\n            </strong>\n          </CopyText>\n        </td>\n        <td className={'middle'}><strong className={\"text-muted\"}>{transmittalItem.car.brand}</strong><br /><span className={\"text-muted\"}>{transmittalItem.car.denomination}</span></td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.invoice}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.invoice}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    invoice: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.entry}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.entry}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    entry: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.bl}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.bl}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    bl: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.origin?.name}>\n            <select\n              className='form-control select-sm font-12' value={transmittalItem.origin?._id ?? ''}\n              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  origin: e.target.value\n                });\n              }}\n            >\n              {\n                venues.map((venue) => (\n                  <option key={venue._id} value={venue._id}>{`${venue.name}`}</option>\n                ))\n              }\n            </select>\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.destination?.name}>\n            <select\n              className='form-control select-sm font-12' value={transmittalItem.destination?._id ?? ''}\n              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  destination: e.target.value\n                });\n              }}\n            >\n              {\n                venues.map((venue) => (\n                  <option key={venue._id} value={venue._id}>{`${venue.name}`}</option>\n                ))\n              }\n            </select>\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf\n            condition={hasPermission(window.user, 'changeTransmittal')}\n            alternative={transmittalItem.loadingDate ? moment(transmittalItem.loadingDate).format('DD-MM-YYYY') : '-'}\n          >\n            <DateRangePicker\n              className={'input-sm'}\n              value={transmittalItem.loadingDate}\n              format={'DD-MM-YY'}\n              disabled={true}\n              // onChange={(e) => {\n              //   this.props.transmittalActions.updateTransmittalItemThunkAction({\n              //     _id: transmittalItem._id,\n              //     transmittal: transmittalItem.transmittal,\n              //     loadingDate: e?.toDate() ?? ''\n              //   });\n              // }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf\n            condition={hasPermission(window.user, 'changeTransmittal')}\n            alternative={transmittalItem.arrivalDate ? moment(transmittalItem.arrivalDate).format('DD-MM-YYYY') : '-'}\n          >\n            <DateRangePicker\n              className={'input-sm'}\n              value={transmittalItem.arrivalDate}\n              format={'DD-MM-YY'}\n              disabled={true}\n              // onChange={(e) => {\n              //   this.props.transmittalActions.updateTransmittalItemThunkAction({\n              //     _id: transmittalItem._id,\n              //     transmittal: transmittalItem.transmittal,\n              //     arrivalDate: e?.toDate() ?? ''\n              //   });\n              // }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          {/*<ShowIf*/}\n          {/*  condition={hasPermission(window.user, 'changeTransmittal')}*/}\n          {/*  alternative={transmittalItem.observation ?? '-'}*/}\n          {/*>*/}\n          {/*  <input*/}\n          {/*    className='form-control input-sm'*/}\n          {/*    defaultValue={transmittalItem.observation}*/}\n          {/*    onChange={(e) => {*/}\n          {/*      this.debounceUpdateTransmittalItem({*/}\n          {/*        _id: transmittalItem._id,*/}\n          {/*        transmittal: transmittalItem.transmittal,*/}\n          {/*        observation: e.target.value*/}\n          {/*      });*/}\n          {/*    }}*/}\n          {/*  />*/}\n          {/*</ShowIf>*/}\n        </td>\n        {\n          transmittalItem.revisions.length ?\n            this.statusIcon(transmittalItem.revisions[0]) :\n            <td className={'middle'} />\n        }\n        <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n          <td className='middle-center text-red pointer' onClick={this.delete}>\n            <i className='fa fa-minus-circle' />\n          </td>\n        </ShowIf>\n      </tr>\n    );\n  }\n\n  private debounceUpdateTransmittalItem(transmittalItem: RecursivePartial<ITransmittalItem>) {\n    this.props.transmittalActions.updateTransmittalItemThunkAction(transmittalItem);\n  }\n\n  private statusIcon(revision: IParticipant) {\n    if (revision.hasDamages) {\n      return (\n        <td className={'middle-center pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-warning text-red' />\n        </td>\n      );\n    } else if (revision.receptionConfirmation) {\n      return (\n        <td className={'middle-center pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-check-circle text-primary' />\n        </td>\n      );\n    } else if (!revision.receptionConfirmation) {\n      return (\n        <td className={'middle-center pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-close text-danger' />\n        </td>\n      );\n    }\n    return <td className={'middle'} />;\n  }\n\n  private delete() {\n    const { transmittalItem } = this.props;\n    const { item: transmittal } = this.props;\n    swal!({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar ${transmittalItem.car.brand} ${transmittalItem.car.denomination}, de la orden ${this.padNumber(transmittal.number)}.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        const { transmittalItem } = this.props;\n        this.api.deleteTransmittalItem(transmittalItem);\n      }\n    });\n  }\n\n  private padNumber(n: number): string {\n    const s = '0000' + n;\n    return s.substr(s.length - 5);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions,\n    getParticipant: (id: string) => dispatch(getParticipant(id))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(TransmitalListItem);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, Fragment } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport ImageLazyLoad from '../../Utils/ImageLazyLoad';\nimport Paginator from '../../Utils/Paginator';\nimport ShowIf from '../../Utils/ShowIf';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport TransmitalListDetail from './TransmitalListDetail';\nimport { Dispatch } from 'redux';\nimport ModalView from '../../Modal/ModalView';\nimport { debounce } from 'throttle-debounce';\nimport { IMilestone } from '../../../../../../../src/distribution/interfaces';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  number: string | undefined;\n}\n\ndeclare let window: IWindow;\n\nclass TransmittalListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    exporing: false,\n    number: \"\"\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Transporte';\n    this.create = this.create.bind(this);\n    this.changeOrder = this.changeOrder.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.changeNumber = this.changeNumber.bind(this);\n    this.callChangeNumber = debounce(1000, this.callChangeNumber.bind(this));\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      pagination, loading, data, options: { orderBy, orderType }, milestones, milestoneTypes\n    } = this.props.transmittal;\n\n    let longestMilestones: IMilestone[] = [];\n\n    for (let mType of milestoneTypes) {\n      let tmp = milestones\n        .filter(m => m.type === mType._id && m.step === 'loadEvidence');\n      if (tmp.length > longestMilestones.length)\n        longestMilestones = tmp.sort((a, b) => a.order - b.order);\n    }\n\n    const { exporing, number } = this.state;\n    return (\n      <AppContainer title={\n        <div\n          className='input-group input-group-sm'\n          style={{ width: '300px' }}\n        >\n          <input\n            type='text'\n            className='form-control pull-right'\n            onChange={(e) => {\n              this.changeNumber(e.target.value);\n            }}\n            value={number}\n            placeholder='Buscar OT ej: 452' />\n          <div className='input-group-btn'>\n            <button\n              className={`btn ${!!this.state.number?.length ? 'btn-primary' : 'btn-default'}`}\n              onClick={!!this.state.number?.length ? () => {\n                this.props.history.replace(`/transmittals/`);\n                this.changeNumber('');\n              }: undefined}\n            >\n              <ShowIf condition={!!this.state.number?.length} alternative={<i className='fa fa-search' />}>\n                <i className='fa fa-close' />\n              </ShowIf>\n            </button>\n          </div>\n        </div>\n      } cMenu='3' cSubMenu='3.4'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Transportes <small>{pagination.count}</small></h3>\n              <div className='pull-right box-tools'>\n                {\n                  hasPermission(window.user, 'addTransmittal') ?\n                    <button className='btn btn-sm btn-success' onClick={this.create}>\n                      <i className='fa fa-fw fa-plus' /> Crear orden de transporte\n                    </button>\n                    : null\n                }\n                <ShowIf condition={data.length > 0}>\n                  <button\n                    className='btn btn-sm btn-primary hidden-xs'\n                    onClick={this.exportExcel}\n                    disabled={exporing}\n                    style={{ marginLeft: '5px' }}\n                  >\n                    {\n                      exporing ? <Fragment><i className='fa fa-spin fa-spinner' /> Exportando</Fragment>\n                        : <Fragment><i className='fa fa-fw fa-download' /> Exportar</Fragment>\n                    }\n                  </button>\n                </ShowIf>\n              </div>\n            </div>\n            <div className={`box-body transmittal-list`}>\n              <div className='table-responsive'>\n                <ShowIf condition={data.length > 0}>\n                  <>\n                    <div className='row transmittal bg-primary'>\n                      <div\n                        className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 center pointer head-sorted'\n                        onClick={() => this.changeOrder('_id')}\n                      >\n                        <strong>ID</strong> <i\n                        className={`fa ${orderBy === '_id' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Placa</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Chofer</strong>\n                      </div>\n                      <div className='flex-45 col-sm-2 col-xs-2 col-md-1 col-lg-1'>\n                        <strong>Transportista</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Nº Unidades</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Tipo</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Documentos</strong>\n                      </div>\n                      {\n                        longestMilestones.map((milestone: IMilestone, index) => {\n                          return (\n                              <div\n                                className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 text-center no-padding'\n                                key={`${index}${milestone._id}`}>\n                              <strong>{milestone.name.replace('Evidencia', '').toUpperCase()}</strong>\n                            </div>\n                          )\n                        })\n                      }\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 no-padding'>\n                        <strong>DESCARGA</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' />\n                    </div>\n                    {\n                      data.map((item: any, index) => (\n                        <TransmitalListDetail\n                          router={this.props.router}\n                          history={this.props.history}\n                          item={item}\n                          evidenceMilestones={longestMilestones}\n                          key={`${index}${item._id}`}\n                        />\n                      ))\n                    }\n                  </>\n                </ShowIf>\n                <ShowIf condition={!loading && data.length === 0}>\n                  <div className='row'>\n                    <div className='col-md-12 text-center' style={{ paddingTop: '10px', paddingBottom: '10px' }}>\n                      <ImageLazyLoad\n                        url='/images/not_found.png'\n                        height={'200px'}\n                        style={{\n                          opacity: 0.5,\n                          maxHeight: '200px',\n                          marginBottom: '10px'\n                        }}\n                        replaceLoading={<i\n                          className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                          style={{ padding: '30px' }}\n                        />}\n                      /><br />\n                      <strong>No hay información para mostrar</strong>\n                    </div>\n                  </div>\n                </ShowIf>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer'>\n                <div className='row'>\n                  <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                    <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                      &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                      </span>\n                  </div>\n                  <div className='col-md-6'>\n                    <div className='text-right' style={{ marginRight: '15px' }}>\n                      <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                    </div>\n                  </div>\n                </div>\n              </div>\n            }\n            {\n              data.length === 0 && loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n          <ModalView modalLarge={true} />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  public componentWillMount(): void {\n    const { orderBy, orderType } = this.props.transmittal.options;\n    const { page } = this.props.transmittal.pagination;\n    const { location: { query } } = this.props.router;\n    const { transmittalActions } = this.props;\n    window.scrollTo(0, 0);\n    const { number } = query;\n    this.setState({ number });\n    transmittalActions.getTransmittalsThunkAction({\n      nextPage: number ? 1 : page,\n      orderBy,\n      orderType,\n      number\n    });\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `transmittal-list-${window.user.team._id}`\n      });\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL_ITEM', (data: any): void => {\n      transmittalActions.createTransmittalItemAction(data.transmittalItem);\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-green-active');\n      }\n      setTimeout(() => {\n        $item.removeClass('bg-green-active');\n      }, 300);\n    });\n\n    this.socket.on('UPDATE_TRANSMITTAL_ITEM', (data: any): void => {\n      transmittalActions.updateTransmittalItemAction(data.transmittalItem);\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('UPDATE_TRANSMITTAL', (data: any): void => {\n      transmittalActions.updateTransmittalAction(data.transmittal);\n      const $item = $(`#transmittal-${data.transmittal._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL_ITEM', (data: any): void => {\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        transmittalActions.deleteTransmittalItemAction(data.transmittalItem);\n      }, 300);\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL', (data: any): void => {\n      const $item = $(`#transmittal-${data.transmittal._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        transmittalActions.deleteTransmittalAction(data.transmittal);\n        const { orderBy, orderType } = this.props.transmittal.options;\n        const { page } = this.props.transmittal.pagination;\n        transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, hideLoading: true });\n      }, 300);\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL', (): void => {\n      const { page } = this.props.transmittal.pagination;\n      const { orderBy, orderType } = this.props.transmittal.options;\n      transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, hideLoading: true });\n    });\n\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `distribution-list-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  private changeNumber(number: string) {\n    this.setState({ number });\n    this.callChangeNumber(number);\n  }\n\n  private callChangeNumber(number: string) {\n    const { options: { orderBy, orderType } } = this.props.transmittal;\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: 1, orderBy, orderType, number });\n  }\n\n  private changeOrder(key: string) {\n    const {\n      options: { orderBy, orderType },\n      pagination: { page }\n    } = this.props.transmittal;\n    let newOrderType = orderType;\n    let newOrderBy = orderBy;\n    if (key === orderBy) {\n      newOrderType = orderType === 'descending' ? 'ascending' : 'descending';\n    } else {\n      newOrderBy = key;\n    }\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy: newOrderBy, orderType: newOrderType });\n  }\n\n  private create(): void {\n    this.props.history.push(parseReplicableURL('/transmittals/create/'));\n  }\n\n  private changePage(page: number): void {\n    const { options: { orderBy, orderType } } = this.props.transmittal;\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType });\n  }\n\n  public exportExcel(): void {\n    this.trackClick('Exportar');\n    window.open(`/transmittals/export-xls/`, '_blank');\n    // this.setState({\n    //   exporing: true\n    // });\n    // const api: ApiService = new ApiService();\n    // const instance = api.getInstance();\n    // instance.defaults.responseType = 'blob';\n    // instance\n    //   .get(`/transmittals/export-xls/`)\n    //   .then((response) => {\n    //     const blob = new Blob([response.data], {\n    //       type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n    //     });\n    //     const fileName = `${moment().format('YYYYMMDD')}-distribución.xlsx`;\n    //     // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n    //     //   // IE workaround for \"HTML7007: One or more blob URLs were\n    //     //   // revoked by closing the blob for which they were created.\n    //     //   // These URLs will no longer resolve as the data backing\n    //     //   // the URL has been freed.\"\n    //     //   window.navigator.msSaveBlob(blob, fileName);\n    //     // } else {\n    //       const blobURL = URL.createObjectURL(blob);\n    //       const tempLink = document.createElement('a');\n    //       tempLink.style.display = 'none';\n    //       tempLink.href = blobURL;\n    //       tempLink.setAttribute('download', fileName);\n    //       // Safari thinks _blank anchor are pop ups. We only want to set _blank\n    //       // target if the browser does not support the HTML5 download attribute.\n    //       // This allows you to download files in desktop safari if pop up blocking\n    //       // is enabled.\n    //       if (typeof tempLink.download === 'undefined') {\n    //         tempLink.setAttribute('target', '_blank');\n    //       }\n    //       this.setState({\n    //         exporing: false\n    //       });\n    //       document.body.appendChild(tempLink);\n    //       tempLink.click();\n    //       document.body.removeChild(tempLink);\n    //       URL.revokeObjectURL(blobURL);\n    //     // }\n    //   })\n    //   .catch((err) => {\n    //     this.setState({\n    //       exporing: false\n    //     });\n    //     if (!Axios.isCancel(err)) {\n    //       swal!('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n    //     }\n    //   });\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState, router: any }) => {\n  return {\n    transmittal: state.transmittal,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(TransmittalListView);\n","import * as React from 'react';\nimport { RefObject } from 'react';\nimport { ITransmittal } from '../../../../../../../src/distribution/interfaces/transmittal.interface';\nimport ApiService from '../../../utils/axios';\nimport { AxiosError } from 'axios';\n\ninterface IPropsType {\n  transmittal: ITransmittal;\n}\n\ninterface IStateType {\n  loading: boolean;\n  error: Error | null;\n}\n\nclass UploadTransmittalFile extends React.Component<IPropsType, IStateType> {\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  private readonly api: ApiService;\n\n  readonly state: IStateType = {\n    error: null,\n    loading: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.api = new ApiService();\n    this.inputFile = React.createRef();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading } = this.state;\n    return (\n      <button\n        className='btn btn-xs btn-default'\n        disabled={loading}\n        style={{ marginRight: '5px' }}\n        onClick={this.clickUploadFile}\n      >\n        <input\n          type='file'\n          ref={this.inputFile}\n          style={{ display: 'none' }}\n          onChange={this.handleChangeInputFile}\n        />\n        {\n          loading\n            ? (\n              <i className='fa fa-spinner fa-spin text-purple' />\n            )\n            : (\n              <i\n                className='fa fa-fw fa-cloud-upload'\n                data-toggle='tooltip'\n                data-placement='top'\n                title={`Cargar archivo`}\n              />\n            )\n        }\n      </button>\n    );\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const { files } = e.target;\n    const { transmittal } = this.props;\n    if (files && files.length) {\n      const data = new FormData();\n      data.append('file', files[0]);\n      data.append('transmittal', transmittal._id);\n      this.setState({ loading: true });\n      this.api.uploadTransmittalFile(data)\n        .then((response) => {\n          this.setState({ loading: false });\n        })\n        .catch((err: AxiosError) => {\n          this.setState({ loading: false });\n          this.api.errorHandler(err);\n        });\n    }\n    this.inputFile.current!.value = '';\n  }\n}\n\nexport default UploadTransmittalFile;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\nimport {IUsersState} from '../../actions/users.actions';\n\ninterface IPropsType {\n  users: IUsersState;\n  user?: IUser;\n  changeTempUser(user: any): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  type: string;\n}\n\nclass UserFormChangePasswordView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    type: 'password'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeType = this.changeType.bind(this);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n\n    return (\n      <div className=\"row\">\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Nueva Contraseña</label>\n            <div className=\"input-group\">\n              <input\n                type={this.state.type}\n                className=\"form-control\"\n                defaultValue={tempUser ? tempUser.password : undefined}\n                onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({password: e.target.value})}\n              />\n              <span className=\"input-group-addon pointer\" onClick={this.changeType}>\n                <i className={`fa ${this.state.type === 'text' ? 'fa-eye-slash' : 'fa-eye'}`} />\n              </span>\n            </div>\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private changeType() {\n    this.setState({\n      type: this.state.type === 'text' ? 'password' : 'text'\n    });\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UserFormChangePasswordView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {ICompany} from '../../../../../../src/app/interfaces/company.interface';\nimport {IForm} from '../../../../../../src/form/interfaces/form.interface';\nimport {IPermission} from '../../../../../../src/app/interfaces/permission.interface';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\nimport {IVenue} from '../../../../../../src/app/interfaces/venue.interface';\nimport {IUsersState} from '../../actions/users.actions';\nimport {IWindow} from '../../interfaces/window';\nimport Checkbox from '../Utils/CheckBox';\nimport {hasPermission} from '../../utils/common';\n\ninterface IPropsType {\n  users: IUsersState;\n  venues: IVenue[];\n  forms: IForm[];\n  permissions: IPermission[];\n  companies: ICompany[];\n  user?: IUser;\n  create: boolean;\n  changeTempUser(user: any): void;\n}\ndeclare let window: IWindow;\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass UserFormView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.addPermission = this.addPermission.bind(this);\n    this.deletePermission = this.deletePermission.bind(this);\n    this.addVenueAccess = this.addVenueAccess.bind(this);\n    this.deleteVenueAccess = this.deleteVenueAccess.bind(this);\n    this.changeIsAdmin = this.changeIsAdmin.bind(this);\n    this.changeIsDriver = this.changeIsDriver.bind(this);\n    this.addForm = this.addForm.bind(this);\n    this.deleteForm = this.deleteForm.bind(this);\n  }\n\n  public componentDidMount() {\n    const {changeTempUser, companies} = this.props;\n    const {tempUser} = this.props.users;\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n    ($('#id-forms') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addForm(e.target.value);\n      });\n    ($('#id-form-default') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({preferred: e.target.value});\n      });\n    ($('#id-venue') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({venue: e.target.value});\n      });\n    ($('#id-company') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({\n          company: companies.find((company) => (\n            company._id === e.target.value\n          ))\n        });\n      });\n    ($('#id-channel') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({\n          settings: {\n            ...tempUser.settings,\n            defaultChannel: e.target.value\n          }\n        });\n      });\n    ($('#id-permissions') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n          this.addPermission(e.target.value);\n        });\n    ($('#id-venues-access') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addVenueAccess(e.target.value);\n      });\n\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    $('#id-forms').trigger('chosen:updated');\n    $('#id-form-default').trigger('chosen:updated');\n    $('#id-venue').trigger('chosen:updated');\n    $('#id-permissions').trigger('chosen:updated');\n    $('#id-company').trigger('chosen:updated');\n    $('#id-channel').trigger('chosen:updated');\n    $('#id-venues-access').trigger('chosen:updated');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {changeTempUser, venues, permissions, forms, create, companies} = this.props;\n    const {tempUser, channels} = this.props.users;\n    const userPermissions: IPermission[] = [];\n    const selectPermissions: IPermission[] = [];\n    const userForms: IForm[] = [];\n    const selectForms: IForm[] = [];\n    const idsUserPermissions = tempUser && tempUser.userPermissions.length ? tempUser.userPermissions.map((userPermission) => userPermission._id) : [];\n    const idsUserVenueAccess = tempUser && tempUser.venuesAccess.length ? tempUser.venuesAccess.map((venue) => venue._id) : [];\n    const idsUserForms = tempUser && tempUser.userForms.length ? tempUser.userForms.map((userForm) => userForm._id) : [];\n    permissions.forEach((permission) => {\n      if (idsUserPermissions.includes(permission._id)) {\n        userPermissions.push(permission);\n      } else {\n        selectPermissions.push(permission);\n      }\n    });\n    forms.forEach((form) => {\n      if (idsUserForms.includes(form._id)) {\n        userForms.push(form);\n      } else {\n        selectForms.push(form);\n      }\n    });\n    return (\n      <React.Fragment>\n        <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n          <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n          {\n            window.user.isAdmin || (hasPermission(window.user, 'changeTeamPermissions') && !this.props.user?.isAdmin)  ?\n              <li><a data-toggle=\"tab\" href=\"#permissions\">Permisos</a></li>\n              : null\n          }\n          <li><a data-toggle=\"tab\" href=\"#access\">Accesos</a></li>\n          <li ><a data-toggle=\"tab\" href=\"#request\">Solicitudes</a></li>\n        </ul>\n        <div className=\"tab-content\">\n          <div id=\"general\" className=\"tab-pane fade in active\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Nombres</label>\n                  <input\n                    type=\"text\"\n                    name=\"firstName\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempUser ? tempUser.firstName : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({firstName: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Apellidos</label>\n                  <input\n                    type=\"text\"\n                    name=\"lastName\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempUser ? tempUser.lastName : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({lastName: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Email</label>\n                  <input\n                    type=\"email\"\n                    name=\"email\"\n                    disabled={!create}\n                    className=\"form-control\"\n                    maxLength={80}\n                    defaultValue={tempUser ? tempUser.email : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({email: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-company\">Empresa</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-company\"\n                    name=\"venue\"\n                    defaultValue={tempUser && tempUser.company ? tempUser.company._id : undefined}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      companies.map((company) => (\n                        <option key={company._id} value={company._id}>{company.name}</option>\n                      ))\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-venue\">Sucursal</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-venue\"\n                    name=\"venue\"\n                    defaultValue={tempUser && tempUser.venue ? tempUser.venue : undefined}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      venues\n                        .filter((venue) => (\n                          venue.company && tempUser.company && tempUser.company._id === venue.company._id\n                        ))\n                        .map((venue) => (\n                          <option key={venue._id} value={venue._id}>{venue.name}</option>\n                        ))\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Formularios</label>\n                  <select\n                    id=\"id-forms\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      selectForms.map((form) => {\n                        return (\n                          <option key={form._id} value={form._id}>{form.name}</option>\n                        );\n                      })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                  <tr>\n                    <th style={{width: '90%'}}>Name</th>\n                    <th style={{width: '10%'}}/>\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    userForms.length ? userForms.map((form: any) => {\n                      return (\n                        <tr key={form._id}>\n                          <td>{form.name}</td>\n                          <td\n                            className=\"text-center text-red pointer\"\n                            onClick={() => this.deleteForm(form._id)}\n                          >\n                            <i className=\"fa fa-minus-circle\"/>\n                          </td>\n                        </tr>\n                      );\n                      }) :\n                      <tr>\n                        <td colSpan={2}>Aún no se han seleccionado permisos.</td>\n                      </tr>\n                  }\n                  </tbody>\n                </table>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Formulario por defecto</label>\n                  <select\n                    id=\"id-form-default\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    defaultValue={tempUser && tempUser.preferred ? tempUser.preferred : undefined}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      userForms.map((form) => {\n                        return (\n                          <option key={form._id} value={form._id}>{form.name}</option>\n                        );\n                      })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"checkbox\">\n                  <Checkbox\n                    active={tempUser && tempUser.isDriver}\n                    action={this.changeIsDriver}\n                    classes=\"icheck-in-checkbox\"\n                    style={{marginTop: '-4px', marginRight: '5px'}}\n                  />\n                  Es Conductor\n                </div>\n              </div>\n              {\n                window.user.isAdmin ?\n                  <div className=\"col-md-12\">\n                    <div className=\"checkbox\">\n                      <Checkbox\n                        active={tempUser && tempUser.isAdmin}\n                        action={this.changeIsAdmin}\n                        classes=\"icheck-in-checkbox\"\n                        style={{marginTop: '-4px', marginRight: '5px'}}\n                      />\n                      Es ADMIN\n                    </div>\n                  </div>\n                  : null\n              }\n            </div>\n          </div>\n          {\n            window.user.isAdmin || (hasPermission(window.user, 'changeTeamPermissions') && !this.props.user?.isAdmin) ?\n              <div id=\"permissions\" className=\"tab-pane fade\">\n                <div className=\"row\">\n                  <div className=\"col-md-12\">\n                    <div className=\"form-group\">\n                      <label>Permisos</label>\n                      <select\n                        id=\"id-permissions\"\n                        className=\"chosen-select form-control\"\n                        style={{minWidth: '200px'}}\n                        data-placeholder={'Seleccione...'}\n                      >\n                        <option value=\"\"/>\n                        {\n                          selectPermissions.map((permission) => {\n                            return (\n                              <option key={permission._id} value={permission._id}>{permission.name}</option>\n                            );\n                          })\n                        }\n                      </select>\n                    </div>\n                  </div>\n                  <div className=\"col-md-12\">\n                    <table className=\"table table-striped\">\n                      <thead>\n                      <tr>\n                        <th style={{width: '20%'}}>Code</th>\n                        <th style={{width: '70%'}}>Name</th>\n                        <th style={{width: '10%'}}/>\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        userPermissions.length ?\n                          userPermissions.map((permission: any) => {\n                            return (\n                              <tr key={permission._id}>\n                                <td>{permission.codeName}</td>\n                                <td>{permission.name}</td>\n                                <td className=\"text-center text-red pointer\" onClick={() => this.deletePermission(permission._id)}>\n                                  <i className=\"fa fa-minus-circle\"/>\n                                </td>\n                              </tr>\n                            );\n                          })\n                          : <tr>\n                            <td colSpan={3}>Aún no se han seleccionado permisos.</td>\n                          </tr>\n                      }\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n              </div>\n              : null\n          }\n          <div id=\"access\" className=\"tab-pane fade\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Sucursales adicionales</label>\n                  <select\n                    id=\"id-venues-access\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      venues\n                        .filter((venue) => (\n                          !idsUserVenueAccess.includes(venue._id) && venue._id !== tempUser.venue)\n                        )\n                        .map((venue) => {\n                          return (\n                            <option key={venue._id} value={venue._id}>\n                              {venue.name}{venue.company ? ` - ${venue.company.name}` : ''}\n                            </option>\n                          );\n                        })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                  <tr>\n                    <th style={{width: '90%'}}>Sucursal</th>\n                    <th style={{width: '10%'}}/>\n                  </tr>\n                  </thead>\n                  <tbody>\n                    {\n                      tempUser.venue ?\n                        venues\n                          .filter((venue: any) => (venue._id === tempUser.venue))\n                          .map((venue: any) => (\n                            <tr key={venue._id} className=\"bg-aqua-active\">\n                              <td colSpan={2}>{venue.name}{venue.company ? ` - ${venue.company.name}` : ''}</td>\n                            </tr>\n                          ))\n                        : null\n                    }\n                    {\n                      tempUser.venuesAccess.length ?\n                        tempUser.venuesAccess\n                          .filter((venue: any) => (venue._id !== tempUser.venue))\n                          .map((venue: any) => {\n                          return (\n                            <tr key={venue._id}>\n                              <td>{venue.name}{venue.company ? ` - ${venue.company.name}` : ''}</td>\n                              <td className=\"text-center text-red pointer\" onClick={() => this.deleteVenueAccess(venue._id)}><i\n                                className=\"fa fa-minus-circle\"/></td>\n                            </tr>\n                          );\n                        }) :\n                        <tr>\n                          <td colSpan={2}>Aún no se han seleccionado sucursales adicionales.</td>\n                        </tr>\n                    }\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n          <div id=\"request\" className=\"tab-pane fade\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-channel\">Canal</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-channel\"\n                    name=\"channel\"\n                    defaultValue={tempUser?.settings?.defaultChannel}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      channels.map((channel) => (\n                        <option key={channel._id} value={channel._id}>{channel.name}</option>\n                      ))\n                    }\n                  </select>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </React.Fragment>\n    );\n  }\n\n  private changeIsAdmin() {\n    const {isAdmin} = this.props.users.tempUser;\n    this.props.changeTempUser({isAdmin: !isAdmin});\n  }\n\n  private changeIsDriver() {\n    const {isDriver} = this.props.users.tempUser;\n    this.props.changeTempUser({isDriver: !isDriver});\n  }\n\n  private addVenueAccess(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    const {venues} = this.props;\n    const findVenue = venues.find((venue) => venue._id === id);\n    if (findVenue) {\n      changeTempUser({\n        venuesAccess: [findVenue, ...tempUser.venuesAccess]\n      });\n    }\n  }\n\n  private deleteVenueAccess(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    changeTempUser({\n      venuesAccess: tempUser ? tempUser.venuesAccess.filter((venue) => venue._id !== id) : []\n    });\n  }\n\n  private addPermission(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    const {permissions} = this.props;\n    const findPermision = permissions.find((permission) => permission._id === id);\n    if (findPermision) {\n      changeTempUser({\n        userPermissions: [findPermision, ...tempUser.userPermissions]\n      });\n    }\n  }\n\n  private deletePermission(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    changeTempUser({\n      userPermissions: tempUser ? tempUser.userPermissions.filter((permission) => permission._id !== id) : []\n    });\n  }\n\n  private addForm(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    const {forms} = this.props;\n    const findForm = forms.find((form) => form._id === id);\n    if (findForm) {\n      changeTempUser({\n        userForms: [findForm, ...tempUser.userForms]\n      });\n    }\n  }\n\n  private deleteForm(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    changeTempUser({\n      userForms: tempUser ? tempUser.userForms.filter((form) => form._id !== id) : []\n    });\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UserFormView);\n","import { AxiosError, default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport { IUser } from '../../../../../../src/app/interfaces/user.interface';\nimport {\n  loadDataAction,\n  ModalReduxAction\n} from '../../actions/modal.actions';\nimport {\n  changeSearchUserAction,\n  changeTempUserAction,\n  createUserAction,\n  deleteUserAction,\n  getUsersAction,\n  ITempUser,\n  IUsersState,\n  updateUserAction,\n  UserReduxAction\n} from '../../actions/users.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport {\n  hasPermission,\n  showModal,\n  statusFooterButttonsModal\n} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport UserFormChangePasswordView from './UserFormChangePasswordView';\nimport UserFormView from './UserFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { UserTypes } from '../../../../../../src/app/models/user.model.types';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<UserReduxAction>;\n  users: IUsersState;\n\n  getUsersAction(page: number, type: UserTypes, search?: string): UserReduxAction;\n  createUserAction(): UserReduxAction;\n  updateUserAction(): UserReduxAction;\n  deleteUserAction(id?: string): UserReduxAction;\n  changeTempUserAction(user: ITempUser): UserReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  changeSearchUserAction(searchText: string): UserReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass UserListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state = {\n    error: null,\n    searchText: '',\n    exporing: false\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de usuarios';\n    this.createUser = this.createUser.bind(this);\n    this.processCreateUser = this.processCreateUser.bind(this);\n    this.updateUser = this.updateUser.bind(this);\n    this.processUpdateUser = this.processUpdateUser.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.changeTempUser = this.changeTempUser.bind(this);\n    this.changePassword = this.changePassword.bind(this);\n    this.processChangePassword = this.processChangePassword.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.cloneUser = this.cloneUser.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.users;\n    this.props.getUsersAction(pagination.page, UserTypes.common);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `user-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const {pagination} = this.props.users;\n        this.props.getUsersAction(pagination.page, UserTypes.common);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.users.pagination !== prevProps.users.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.users.source) {\n      this.props.users.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public exportExcel() {\n    this.trackClick('Exportar');\n    this.setState({\n      exporing: true\n    });\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/settings/users/export/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-usuarios.xlsx`;\n        // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n        //   // IE workaround for \"HTML7007: One or more blob URLs were\n        //   // revoked by closing the blob for which they were created.\n        //   // These URLs will no longer resolve as the data backing\n        //   // the URL has been freed.\"\n        //   window.navigator.msSaveBlob(blob, fileName);\n        // } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          this.setState({\n            exporing: false\n          });\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n        // }\n      })\n      .catch((err) => {\n        this.setState({\n          exporing: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal!('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n        }\n      });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {exporing} = this.state;\n    const {\n      loading, users, pagination, searchText\n    } = this.props.users;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.5\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Usuarios <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                {\n                  hasPermission(window.user, 'addUser') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createUser}><i className=\"fa fa-plus\" /> Crear usuario</button>\n                    : null\n                }\n                <button\n                  className=\"btn btn-sm btn-primary hidden-xs\"\n                  onClick={this.exportExcel}\n                  disabled={exporing}\n                  style={{marginLeft: '5px'}}\n                >\n                  {\n                    exporing ?\n                      <React.Fragment>\n                        <i className=\"fa fa-spin fa-spinner\"/> Exportando\n                      </React.Fragment>\n                      : <React.Fragment>\n                        <i className=\"fa fa-fw fa-download\"/> Exportar\n                      </React.Fragment>\n                  }\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div className=\"row\">\n                <div className=\"col-md-offset-8 col-md-4\">\n                  <div className=\"input-group input-group-sm\"\n                       style={{padding: '10px'}}\n                  >\n                    <input\n                      type=\"text\"\n                      value={searchText}\n                      className=\"form-control pull-right\"\n                      onChange={this.onChangeSearch}\n                      placeholder=\"Buscar\"/>\n                    <div className=\"input-group-btn\">\n                      <button className=\"btn btn-default\"><i className=\"fa fa-search\"/></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                <tr>\n                  <th style={{width: '24%'}}>Usuario</th>\n                  <th style={{width: '24%'}} className=\"hidden-xs\">Sucursal</th>\n                  <th style={{width: '24%'}} className=\"hidden-xs\">Formularios</th>\n                  <th style={{width: '24%'}} className=\"hidden-xs\">Modificado</th>\n                  {\n                    hasPermission(window.user, 'changeUser') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    hasPermission(window.user, 'addUser') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    window.user.isAdmin || (hasPermission(window.user, 'changeUser')) ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    hasPermission(window.user, 'deleteUser') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && users.length === 0 && users ? <tr>\n                    <td colSpan={6}>No se han encontrado resultados.</td>\n                  </tr> : null\n                }\n                {\n                  users.map((user: IUser) => {\n                    const forms = user.userForms;\n                    return (\n                      <tr\n                        key={user._id}\n                        id={`user-${user._id}`}\n                        className={'background-transition'}\n                      >\n                        <td className=\"middle\">{user.firstName} {user.lastName}<br/>\n                          <span className=\"text-sm text-muted\">{user.email}</span>\n                          <div className=\"hidden-lg hidden-md hidden-sm text-sm\">\n                            <span\n                              className=\"text-sm text-muted\">{user.venue ? user.venue.name : ''} - {user.company ? user.company.name : ''}</span>\n                          </div>\n                        </td>\n                        <td className=\"middle hidden-xs\">{user.venue ? user.venue.name : ''}<br/>\n                          <span className=\"text-sm text-muted\">{user.company ? user.company.name : ''}</span>\n                        </td>\n                        <td className=\"middle hidden-xs\">\n                          {forms.map((form, index) => {\n                            return <React.Fragment key={`${form._id}-${index}`}>\n                              {index > 0 ?\n                                <br/> : null}\n                              <span>{form.name}</span>\n                            </React.Fragment>;\n                          })}\n                        </td>\n                        <td className=\"middle hidden-xs text-muted\">{moment(user.updatedAt).format('LLL')}</td>\n                        {\n                          hasPermission(window.user, 'changeUser') ?\n                            <td className=\"middle-center text-yellow pointer\" onClick={() => this.changePassword(user)}>\n                              <i className=\"fa fa-lock\"/></td> : null\n                        }\n                        {\n                          hasPermission(window.user, 'addUser') ?\n                            <td className=\"middle-center text-blue pointer\" onClick={() => this.cloneUser(user)}>\n                              <i className=\"fa fa-clone\"/></td> : null\n                        }\n                        {\n                          window.user.isAdmin || (hasPermission(window.user, 'changeUser') && !user.isAdmin) ?\n                            <td className=\"middle-center text-blue pointer\" onClick={() => this.updateUser(user)}><i\n                              className=\"fa fa-pencil\"/></td> : <td></td>\n                        }\n                        {\n                          hasPermission(window.user, 'deleteUser') ?\n                            <td className=\"middle-center text-red pointer\" onClick={() => this.deleteUser(user)}><i\n                              className=\"fa fa-minus-circle\"/></td> : null\n                        }\n                      </tr>\n                    );\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages}/>\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private cloneUser(user: IUser): void {\n    const { changeTempUser } = this;\n    const { venues, permissions, forms, companies } = this.props.users;\n    const tmpUser = {\n      ...user,\n      _id: '',\n      firstName: '',\n      lastName: '',\n      email: ''\n    };\n    tmpUser.venue = tmpUser.venue ? tmpUser.venue._id : '';\n    this.props.changeTempUserAction(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Clonando usuario`,\n        <UserFormView\n          create={true}\n          changeTempUser={changeTempUser}\n          companies={companies}\n          venues={venues}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n          user={tmpUser}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateUser}>Crear</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.props.changeSearchUserAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    this.props.getUsersAction(1, UserTypes.common);\n  }\n\n  private createUser(): void {\n    const { changeTempUser } = this;\n    const { venues, permissions, forms, companies } = this.props.users;\n    this.props.changeTempUserAction({\n      _id: '',\n      firstName: '',\n      lastName: '',\n      company: null,\n      email: '',\n      isAdmin: false,\n      isDriver: false,\n      venue: '',\n      userPermissions: [],\n      venuesAccess: [],\n      userForms: [],\n      settings: {}\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Agregar Usuario',\n        <UserFormView\n          create={true}\n          changeTempUser={changeTempUser}\n          venues={venues}\n          companies={companies}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateUser}>Crear</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processCreateUser(): void {\n    const {firstName, lastName, email, venue} = this.props.users.tempUser;\n    if (!firstName || !firstName.trim().length) {\n      swal!('Agregar usuario', 'El nombres es requerido', 'error');\n    } else if (!lastName || !lastName.trim().length) {\n      swal!('Agregar usuario', 'El apellidos es requerido', 'error');\n    } else if (!email || !email.trim().length) {\n      swal!('Agregar usuario', 'El email es requerido', 'error');\n    } else if (!venue || !venue.trim().length) {\n      swal!('Agregar usuario', 'El sucursal es requerido', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.createUserAction();\n    }\n  }\n\n  private changePassword(user: IUser): void {\n    const {changeTempUser} = this;\n    const tmpUser = {\n      ...user,\n      password: ''\n    };\n    changeTempUser(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Cambiando contraseña a ${user.firstName} ${user.lastName}`,\n        <UserFormChangePasswordView changeTempUser={changeTempUser} users={this.props.users} user={user}/>,\n        <React.Fragment>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-default\"\n            data-dismiss=\"modal\"\n          >\n            Cancelar\n          </button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processChangePassword}>Cambiar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processChangePassword() {\n    const {password, _id} = this.props.users.tempUser;\n    statusFooterButttonsModal(true);\n    if (password && password.trim().length >= 6 && _id) {\n      const api: ApiService = new ApiService();\n      api.changePasswordUser(_id, password)\n        .then((response) => {\n          statusFooterButttonsModal(false);\n          showModal(false);\n          swal!(response.data.message, {\n            icon: 'success'\n          });\n        })\n        .catch((err: AxiosError) => {\n          statusFooterButttonsModal(false);\n          api.errorHandler(err);\n        });\n    } else {\n      swal!('Cambiar contraseña', 'La contraseña debe tener al menos 6 caracteres.', 'error');\n      statusFooterButttonsModal(false);\n    }\n  }\n\n  private updateUser(user: IUser): void {\n    const {changeTempUser} = this;\n    const {venues, permissions, forms, companies} = this.props.users;\n    const tmpUser = {...user};\n    tmpUser.venue = tmpUser.venue ? tmpUser.venue._id : '';\n    changeTempUser(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Editando a ${user.firstName} ${user.lastName}`,\n        <UserFormView\n          create={false}\n          changeTempUser={changeTempUser}\n          companies={companies}\n          venues={venues}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n          user={user}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateUser}>Editar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processUpdateUser() {\n    const {firstName, lastName, email, venue} = this.props.users.tempUser;\n    if (!firstName || !firstName.trim().length) {\n      swal!('Agregar usuario', 'El nombres es requerido', 'error');\n    } else if (!lastName || !lastName.trim().length) {\n      swal!('Agregar usuario', 'El apellidos es requerido', 'error');\n    } else if (!email || !email.trim().length) {\n      swal!('Agregar usuario', 'El email es requerido', 'error');\n    } else if (!venue || !venue.trim().length) {\n      swal!('Agregar usuario', 'El sucursal es requerido', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.updateUserAction();\n    }\n  }\n\n  private changeTempUser({_id, firstName, lastName, email, venue, userPermissions, preferred, userForms, company, venuesAccess, password, isAdmin, isDriver, settings}: ITempUser) {\n    const tempUser: ITempUser = {\n      _id: _id ? _id : this.props.users.tempUser._id,\n      firstName: firstName ? firstName : this.props.users.tempUser.firstName,\n      lastName: lastName ? lastName : this.props.users.tempUser.lastName,\n      isAdmin: typeof isAdmin === 'boolean' ? isAdmin : this.props.users.tempUser.isAdmin,\n      isDriver: typeof isDriver === 'boolean' ? isDriver : this.props.users.tempUser.isDriver,\n      password: password ? password : '',\n      settings: settings ?? this.props.users.tempUser.settings,\n      email: email ? email : this.props.users.tempUser.email,\n      userPermissions: userPermissions ? userPermissions : this.props.users.tempUser.userPermissions,\n      userForms: userForms ? userForms : this.props.users.tempUser.userForms,\n      preferred: preferred ? preferred : preferred === undefined ? this.props.users.tempUser.preferred : null,\n      venue: venue ? venue : venue === undefined ? this.props.users.tempUser.venue : null,\n      venuesAccess: venuesAccess ? venuesAccess : venuesAccess === undefined ? this.props.users.tempUser.venuesAccess : [],\n      company: company ? company : company === undefined ? this.props.users.tempUser.company : null\n    };\n    this.props.changeTempUserAction(tempUser);\n  }\n\n  private deleteUser(user: IUser) {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el usuario ${user.firstName || ''} ${user.lastName || ''}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteUserAction(user._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getUsersAction(page, UserTypes.common );\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\n// const mapDispatchToProps = (dispatch: Dispatch<UserReduxAction> ) => {\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getUsersAction: (nextPage: number, type: UserTypes, search?: string) => dispatch(getUsersAction(nextPage, type, search)),\n    deleteUserAction: (id: string) => dispatch(deleteUserAction(id)),\n    changeTempUserAction: (user: ITempUser) => dispatch(changeTempUserAction(user)),\n    createUserAction: () => dispatch(createUserAction()),\n    updateUserAction: () => dispatch(updateUserAction()),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    changeSearchUserAction: (searchText: string) => dispatch(changeSearchUserAction(searchText))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UserListView);\n","import * as React from 'react';\nimport {RefObject} from 'react';\n\ninterface IPropsType {\n  value: string;\n\n  items: any[];\n  inputClass?: string;\n\n  renderItem(item: any, index: any): React.ReactElement<any>;\n  onChange(e: React.ChangeEvent<HTMLInputElement>): void;\n  onSelect(item: any): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  open: boolean;\n}\n\nclass AutoCompleteInput extends React.Component<IPropsType, IStateType>{\n\n  readonly state = {\n    error: null,\n    open: false\n  };\n  readonly autocompleteElement: RefObject<HTMLInputElement>;\n  readonly items: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeOpen = this.changeOpen.bind(this);\n    this.close = this.close.bind(this);\n    this.outsideClick = this.outsideClick.bind(this);\n    this.renderItem = this.renderItem.bind(this);\n    this.autocompleteElement = React.createRef();\n    this.items = React.createRef();\n  }\n\n  public componentDidMount(): void {\n    document.addEventListener('keydown', this.close, true);\n    document.addEventListener('click', this.outsideClick, true);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { onChange, value, items, inputClass } = this.props;\n    return (\n      <div className=\"autocomplete\" ref={this.autocompleteElement} >\n        <input\n          type=\"text\"\n          className={`form-control ${inputClass ? inputClass : ''}`}\n          onChange={(e) => {\n            if (this.items.current) {\n              this.items.current.scrollTop = 0;\n            }\n            this.setState({\n              open: true\n            });\n            onChange(e);\n          }}\n          value={value}\n          onClick={this.changeOpen}\n          autoComplete={'off'}\n        />\n        {\n          this.state.open ?\n            <div className=\"items\" ref={this.items}>\n              {\n                items.map((item, index) => (\n                  this.renderItem(item, index)\n                ))\n              }\n            </div>\n            : null\n        }\n      </div>\n    );\n  }\n\n  private renderItem(item: any, index: any) {\n    const element = this.props.renderItem(item, index);\n    return React.cloneElement(element, {\n      onClick: () => {\n        this.props.onSelect(item);\n        this.changeOpen();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    document.removeEventListener('keydown', this.close, true);\n    document.removeEventListener('click', this.outsideClick, true);\n  }\n\n  private close(e: any): void {\n    // if ((e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) && (e.target.nodeName === 'BODY')) {\n    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {\n      e.preventDefault();\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private outsideClick(e: any): void{\n    if(!this.autocompleteElement.current!.contains(e.target)){\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private changeOpen(): void {\n    const {open} = this.state;\n    this.setState({\n      open: !open\n    });\n  }\n}\n\nexport default AutoCompleteInput;\n","import * as React from 'react';\nimport { RefObject } from 'react';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ajax } from 'rxjs/ajax';\nimport { IRequestItem } from '../../../../../../src/request/interfaces';\nimport ApiService from '../../utils/axios';\nimport { AxiosError, AxiosResponse } from 'axios';\nimport { hasPermission, parseReplicableURL } from '../../utils/common';\nimport ShowIf from './ShowIf';\nimport { Subject } from 'rxjs/internal/Subject';\nimport { IWindow } from '../../interfaces/window';\n\ninterface IPropsType {\n  defaultValue: string;\n  inputClass?: string;\n  item: IRequestItem;\n  history: any;\n  renderItem(item: any, index: any): React.ReactElement<any>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  open: boolean;\n  canEdit: boolean;\n  value: string;\n  VINRecommends: any[];\n}\n\ndeclare let window: IWindow;\n\nclass AutoCompleteVinInput extends React.Component<IPropsType, IStateType> {\n  readonly $subjectVINRecommends = new Subject<any>();\n  readonly api: ApiService;\n  readonly autocompleteElement: RefObject<HTMLInputElement>;\n  readonly items: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeOpen = this.changeOpen.bind(this);\n    this.close = this.close.bind(this);\n    this.outsideClick = this.outsideClick.bind(this);\n    this.renderItem = this.renderItem.bind(this);\n    this.searchVin = this.searchVin.bind(this);\n    this.updateVin = this.updateVin.bind(this);\n    this.openVehicle = this.openVehicle.bind(this);\n    this.autocompleteElement = React.createRef();\n    this.api = new ApiService();\n    this.items = React.createRef();\n    this.state = {\n      error: null,\n      open: false,\n      value: this.props.defaultValue,\n      canEdit: false,\n      VINRecommends: []\n    };\n    this.$subjectVINRecommends.pipe(\n      debounceTime(300),\n      switchMap(({ vin, material }: { vin: string, material: string }) => {\n        return ajax({\n          url: `/api/v1/requests/search-vin/?vin=${vin}&material=${material}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        VINRecommends: response.response.data\n      });\n    });\n  }\n\n  public componentWillReceiveProps(nextProps: Readonly<IPropsType>, nextContext: any) {\n    if (nextProps.defaultValue !== this.props.defaultValue) {\n      this.setState({\n        value: nextProps.defaultValue\n      });\n    }\n  }\n\n  public componentDidMount(): void {\n    document.addEventListener('keydown', this.close, true);\n    document.addEventListener('click', this.outsideClick, true);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { defaultValue, inputClass, item } = this.props;\n    const { VINRecommends, canEdit, value } = this.state;\n    return (\n      <div className='autocomplete' ref={this.autocompleteElement}>\n        <div\n          className='input-group input-group-sm'\n        >\n          {\n            !canEdit ?\n              <ShowIf condition={hasPermission(window.user, 'viewCar') && item.car.vin?.length > 0}>\n              <span\n                className='input-group-addon pointer bg-primary'\n                style={{ padding: '5px' }}\n                onClick={this.openVehicle}\n              >\n                <i className='fa fa-fw fa-external-link-square' />\n              </span>\n              </ShowIf>\n              : <span\n                className='input-group-addon pointer bg-red'\n                style={{ padding: '5px' }}\n                onClick={() => {\n                  this.setState({\n                    value: defaultValue || '',\n                    canEdit: false\n                  });\n                }}\n              >\n                <i className='fa fa-fw fa-close' />\n              </span>\n          }\n          <input\n            type='text'\n            className={`form-control ${inputClass ? inputClass : ''}`}\n            onChange={(e) => {\n              const { value } = e.target;\n              if (this.items.current) {\n                this.items.current.scrollTop = 0;\n              }\n              this.setState({\n                open: true,\n                value\n              });\n              this.searchVin(value, item.car.material);\n            }}\n            style={{ padding: '5px' }}\n            disabled={!canEdit}\n            value={value}\n            onClick={this.changeOpen}\n            autoComplete={'off'}\n          />\n          <div\n            className={`input-group-addon pointer ${canEdit ? 'bg-green' : ''}`}\n            onClick={() => {\n              if (canEdit) {\n                this.updateVin(value);\n              } else {\n                this.setState({\n                  canEdit: true\n                });\n              }\n            }}\n          >\n            <i className={`fa ${canEdit ? 'fa fa-save' : 'fa fa-pencil'}`} />\n          </div>\n        </div>\n        {\n          this.state.open ?\n            <div className='items' ref={this.items}>\n              {\n                VINRecommends.map((item, index) => (\n                  this.renderItem(item, index)\n                ))\n              }\n            </div>\n            : null\n        }\n      </div>\n    );\n  }\n\n  private renderItem(item: any, index: any) {\n    const element = this.props.renderItem(item, index);\n    return React.cloneElement(element, {\n      onClick: () => {\n        this.setState({\n          value: item.vin\n        });\n        this.changeOpen();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    document.removeEventListener('keydown', this.close, true);\n    document.removeEventListener('click', this.outsideClick, true);\n  }\n\n  private close(e: any): void {\n    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {\n      e.preventDefault();\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private updateVin(vin: string) {\n    const { item } = this.props;\n    this.api.uppdateRequestItemVin(item, vin)\n      .then((response: AxiosResponse) => {\n        console.log('responde', response);\n        this.setState({\n          canEdit: false\n        });\n        // transmittalActions.updateTransmittalAction(response.data.data);\n      })\n      .catch((err: AxiosError) => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  openVehicle() {\n    const { item } = this.props;\n    this.props.history.push(parseReplicableURL(`/settings/cars/${item.car._id}`));\n    // window.open(parseReplicableURL(`/settings/cars/${item.car._id}/`), '_blank');\n  }\n\n\n  private searchVin(vin: string, material: string): void {\n    this.$subjectVINRecommends.next({ vin, material });\n  }\n\n  private outsideClick(e: any): void {\n    if (!this.autocompleteElement.current!.contains(e.target)) {\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private changeOpen(): void {\n    const { open } = this.state;\n    this.setState({\n      open: !open\n    });\n  }\n}\n\nexport default AutoCompleteVinInput;\n","import * as React from 'react';\nimport * as unorm from 'unorm';\nimport {RefObject} from 'react';\n\ninterface IOption {\n  value: string;\n  text: any;\n  className?: string;\n}\n\ninterface IPropsType {\n  options: IOption[];\n  selected: string[];\n  className?: string;\n  displayItems?: number;\n  onClick: any;\n  selectAll?: any;\n  noneSelectedText?: string;\n  selectedText?: string;\n  separator?: string;\n  allOption?: boolean;\n  autoClouse?: boolean;\n  search?: boolean;\n  sm?: boolean;\n  displayHandler?: (value: boolean) => void;\n  notHideOnClickOutside?: boolean\n}\n\ninterface IStateType {\n  open: boolean;\n  searchText: string;\n}\n\nclass BootstrapSelect extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    open: false,\n    searchText: ''\n  };\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly dropdown: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerOpen = this.handlerOpen.bind(this);\n    this.search = this.search.bind(this);\n    this.input = React.createRef();\n    this.dropdown = React.createRef();\n  }\n\n  componentDidMount() {\n    const {notHideOnClickOutside, autoClouse} = this.props;\n    if (notHideOnClickOutside && !autoClouse) {\n      $('.osa-dropwdown-button').on('click', (event) => {\n        $('.osa-dropdown').toggleClass('open');\n      });\n    }\n  }\n\n  componentWillUnmount() {\n    const {notHideOnClickOutside, autoClouse} = this.props;\n    if (notHideOnClickOutside && !autoClouse) {\n      $('.osa-dropwdown-button').remove('click')\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      sm, options, selected, onClick, displayItems, noneSelectedText, selectedText, separator, allOption, search, autoClouse, selectAll, notHideOnClickOutside\n    } = this.props;\n    const  {searchText} = this.state;\n    const selectedItems = options.filter((option) => (selected.includes(option.value)));\n\n    return (\n      <div\n        ref={this.dropdown}\n        className={`osa-dropdown dropdown bootstrap-select form-control show-tick ${autoClouse ? '' : 'keep-inside-clicks-open'} ${sm?'bootstrap-select-sm':''}`}>\n        <button\n          type=\"button\"\n          className={`osa-dropwdown-button btn dropdown-toggle bs-placeholder btn-filter btn-default`}\n          data-toggle={notHideOnClickOutside && !autoClouse ? '' : \"dropdown\"}\n          style={{borderRadius: '0px'}}\n          onClick={this.handlerOpen}\n        >\n          <div className=\"filter-option\">\n            <div className=\"filter-option-inner\">\n              <div className=\"filter-option-inner-inner\">\n                {\n                  selectedItems.length ?\n                    displayItems && selectedItems.length > displayItems ?\n                      <span style={{color: '#555'}}>{`${selectedItems.length} ${selectedText ? selectedText : 'items seleccionados.'}`}</span> :\n                      selectedItems\n                        .map((option, index) => (\n                          <React.Fragment key={index}>\n                            <span\n                              className={option.className ? option.className : ''}\n                              style={{color: '#555'}}\n                            >{option.text}</span> {selectedItems.length > index + 1 ? separator ? `${separator}` : ', ' : null}\n                          </React.Fragment>\n                        ))\n                    : noneSelectedText ? <span style={{color: '#999'}}> {noneSelectedText}</span> : <span style={{color: '#999'}}> Todos </span>\n                }\n              </div>\n            </div>\n          </div>\n          <span className=\"bs-caret\">\n            <span className=\"caret\" />\n          </span>\n        </button>\n        <div className=\"dropdown-menu\" style={{borderRadius: '0px'}}>\n          {\n            search ?\n              <div className=\"bs-searchbox\">\n                <input\n                  ref={this.input}\n                  type=\"text\"\n                  className=\"form-control input-sm\"\n                  autoComplete=\"off\"\n                  value={this.state.searchText}\n                  onChange={\n                    (e: React.ChangeEvent<HTMLInputElement>) => this.search(e.target.value)\n                  }\n                />\n              </div> : null\n          }\n          {\n            allOption ?\n              <div className=\"bs-actionsbox\">\n                <div className=\"btn-group btn-group-sm btn-block\">\n                  <button\n                    onClick={() => selectAll(true)}\n                    type=\"button\" className=\"actions-btn bs-select-all btn btn-default\">Seleccionar todo\n                  </button>\n                  <button\n                    onClick={() => selectAll(false)}\n                    type=\"button\" className=\"actions-btn bs-deselect-all btn btn-default\">Deseleccionar todo\n                  </button>\n                </div>\n              </div> : null\n          }\n          <div\n            className=\"inner open\"\n            aria-expanded=\"false\"\n            tabIndex={-1}\n          >\n            <ul className=\"dropdown-menu inner\" style={{maxHeight: '30vh', overflowY: 'auto'}}>\n              {\n                options.filter((option) => {\n                  if (!searchText || !searchText.length) {\n                    return true;\n                  }\n                  return unorm.nfd(option.text)\n                    .replace(/[\\u0300-\\u036f]/g, '')\n                    .toLowerCase()\n                    .includes(searchText.toLowerCase());\n                }).map((option) => {\n                  const isSelected = selected.includes(option.value);\n                  return (\n                    <li key={option.value} className={`${isSelected ? 'selected' : ''}`} onClick={() => onClick(option.value)}>\n                      <a role=\"option\" tabIndex={0} className={`${isSelected ? 'selected' : ''}`} style={{background: '#FFF'}}>\n                        <span className=\"glyphicon glyphicon-ok check-mark\" />\n                        <span className={option.className ? option.className : ''}>{option.text}</span>\n                      </a>\n                    </li>\n                  );\n                })\n              }\n            </ul>\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private handlerOpen() {\n    // https://codepen.io/qpqinc/pen/yLyPVMJ\n    if (this.props.displayHandler != null){\n      this.props.displayHandler(!this.state.open);\n    }\n    if(this.input.current){\n      this.input.current.focus()\n    }\n    this.setState({\n        open: !this.state.open\n      }, () => {\n        if (!this.state.open) {\n          this.search('');\n        }\n      }\n    );\n  }\n\n  private search(searchText: string) {\n    this.setState({\n      searchText: unorm.nfd(searchText).replace(/[\\u0300-\\u036f]/g, '')\n    });\n  }\n}\n\nexport default BootstrapSelect;\n","import * as React from 'react';\n\ninterface IPropsType {\n  checked: boolean;\n  onChange: any;\n  color?: string;\n}\n\nclass BootstrapSwitch extends React.Component<IPropsType, {}> {\n\n  state = {\n    hover: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {checked, onChange, color} = this.props;\n    return (\n      <label className={`switch ${color ? `switch-${color}` : ''}`}>\n        <input type=\"checkbox\" className=\"switch\" checked={checked} onChange={onChange}/>\n        <span className=\"slider round\"/>\n      </label>\n    );\n  }\n}\n\nexport default BootstrapSwitch;\n","import * as React from 'react';\n// import {CSSProperties} from 'react';\n\ninterface IPropsType {\n  color?: string;\n  active?: boolean;\n  action: any;\n  classes?: string;\n  style?: React.CSSProperties;\n}\n\ninterface IStateType {\n  hover: boolean;\n}\n\nclass Checkbox extends React.Component<IPropsType, IStateType> {\n\n  state = {\n    hover: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.mouseOver = this.mouseOver.bind(this);\n    this.mouseOut = this.mouseOut.bind(this);\n  }\n\n  private mouseOver(): void {\n    this.setState({\n      hover: true\n    });\n  }\n\n  private mouseOut(): void {\n    this.setState({\n      hover: false\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {hover} = this.state;\n    const {color, active, action, classes, style} = this.props;\n    const classIcheck: string[] = [];\n\n    // set color\n    if (color) {\n      classIcheck.push(`icheckbox_square-${color}`);\n    } else {\n      classIcheck.push('icheckbox_square-blue');\n    }\n\n    // if mouse hover\n    if (hover) {\n      classIcheck.push('hover');\n    }\n\n    if (classes) {\n      classIcheck.push(classes);\n    }\n\n    // if checked\n    if (active) {\n      classIcheck.push('checked');\n    }\n\n    return (\n      <div\n        className={classIcheck.join(' ')}\n        onMouseOver={this.mouseOver}\n        onMouseOut={this.mouseOut}\n        onClick={action}\n        style={style ? style : {}}\n      >\n      </div>\n    );\n  }\n}\n\nexport default Checkbox;\n","import * as React from 'react';\n\ninterface IPropsType {\n  value: string;\n  className?: string;\n}\n\nclass CopyText extends React.Component<IPropsType, {}> {\n\n  private element: React.RefObject<HTMLDivElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.element = React.createRef();\n    this.copyToClipboard = this.copyToClipboard.bind(this);\n  }\n\n  showNotification(value: string) {\n    if ($('#center-message').length) {\n      $('#center-message').remove();\n    }\n    const div = document.createElement('div');\n    div.id = 'center-message';\n    div.textContent = `${value} copiado a clipboard.`;\n    document.body.appendChild(div);\n    $('#center-message').fadeIn();\n    setTimeout(() => {\n      const $centerMessage = $('#center-message');\n      $centerMessage.fadeOut('slow', () => {\n        if ($centerMessage.length) {\n          $centerMessage.remove();\n        }\n      });\n    }, 1500);\n  }\n\n  copyToClipboard() {\n    const {value} = this.props;\n    if (value && value.length && this.element.current) {\n      const element = document.createElement('input');\n      element.value = value;\n      // element.type = 'hidden';\n      this.element.current.appendChild(element);\n      element.select();\n      document.execCommand('copy');\n      this.element.current.removeChild(element);\n      this.showNotification(value);\n    }\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {className} = this.props;\n    return (\n      <span className={className ? className : ''} ref={this.element}>\n        {this.props.children}{' '}\n        <i\n          className=\"fa text-black fa-copy pointer hidden-xs hidden-sm\"\n          onClick={this.copyToClipboard}\n          data-toggle=\"tooltip\"\n          data-placement=\"top\"\n          title=\"Copiar a clipboard\"\n          style={{\n            fontSize: '80%'\n          }}\n        />\n      </span>\n    );\n  }\n}\n\nexport default CopyText;\n","import * as React from 'react';\nimport { createRef, RefObject } from 'react';\n\ninterface IPropsType {\n  options: daterangepicker.Options,\n  startDate: Date,\n  endDate: Date,\n  onChange: (from: Date, to: Date) => void,\n}\n\ninterface IStateType {\n  from: Date,\n  to: Date\n}\n\nclass DateRangeInput extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    from: this.props.startDate,\n    to: this.props.startDate\n  };\n  pickerRef: RefObject<HTMLInputElement> = createRef();\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChange = this.onChange.bind(this);\n  }\n\n  componentDidMount(): void {\n    const { options, startDate, endDate } = this.props;\n    $(this.pickerRef.current!).daterangepicker({ ...options, startDate, endDate }, (from: any, to: any) => {\n      this.onChange(from, to);\n    });\n  }\n\n  onChange = (from: Date, to: Date) => {\n    this.setState({\n      from,\n      to\n    }, () => {\n      this.props.onChange(from, to);\n    });\n  };\n\n  render() {\n    return <div className='input-group input-group-sm' style={{ padding: '10px 5px' }}>\n      <input type='text' className='form-control input-sm' ref={this.pickerRef} />\n      <div className='input-group-btn'>\n        <button className='btn btn-default' onClick={() => {\n          ($(this.pickerRef.current!) as any).click();\n        }}>\n          <i className='fa fa-calendar' /></button>\n      </div>\n    </div>;\n  }\n\n}\n\nexport default DateRangeInput;\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { CSSProperties, RefObject } from 'react';\n\ninterface IPropsType {\n  onChange?: (e: moment.Moment | null) => void;\n  className?: string;\n  format?: string;\n  style?: CSSProperties;\n  value?: any;\n  disabled?: any;\n\n  startDate?: any\n  todayHighlight?: boolean\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DateRangePicker extends React.Component<IPropsType, IStateType> {\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly inputGroup: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.input = React.createRef();\n    this.inputGroup = React.createRef();\n    this.clickCalendar = this.clickCalendar.bind(this);\n  }\n\n  public componentDidMount() {\n    const { format } = this.props;\n    $(this.input.current!).datepicker({\n      autoclose: true,\n      language: 'es',\n      todayHighlight: !!this.props.todayHighlight,\n      orientation: 'bottom auto',\n      clearBtn: true,\n      startDate: this.props.startDate,\n      format: {\n        toDisplay: (date) => {\n          return moment(date).utc().format(format ?? 'DD-MM-YY');\n        },\n        toValue: (date) => {\n          return moment(date, format ?? 'DD-MM-YY').utc().toDate();\n        }\n      }\n    });\n    $(this.input.current!).on('changeDate', () => {\n      if (typeof (this.props.onChange) === 'function') {\n        const date = moment(this.input.current!.value, format ?? 'DD-MM-YY', true);\n        if (date.isValid()) {\n          this.props.onChange(date);\n        } else {\n          this.props.onChange(null);\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount() {\n    $(this.input.current!).datepicker('destroy');\n  }\n\n  private clickCalendar() {\n    $(this.input.current!).datepicker('show');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { format, value, disabled } = this.props;\n    return (\n      <div className='input-group'>\n        <input\n          ref={this.input}\n          type=\"text\"\n          disabled={disabled}\n          value={value?.toString().length ? moment(value).format(format ?? 'DD-MM-YY') : ''}\n          className={`form-control ${this.props.className ?? ''}`}\n          onChange={() => {\n          }}\n          style={{ ...this.props.style }}\n        />\n        <span className='input-group-addon pointer' onClick={this.clickCalendar}>\n          <i className='fa fa-calendar' />\n        </span>\n      </div>\n    );\n  }\n}\n\nexport default DateRangePicker;\n","import * as React from 'react';\nimport {\n  CSSProperties,\n  RefObject\n} from 'react';\n\ninterface IPropsType {\n  url: string;\n  height: string;\n  small?: boolean;\n  style?: React.CSSProperties;\n  replaceLoading?: any;\n}\n\ninterface IStateType {\n  loading: boolean;\n  inViewPort: boolean;\n  error: boolean;\n  eventRuning: boolean;\n  bounding: any;\n  height: any;\n}\n\nclass ImageLazyLoad extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    loading: true,\n    eventRuning: false,\n    inViewPort: false,\n    error: false,\n    bounding: null,\n    height: null\n  };\n\n  private element: RefObject<HTMLDivElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.element = React.createRef();\n    this.handleImageLoaded = this.handleImageLoaded.bind(this);\n    this.isInViewport = this.isInViewport.bind(this);\n    this.addEventListener = this.addEventListener.bind(this);\n    this.removeEventListener = this.removeEventListener.bind(this);\n    this.error = this.error.bind(this);\n  }\n\n  public componentDidMount() {\n    this.addEventListener();\n  }\n\n  public componentWillUnmount() {\n    this.removeEventListener();\n  }\n\n  public render() {\n    const { loading, inViewPort } = this.state;\n    const { url, height, small, style, replaceLoading } = this.props;\n\n    let imageStyle: CSSProperties = {};\n    if (loading) {\n      imageStyle.display = 'none';\n    } else if (style) {\n      imageStyle = style;\n    }\n\n    return (\n      <React.Fragment>\n        {\n          inViewPort ?\n            <img\n              src={url}\n              onLoad={this.handleImageLoaded}\n              onError={this.error}\n              style={imageStyle}\n            /> : null\n        }\n        {\n          loading ?\n            replaceLoading ?\n              <span ref={this.element}>{replaceLoading}</span> :\n              <div\n                style={{\n                  height,\n                  display: 'table-cell',\n                  verticalAlign: 'middle'\n                }}\n                className={'text-center'}\n                ref={this.element}\n              >\n                {\n                  small\n                    ? (\n                      <i className={'fa fa-circle-o-notch fa-spin'} />\n                    )\n                    : (\n                      <i className={'fa fa-circle-o-notch fa-spin fa-2x'} />\n                    )\n                }\n              </div> : null\n        }\n\n      </React.Fragment>\n    );\n  }\n\n  private error() {\n    this.setState({\n      error: true\n    });\n  }\n\n  private handleImageLoaded() {\n    const { url } = this.props;\n    sessionStorage.setItem(url, 'true');\n    this.setState({\n      loading: false\n    });\n  }\n\n  private isInViewport() {\n    if (!this.state.inViewPort && this.element.current) {\n      const bounding = this.element.current.getBoundingClientRect();\n      // start load distance\n      const distance = 300;\n      const clientHeight: number = document && document.documentElement ? document.documentElement.clientHeight : 0;\n      const height = window.innerHeight || clientHeight;\n      const isInViewPort = (\n        bounding.top >= 0 &&\n        bounding.left >= 0 &&\n        (bounding.bottom - distance) <= height\n      );\n\n      if (isInViewPort) {\n        this.removeEventListener();\n        this.setState({\n          inViewPort: true\n        });\n      }\n    }\n  }\n\n  private addEventListener() {\n    this.setState({\n      eventRuning: true\n    });\n    // const modal = document.getElementById('andesModal');\n    let modal = ($('#andesModal').data('bs.modal') || {}).isShown;\n    if (modal) {\n      modal = document.getElementById('andesModal');\n      modal.addEventListener('scroll', this.isInViewport, false);\n      modal.addEventListener('rezise', this.isInViewport, false);\n      setTimeout(() => {\n        this.isInViewport();\n      }, 1000);\n    } else {\n      window.addEventListener('scroll', this.isInViewport, false);\n      window.addEventListener('rezise', this.isInViewport, false);\n      this.isInViewport();\n    }\n  }\n\n  private removeEventListener() {\n    this.setState({\n      eventRuning: false\n    });\n    // const modal = document.getElementById('andesModal');\n    let modal = ($('#andesModal').data('bs.modal') || {}).isShown;\n    if (modal) {\n      modal = document.getElementById('andesModal');\n      modal.removeEventListener('scroll', this.isInViewport, false);\n      modal.removeEventListener('rezise', this.isInViewport, false);\n    } else {\n      window.removeEventListener('scroll', this.isInViewport, false);\n      window.removeEventListener('rezise', this.isInViewport, false);\n    }\n  }\n}\n\nexport default ImageLazyLoad;\n","import * as Mixpanel from 'mixpanel-browser';\nimport {IUser} from \"../../../../../../src/app/interfaces/user.interface\";\nimport {IWindow} from \"../../interfaces/window\";\n\ndeclare let window: IWindow;\n\nclass MixpanelTracker {\n  private static instance : MixpanelTracker;\n\n  static getInstance() : MixpanelTracker {\n    if (!this.instance)\n      this.instance = new MixpanelTracker();\n    return this.instance;\n  }\n\n  private constructor() {\n    Mixpanel.init(window.MIXPANEL);\n  }\n\n  public trackAction(title: string, properties: any = {}) : void {\n    Mixpanel.track(title, properties);\n  }\n\n  public identifyUser(user : IUser) : void {\n    Mixpanel.register({\n      'team': user.team.name,\n      'team_id': user.team._id,\n      'company': user.company.name,\n      'company_id': user.company._id,\n      'venue': user.venue.name,\n      'venue_id': user.venue._id,\n    });\n    Mixpanel.identify(user._id);\n    Mixpanel.people.set( user._id, {\n      '$first_name': user.firstName,\n      '$last_name': user.lastName,\n      '$email': user.email,\n      'team': user.team.name,\n      'team_id': user.team._id,\n      'company': user.company.name,\n      'company_id': user.company._id,\n      'venue': user.venue.name,\n      'venue_id': user.venue._id,\n    });\n  }\n\n}\n\nexport default MixpanelTracker;\n","import axios from 'axios';\nimport * as React from 'react';\nimport { ChangeEvent, DragEvent, ErrorInfo, RefObject } from 'react';\nimport * as uuid from 'uuid';\nimport { getExtension, getIconFromExtension } from '../../utils/common';\nimport Raven = require('raven-js');\nimport ShowIf from './ShowIf';\nimport ApiService from '../../utils/axios';\nimport * as swal from 'sweetalert';\n\n\ninterface IPropsType {\n  onChange: (e: any) => void;\n  deleteCalback?: (e: any) => void;\n  className?: string;\n  body?: any;\n  files: any[];\n  url: string;\n  listMode?: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n}\n\nexport enum imageStatus {\n  pending = 'pending',\n  inProgress = 'inProgress',\n  complete = 'complete'\n}\n\nclass MultiUploadFiles extends React.Component<IPropsType, IStateType> {\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly api: ApiService;\n  readonly state = {\n    error: null,\n    canDrop: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.processFile = this.processFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.uploadImages = this.uploadImages.bind(this);\n    this.deleteFile = this.deleteFile.bind(this);\n    this.getSizeText = this.getSizeText.bind(this);\n    this.downloadFile = this.downloadFile.bind(this);\n    this.inputFile = React.createRef();\n    this.api = new ApiService();\n  }\n\n  public downloadFile(file: any) {\n    window.open(file.url, \"_blank\")\n    // this.api.getInstance()({\n    //   url: file.url,\n    //   method: 'GET',\n    //   responseType: 'blob'\n    // })\n    //   .then((response) => {\n    //     const url = window.URL\n    //       .createObjectURL(new Blob([response.data]));\n    //     const link = document.createElement('a');\n    //     link.href = url;\n    //     link.setAttribute('download', file.name);\n    //     document.body.appendChild(link);\n    //     link.click();\n    //     document.body.removeChild(link);\n    //   });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public render() {\n    const { files, listMode, className } = this.props;\n    return (\n      <div className={`multi-upload ${listMode ? 'list-mode' : ''} ${className}`}>\n        <ShowIf condition={!listMode}>\n          {\n            files.map((file) => (\n              <div className='item-container multi-upload-item' key={file?._id ||file.tmpID}>\n                <div\n                  className='delete-button pointer'\n                  onClick={() => this.deleteFile(file?._id ||file.tmpID)}\n                >\n                  <i className='fa fa-minus-circle' />\n                </div>\n                {\n                  file.isImage ?\n                    <img\n                      src={file.url}\n                      className='image-item'\n                      style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                    /> :\n                    <div className='item'>\n                      <div\n                        className={`icon-file ${getIconFromExtension(getExtension(file.name))}`}\n                        style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                      />\n                      <p\n                        className='text-description'\n                        data-toggle='tooltip'\n                        data-placement='top'\n                        title={file.name}\n                        style={{\n                          paddingBottom: 0\n                        }}\n                      >\n                        {file.name}\n                      </p>\n                      <p\n                        className='text-description'\n                        style={{\n                          color: '#9e9e9e',\n                          paddingTop: 0\n                        }}\n                      >{this.getSizeText(file.size)}</p>\n                    </div>\n                }\n                {\n                  file.status === imageStatus.inProgress ?\n                    <div className='multi-upload-progress-bar'>\n                      <div className='multi-progress' style={{ width: `${file.progress}%` }} />\n                    </div> : null\n                }\n              </div>\n            ))\n          }\n        </ShowIf>\n        <ShowIf condition={!!listMode}>\n          <div className='border-bottom'>\n            {\n              files.map((file) => (\n                <React.Fragment key={file._id || file?._id ||file.tmpID}>\n                  <div className='row border' style={{margin: 0}}>\n                    {/*<div*/}\n                    {/*  className='delete-button pointer'*/}\n                    {/*  onClick={() => this.deleteFile(file.tmpID)}*/}\n                    {/*>*/}\n                    {/*  <i className='fa fa-minus-circle' />*/}\n                    {/*</div>*/}\n                    {\n                      file.isImage ?\n                        <div className='col-md-2'>\n                          <img\n                            src={file.url}\n                            className='image-item'\n                            style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                          />\n                        </div> :\n                        <div className='col-md-2'>\n                          <div className='item'>\n                            <div\n                              className={`icon-file ${getIconFromExtension(getExtension(file.name))}`}\n                              style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                            />\n                          </div>\n                        </div>\n                    }\n                    <div className='col-md-8' style={{ paddingTop: '20px' }}>\n                      {file.name} <br />\n                      <span className={'text-muted text-sm'}>{this.getSizeText(file.size)}</span>\n                    </div>\n                    <div\n                      className='col-md-1 text-right pointer'\n                      onClick={()=> this.downloadFile(file)}\n                      style={{paddingTop: \"25px\"}}>\n                      <i className='fa fa-download text-primary pointer' />\n                    </div>\n                    <div className='col-md-1 text-right pointer' style={{paddingTop: \"25px\"}}  onClick={() => this.deleteFile(file?._id ||file.tmpID)}>\n                      <i className='fa fa-minus-circle text-red' />\n                    </div>\n                    <div className='row'>\n                      <div className='col-md-12'>\n                        {\n                          file.status === imageStatus.inProgress ?\n                            <div className='multi-upload-progress-bar'>\n                              <div className='multi-progress' style={{ width: `${file.progress}%` }} />\n                            </div> : null\n                        }\n                      </div>\n                    </div>\n                  </div>\n                </React.Fragment>\n              ))\n            }\n          </div>\n        </ShowIf>\n        <div\n          className='add-item pointer multi-upload-item'\n          onClick={this.clickUploadFile}\n          onDrop={this.handleDrop}\n          onDragOver={this.dragOverHandler}\n          onDragEnd={this.dragEndHandler}\n          onDragLeave={this.dragLeaveHandler}\n        >\n          <i className='fa fa-2x fa-cloud-upload' /><br />\n          AÑADIR ARCHIVOS\n        </div>\n        <input\n          type='file'\n          ref={this.inputFile}\n          style={{ display: 'none' }}\n          onChange={(e) => this.handleChangeInputFile(e)}\n          accept='.jpeg, .jpg, .png, .doc, .docx, .xls, .xlsx, .pdf'\n          multiple={true}\n        />\n      </div>\n    );\n  }\n\n  private processFile(file: File | any): Promise<any> {\n    const { onChange, files } = this.props;\n    return new Promise((resolve) => {\n      file.tmpID = uuid.v4();\n      file.progress = 0;\n      file.isImage = this.isImage(file.type);\n      file.status = imageStatus.pending;\n      onChange([...files, file]);\n      this.uploadImages();\n      resolve({});\n    });\n  }\n\n  private getSizeText(bytes: number): string {\n    let text = '';\n    if (bytes < 1000000) {\n      text = Math.floor(bytes / 1000) + 'KB';\n    } else {\n      text = Math.floor(bytes / 1000000) + 'MB';\n    }\n    return text;\n  }\n\n  private deleteFile(id: string) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el archivo adjunto.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        const { onChange, files, deleteCalback } = this.props;\n        onChange([...files].filter(file => file.tmpID !== id && file._id !== id));\n        if (deleteCalback) {\n          deleteCalback(id);\n        }\n      }\n    });\n  }\n\n  private uploadImages() {\n    const { onChange, files, url, body} = this.props;\n    const pendingImages: any[] = [];\n    const inProcessImages: any[] = [];\n    if (files.length) {\n      files.forEach((file) => {\n        if (file.status === imageStatus.pending) {\n          pendingImages.push(file);\n        } else if (file.status === imageStatus.inProgress) {\n          inProcessImages.push(file);\n        }\n      });\n    }\n    if (!inProcessImages.length && pendingImages.length) {\n      const imageToUpload = pendingImages[0];\n      let lastPercentage = 0;\n      onChange([...this.props.files].map((file) => {\n        if (file.tmpID === imageToUpload.tmpID) {\n          file.status = imageStatus.inProgress;\n        }\n        return file;\n      }));\n      const instance = axios.create({\n        timeout: 360000,\n        headers: {\n          'Content-Type': 'multipart/form-data'\n        },\n        onUploadProgress: (progressEvent) => {\n          const percentage = (100 / progressEvent.total) * progressEvent.loaded;\n          if (lastPercentage < percentage) {\n            lastPercentage = percentage + 5;\n            // TODO Fix this\n            onChange([...this.props.files].map((file) => {\n              if (file.tmpID === imageToUpload.tmpID) {\n                file.status = imageStatus.inProgress;\n                file.progress = percentage;\n              }\n              return file;\n            }));\n          }\n        }\n      });\n      let attempt = 1;\n      const timeout = 1000;\n      const data = new FormData();\n      data.append('file', imageToUpload);\n      if (body) {\n        Object.keys(body).forEach(key => {\n          data.append(key, body[key]);\n        });\n      }\n      instance\n        .post(url, data)\n        .then(response => {\n          onChange([...this.props.files].map((file) => {\n            if (file.tmpID === imageToUpload.tmpID) {\n              file._id = response.data.data._id;\n              file.progress = 100;\n              file.url = decodeURIComponent(response.data.data.file.url);\n              file.status = imageStatus.complete;\n            }\n            return file;\n          }));\n          // dispatch(updateImage(imageToUpload.tempID, 100, statusImages.completed, response.data.id, 1));\n          // dispatch(uploadImages());\n          this.uploadImages();\n        })\n        .catch(err => {\n          Raven.captureMessage(JSON.stringify(err.response), {\n            level: 'info'\n          });\n          if (!axios.isCancel(err)) {\n            Raven.captureException(JSON.stringify(err.response));\n            const waitTime = Math.pow(2, attempt) * timeout;\n            if (waitTime < 16000) attempt = attempt + 1;\n            else attempt = 1;\n            // dispatch(updateImage(imageToUpload.tempID, 0, statusImages.pending, null, attempt));\n            onChange([...this.props.files].map((file) => {\n              if (file.tmpID === imageToUpload.tmpID) {\n                file.status = imageStatus.pending;\n              }\n              return file;\n            }));\n            setTimeout(() => {\n              this.uploadImages();\n            }, waitTime);\n          }\n        });\n    }\n  }\n\n  private isImage(type: string): boolean {\n    const accepted = ['image/jpg', 'image/jpeg', 'image/png'];\n    return accepted.includes(type);\n  }\n\n  private async handleChangeInputFile(e: ChangeEvent<HTMLInputElement>) {\n    const { files } = e.target;\n    if (files && files.length) {\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < files.length; i++) {\n        // const file: File | null = dt.items[i].getAsFile();\n        const file: any = files[i];\n        if (file) {\n          const reader = new FileReader();\n          reader.onload = async (e) => {\n            file.url = e.target!.result;\n            await this.processFile(file);\n          };\n          reader.readAsDataURL(file);\n        }\n      }\n    }\n    // clear input file\n    this.inputFile.current!.value = '';\n  }\n\n  private handleDrop(e: DragEvent<HTMLDivElement>) {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        // Use  interface to access the file(s)\n        // tslint:disable-next-line: prefer-for-of\n        for (let i = 0; i < dt.items.length; i++) {\n          // const file: File | null = dt.items[i].getAsFile();\n          const file: any = dt.items[i].getAsFile();\n          if (file) {\n            const reader = new FileReader();\n            reader.onload = async (e) => {\n              file.url = e.target!.result;\n              await this.processFile(file);\n            };\n            reader.readAsDataURL(file);\n          }\n        }\n      }\n    } else {\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < dt.files.length; i++) {\n        const file: any = dt.files[i];\n        if (file) {\n          const reader = new FileReader();\n          reader.onload = async (e) => {\n            file.url = e.target!.result;\n            await this.processFile(file);\n          };\n          reader.readAsDataURL(file);\n        }\n      }\n    }\n    // clear input file\n    this.inputFile.current!.value = '';\n  }\n\n  private dragOverHandler(e: DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n}\n\nexport default MultiUploadFiles;\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\n\ninterface IPropsType {\n  page: number;\n  pages: number;\n  changePage: (page: number) => void;\n}\n\nconst Paginator: React.FunctionComponent<IPropsType> = (props) => {\n  const {page, pages, changePage} = props;\n  return (\n    <ul className=\"pagination pagination-sm\">\n      {\n        new Array(pages).fill(1).map((item, index) => {\n          const key = index + 1;\n          const onClick = key !== page ? () => changePage(key) : undefined;\n          if ((key > page - 3 && key < page + 3) || (key === 1 || key === pages)) {\n            return (\n              <li className={`page-item ${key === page ? 'active' : ''}`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\" onClick={onClick}>{key}</a>\n              </li>\n            );\n          }\n          if (key >= page + 3 && key === pages - 1) {\n            return (\n              <li className={`page-item disabled`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\">...</a>\n              </li>\n            );\n          } else if (key <= page - 3 && key === 2) {\n            return (\n              <li className={`page-item disabled`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\">...</a>\n              </li>\n            );\n          } else {\n            return null;\n          }\n        })\n      }\n    </ul>\n  );\n};\n\nPaginator.propTypes = {\n  page: PropTypes.number.isRequired,\n  pages: PropTypes.number.isRequired,\n  changePage: PropTypes.func.isRequired\n};\n\nexport default Paginator;\n","import * as React from 'react';\n\ninterface IPropsType {\n  className?: string;\n  children?: React.ReactNode;\n  style?: React.CSSProperties;\n}\n\nconst Row: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  return (\n    <div\n      className={`row${props.className && props.className.length ? ` ${props.className}` : ''}`}\n      style={props.style ? props.style : {}}\n    >\n      {props.children}\n    </div>\n  );\n};\n\nexport default Row;\n","import * as React from 'react';\n\ninterface IPropsType {\n  condition: boolean;\n  children?: React.ReactNode;\n  alternative?: React.ReactNode;\n}\n\nconst ShowIf: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  if (props.condition) {\n    return (\n      <>{props.children}</>\n    );\n  }\n  if (props.alternative) {\n    return (\n      <>{props.alternative}</>\n    );\n  }\n  return null;\n};\n\nexport default ShowIf;\n","import * as React from 'react';\nimport { IWindow } from '../../interfaces/window';\nimport MixpanelTracker from './MixpanelTracker';\n\ndeclare let window: IWindow;\n\nabstract class TrackingBasePage<PropsType, StateType> extends React.Component<PropsType, StateType>{\n  abstract title : string;\n\n  protected constructor(props: PropsType) {\n    super(props);\n    this.trackPage = this.trackPage.bind(this);\n    this.registerUser = this.registerUser.bind(this);\n    this.shouldTrack = this.shouldTrack.bind(this);\n    this.componentDidMount = this.componentDidMount.bind(this);\n    this.trackClick = this.trackClick.bind(this);\n  }\n\n  public componentDidMount() : void {\n    // set the title of the page\n    document.title = `OSA Andes | ${this.title}`;\n    this.registerUser();\n    this.trackPage();\n  }\n\n  trackPage() : void {\n    if (this.shouldTrack())\n      MixpanelTracker.getInstance().trackAction(this.title);\n  }\n\n  trackClick(title: string, properties: any = {}) : void {\n    if (this.shouldTrack())\n      MixpanelTracker.getInstance().trackAction(`${this.title} - ${title}`, properties);\n  }\n\n  public shouldTrack() : boolean {\n    return !window.user.email.includes('@osacontrol.com');\n  }\n\n  private registerUser() : void {\n    if (this.shouldTrack() && !window.isTracked) {\n      MixpanelTracker.getInstance().identifyUser(window.user);\n      window.isTracked = true;\n    }\n  }\n}\n\n export default TrackingBasePage;\n","import * as React from \"react\";\nimport { DetailedHTMLFactory, InputHTMLAttributes } from 'react';\ninterface IPropsType {\n  input: DetailedHTMLFactory<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement>;\n  checked: boolean;\n  label: string;\n  type: string;\n  help: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\nconst BootstrapSwitchField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  checked,\n  help,\n  meta: { touched, error, warning }\n}:IPropsType) => (\n  <div className=\"form-group-switch\">\n    <label className={`switch switch-blue`}>\n      <input type='checkbox' className='switch' {...input} checked={checked} />\n      <span className=\"slider round\" />\n    </label>\n    <label className=\"switch-label\">{label}</label>\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"error invalid-feedback\">{error}</span>) ||\n        (warning && <span className=\"warning warning-feedback\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default BootstrapSwitchField;\n\n\n\n","import * as React from 'react';\nimport {RefObject} from 'react';\nimport * as unorm from 'unorm';\nimport {WrappedFieldProps} from \"redux-form/lib/Field\";\n\ninterface IOption {\n  value: string;\n  text: any;\n  className?: string;\n}\n\ninterface IPropsType extends WrappedFieldProps {\n  options: IOption[];\n  labelOff?:boolean;\n  className?: string;\n  disabled?:boolean;\n  right?:boolean;\n  displayItems?: number;\n  onClick: (value: string) => void;\n  selectAll?: any;\n  noneSelectedText?: string;\n  selectedText?: string;\n  separator?: string;\n  allOption?: boolean;\n  autoClouse?: boolean;\n  search?: boolean;\n  sm?: boolean;\n  label: string;\n}\n\ninterface IStateType {\n  open: boolean;\n  searchText: string;\n}\n\nclass BootstrapSelectField extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    open: false,\n    searchText: ''\n  };\n\n  readonly input: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerOpen = this.handlerOpen.bind(this);\n    this.search = this.search.bind(this);\n    this.input = React.createRef();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      sm,\n      options,\n      onClick,\n      displayItems,\n      noneSelectedText,\n      selectedText,\n      separator,\n      allOption,\n      search,\n      autoClouse,\n      selectAll,\n      label,\n      disabled,\n      right,\n      input,\n      labelOff,\n      meta: {touched, error, warning}\n    } = this.props;\n    const {searchText} = this.state;\n    const selectedItems = options.filter((option) => (input.value.includes(option.value)));\n    // console.log('onClick', onClick)\n    return (\n      <div className={`form-group ${touched && error ? \"has-error\" : \"\"} ${touched && warning ? \"has-warning\" : \"\"}`}>\n        {!labelOff?<label className=\"control-label text-ellipsis\">{label}</label>: null}\n        <div\n          className={`dropdown bootstrap-select form-control show-tick ${autoClouse ? '' : 'keep-inside-clicks-open'} ${sm ? 'bootstrap-select-sm' : ''}`} >\n          <button\n            type=\"button\"\n            className={`btn dropdown-toggle bs-placeholder btn-filter btn-default`}\n            data-toggle=\"dropdown\"\n            disabled={disabled}\n            style={{borderRadius: '0px', borderColor: touched && error ? '#dd4b39' : '', padding: '6px 12px 5px 5px'}}\n            onClick={this.handlerOpen}\n          >\n            <div className=\"filter-option\">\n              <div className=\"filter-option-inner\">\n                <div className=\"filter-option-inner-inner text-ellipsis\">\n                  {\n                    selectedItems.length ?\n                      displayItems && selectedItems.length > displayItems ?\n                        <span style={{color: '#555'}}>{`${selectedItems.length} ${selectedText ? selectedText : 'items seleccionados.'}`}</span> :\n                        selectedItems\n                          .map((option, index) => (\n                            <React.Fragment key={index}>\n                            <span\n                              className={option.className ? option.className : ''}\n                              style={{color: '#555'}}\n                            >{option.text}</span> {selectedItems.length > index + 1 ? separator ? `${separator}` : ', ' : null}\n                            </React.Fragment>\n                          ))\n                      : noneSelectedText ?\n                      <span style={{color: touched && error ? \"#dd4b39\" : '#999'}}> {noneSelectedText}</span> : <span style={{color: '#999'}}> Todos </span>\n                  }\n                </div>\n              </div>\n            </div>\n            <span className=\"bs-caret\" style={{color: touched && error ? \"#dd4b39\" : undefined}}>\n            <span className=\"caret\"/>\n          </span>\n          </button>\n          <div className={`dropdown-menu ${right?'dropdown-menu-right':''}`} style={{borderRadius: '0px'}}>\n            {\n              search ?\n                <div className=\"bs-searchbox\">\n                  <input\n                    ref={this.input}\n                    type=\"text\"\n                    className=\"form-control input-sm\"\n                    autoComplete=\"off\"\n                    value={this.state.searchText}\n                    onChange={\n                      (e: React.ChangeEvent<HTMLInputElement>) => this.search(e.target.value)\n                    }\n                  />\n                </div> : null\n            }\n            {\n              allOption ?\n                <div className=\"bs-actionsbox\">\n                  <div className=\"btn-group btn-group-sm btn-block\">\n                    <button\n                      onClick={() => selectAll(true)}\n                      type=\"button\" className=\"actions-btn bs-select-all btn btn-default\">Seleccionar todo\n                    </button>\n                    <button\n                      onClick={() => selectAll(false)}\n                      type=\"button\" className=\"actions-btn bs-deselect-all btn btn-default\">Deseleccionar todo\n                    </button>\n                  </div>\n                </div> : null\n            }\n            <div\n              className=\"inner open\"\n              aria-expanded=\"false\"\n              tabIndex={-1}\n            >\n              <ul className=\"dropdown-menu inner\" style={{maxHeight: '20vh', overflowY: 'auto'}}>\n                {\n                  options.filter((option) => {\n                    if (!searchText || !searchText.length) {\n                      return true;\n                    }\n                    return unorm.nfd(option.text)\n                      .replace(/[\\u0300-\\u036f]/g, '')\n                      .toLowerCase()\n                      .includes(searchText.toLowerCase());\n                  }).map((option) => {\n                    const isSelected = input.value.includes(option.value);\n                    return (\n                      <li key={option.value} className={`${isSelected ? 'selected' : ''}`} onClick={() => onClick(option.value)}>\n                        <a role=\"option\" tabIndex={0} className={`${isSelected ? 'selected' : ''}`} style={{background: '#FFF'}}>\n                          <span className=\"glyphicon glyphicon-ok check-mark\"/>\n                          <span className={option.className ? option.className : ''}>{option.text}</span>\n                        </a>\n                      </li>\n                    );\n                  })\n                }\n              </ul>\n            </div>\n          </div>\n        </div>\n        {\n          touched &&\n          ((error && <span className=\"help-block text-ellipsis\">{error}</span>) ||\n            (warning && <span className=\"help-block text-ellipsis\">{warning}</span>)) || <span className=\"help-block\">&nbsp;</span>\n        }\n      </div>\n    );\n  }\n\n  private handlerOpen() {\n    // if (this.input.current) {\n    //   this.input.current.focus()\n    // }\n    this.setState({\n        open: !this.state.open\n      }, () => {\n        if (!this.state.open) {\n          this.search('');\n        }\n      }\n    );\n  }\n\n  private search(searchText: string) {\n    this.setState({\n      searchText: unorm.nfd(searchText).replace(/[\\u0300-\\u036f]/g, '')\n    });\n  }\n}\n\nexport default BootstrapSelectField;\n","import * as React from 'react';\nimport { DetailedHTMLFactory, InputHTMLAttributes } from 'react';\ninterface IPropsType {\n  input: DetailedHTMLFactory<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement>;\n  checked: boolean;\n  label: string;\n  type: string;\n  help: string;\n  style: any;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\nconst CheckBoxField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  checked,\n  style={},\n  type,\n  help,\n  meta: { touched, error, warning }\n}:IPropsType) => (\n  <div className=\"form-group\" style={style}>\n    <div className=\"form-check\">\n      <input type={type} className=\"form-check-input\" checked={checked} {...input}  />\n      <label className=\"form-check-label\" style={{marginLeft: '5px'}}> {label}</label>\n    </div>\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"error invalid-feedback\">{error}</span>) ||\n        (warning && <span className=\"warning warning-feedback\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default CheckBoxField;\n\n\n\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { CSSProperties, InputHTMLAttributes, RefObject } from 'react';\n\ninterface IPropsType {\n  onChange?: (e: moment.Moment | null) => void;\n  input: InputHTMLAttributes<any>\n  label: string;\n  labelOff?:boolean;\n  type: string\n  help: string\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  }\n  className?: string;\n  format?: string;\n  style?: CSSProperties;\n  value?: any;\n  startDate?: any\n  todayHighlight?: boolean\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DateRangePickerField extends React.Component<IPropsType, IStateType> {\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly inputGroup: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.input = React.createRef();\n    this.inputGroup = React.createRef();\n    this.clickCalendar = this.clickCalendar.bind(this);\n  }\n\n  public componentDidMount() {\n    const { format } = this.props;\n    $(this.input.current!).datepicker({\n      autoclose: true,\n      language: 'es',\n      todayHighlight: !!this.props.todayHighlight,\n      orientation: 'bottom auto',\n      clearBtn: true,\n      startDate: this.props.startDate,\n      format: {\n        toDisplay: (date) => {\n          return moment(date).utc().format(format ?? 'DD-MM-YY');\n        },\n        toValue: (date) => {\n          return moment(date, format ?? 'DD-MM-YY').utc().toDate();\n        }\n      }\n    });\n    $(this.input.current!).on('changeDate', () => {\n      if (typeof (this.props.onChange) === 'function') {\n        const date = moment(this.input.current!.value, format ?? 'DD-MM-YY', true);\n        if (date.isValid()) {\n          this.props.onChange(date);\n        } else {\n          this.props.onChange(null);\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount() {\n    $(this.input.current!).datepicker('destroy');\n  }\n\n  private clickCalendar() {\n    $(this.input.current!).datepicker('show');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      format, input,\n      label,\n      labelOff,\n      placeholder,\n      type,\n      help,\n      meta: { touched, error, warning }\n    } = this.props;\n    return (\n      <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n        {!labelOff ? <label className='control-label  text-ellipsis'>{label}</label> : null}\n        <div className='input-group'>\n          <input\n            ref={this.input}\n            type='text'\n            value={input.value?.toString().length ? moment(input.value as string).format(format ?? 'DD-MM-YY') : ''}\n            className={`form-control ${this.props.className ?? ''}`}\n            onClick={this.clickCalendar}\n            onChange={() => {\n            }}\n            style={{ ...this.props.style }}\n          />\n          <span className='input-group-addon pointer' onClick={this.clickCalendar}>\n          <i className='fa fa-calendar' />\n        </span>\n        </div>\n        {\n          touched &&\n          ((error && <span className='help-block'>{error}</span>) ||\n            (warning && <span className='help-block'>{warning}</span>)) || <span className='help-block'>&nbsp;</span>\n        }\n      </div>\n    );\n  }\n}\n\nexport default DateRangePickerField;\n","import * as React from 'react';\n\ninterface IPropsType {\n  input: any;\n  label: string;\n  labelOff?: boolean;\n  readOnly?: boolean;\n  onChange?: any;\n  type: string;\n  help: string;\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\n\nconst InputField: React.FunctionComponent<IPropsType> = ({\n   input,\n   label,\n   labelOff,\n   placeholder,\n   type,\n   onChange,\n   readOnly,\n   help,\n   meta: { touched, error, warning }\n  }: IPropsType) => (\n  <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n    {!labelOff ? <label className='control-label text-ellipsis'>{label}</label> : null}\n    <input\n      {...input}\n      readOnly={readOnly}\n      onChange={onChange ? onChange : input.onChange}\n      className={`form-control input-sm`}\n      placeholder={placeholder}\n      type={type}\n    />\n    {\n      help ?\n        <small id='passwordHelpBlock' className='form-text text-muted'>\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className='help-block text-ellipsis'>{error}</span>) ||\n        (warning && <span className='help-block text-ellipsis'>{warning}</span>)) || <span className='help-block'>&nbsp;</span>\n    }\n  </div>\n);\n\nexport default InputField;\n","import * as React from 'react';\nimport { DetailedHTMLFactory, InputHTMLAttributes } from 'react';\n\ninterface IPropsType {\n  input: DetailedHTMLFactory<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement>;\n  type: string;\n}\n\nconst InputHiddenField: React.FunctionComponent<IPropsType> = ({ input, type }: IPropsType) => (\n    <input\n      {...input}\n      type={type}\n    />\n);\n\nexport default InputHiddenField;\n","import * as React from 'react';\nimport { SelectHTMLAttributes } from 'react';\n\ninterface IPropsType {\n  input: SelectHTMLAttributes<any>;\n  label: string;\n  children: React.ReactNode;\n  disabled?: boolean;\n  labelOff?: boolean;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\n\nconst SelectField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  children,\n  disabled,\n  labelOff,\n  meta: { touched, error, warning }\n}: IPropsType) => {\n  return (\n    <div className={`form-group ${touched && error ? 'has-error' : ''} ${touched && warning ? 'has-warning' : ''}`}>\n      {!labelOff ? <label className='control-label'>{label}</label> : null}\n      <select\n        {...input}\n        className={`form-control input-sm ${touched && error ? 'is-invalid' : warning ? 'is-warning' : ''}`}\n        disabled={disabled}\n        placeholder={label}\n      >\n        {children}\n      </select>\n      {\n        touched &&\n        ((error && <span className='help-block'>{error}</span>) ||\n          (warning && <span className='help-block'>{warning}</span>)) || <span className=\"help-block\">&nbsp;</span>\n      }\n    </div>\n  );\n};\n\nexport default SelectField;\n","import * as React from \"react\";\nimport { TextareaHTMLAttributes} from \"react\";\nimport {Property} from \"csstype\";\ninterface IPropsType {\n  input: TextareaHTMLAttributes<any>\n  label: string;\n  labelOff?:boolean;\n  resize: Property.Resize;\n  type: string\n  help: string\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  }\n}\nconst TextAreaField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  labelOff,\n  placeholder,\n  help,\n  resize,\n  meta: { touched, error, warning },\n  ...custom\n}: IPropsType) => (\n  <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n    {!labelOff?<label className=\"control-label\">{label}</label>: null}\n    <textarea\n      {...input}\n      {...custom}\n      style={{\n        resize: resize ? resize : 'inherit'\n      }}\n      className={`form-control`}\n      placeholder={placeholder}\n    />\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"help-block\">{error}</span>) ||\n        (warning && <span className=\"help-block\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default TextAreaField;\n","const inputStringRequired = (value: string) => (value && value.toString().trim().length ? undefined : 'Este campo es requerido');\nconst validEmailRequired = (value: string) => /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,4}$/i.test(value) ? undefined : 'Este email no es valido';\nconst maxNumber = (max: number) => (value: number) => max < value ? `Debe ser menor a ${max}` : undefined;\nexport {\n  inputStringRequired,\n  validEmailRequired,\n  maxNumber\n};\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IBaseVenue, IVenue} from '../../../../../../src/app/interfaces/venue.interface';\nimport {changeTempVenueAction, getVenueUsersAction, IVenuesState, VenueReduxAction} from '../../actions/venues.actions';\nimport {updateTooltip} from '../../utils/common';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport Checkbox from '../Utils/CheckBox';\nimport {IVenueDay} from '../../../../../../src/app/interfaces/venueDay.interface';\n\ninterface IPropsType {\n  venues?: IVenuesState;\n  update?: boolean;\n  changeTempVenueAction?: (venue: IBaseVenue, noDelay?: boolean) => VenueReduxAction;\n  getVenueUsersAction? : (page:number, venue: IVenue) => VenueReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass VenueFormView extends React.Component<IPropsType, IStateType> {\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeTypeAction = this.changeTypeAction.bind(this);\n    this.handleSelectVenues = this.handleSelectVenues.bind(this);\n    this.handleSelectResponsible = this.handleSelectResponsible.bind(this);\n  }\n\n  public componentDidMount(): void {\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n    updateTooltip();\n  }\n\n  public componentDidUpdate(prevProps:Readonly<IPropsType>, prevState:Readonly<IStateType>, snapshot?:any): void {\n    updateTooltip();\n    if (prevProps.venues?.tempVenue._id != this.props.venues?.tempVenue._id)\n        this.props.getVenueUsersAction?.(1, this.props.venues?.tempVenue as IVenue)\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.venues && this.props.changeTempVenueAction) {\n      const {changeTempVenueAction, update} = this.props;\n      const {tempVenue, companies, carriers, regions, users} = this.props.venues;\n      let {allVenues} = this.props.venues;\n      if (update) {\n        allVenues = allVenues.filter((venue) => venue._id !== tempVenue._id);\n      }\n      return (\n        <React.Fragment>\n          <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n            <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n            {tempVenue.sendToDays.length > 0 ? <li><a data-toggle=\"tab\" href=\"#diasSucursales\">Tiempos de despacho</a></li> : null}\n          </ul>\n          <div className=\"tab-content\">\n            <div id=\"general\" className=\"tab-pane fade in active\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.name}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          name: e.target.value\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Código</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.code}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          code: e.target.value\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Abreviación</label>\n                    <input\n                      type=\"text\"\n                      name=\"abbreviation\"\n                      step=\"any\"\n                      className=\"form-control\"\n                      maxLength={10}\n                      value={tempVenue.abbreviation || ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          abbreviation: e.target.value.toUpperCase()\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Latitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      step=\"any\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.lat}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          lat: parseFloat(e.target.value)\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Longitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.lng}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          lng: parseFloat(e.target.value)\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"id-company\">Empresa</label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      search={true}\n                      options={\n                        companies\n                          .map((company) => ({\n                            value: company._id,\n                            text: company.name\n                          }))\n                      }\n                      selected={tempVenue.company ? [tempVenue.company._id] : []}\n                      autoClouse={true}\n                      onClick={(value: string) => changeTempVenueAction({\n                        ...tempVenue,\n                        company: companies.find((company) => (company._id === value))\n                      }, true)}\n                    />\n                  </div>\n                  {\n                    update ?\n                      <div className=\"alert alert-warning alert-dismissible\">\n                        Si se modifica la empresa, los usuarios asignados a esta sucursal también se verán afectados.\n                      </div> : null\n                  }\n                </div>\n                {update? <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Encargados de local\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"Usuarios seleccionados.\"\n                      selected={tempVenue.responsible.map((user) => user._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectResponsible(true, value)}\n                      options={users.map((user: any) => ({\n                        value: user._id,\n                        text: `${user.firstName} ${user.lastName}`\n                      }))}\n                      onClick={(value: string) => this.handleSelectResponsible(false, value)}\n                    />\n                  </div>\n                </div> : null }\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"id-company\">Región</label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      options={\n                        regions\n                          .map((region) => ({\n                            value: region._id,\n                            text: region.name\n                          }))\n                      }\n                      selected={tempVenue.region ? [tempVenue.region._id] : []}\n                      autoClouse={true}\n                      onClick={(value: string) => changeTempVenueAction({\n                        ...tempVenue,\n                        region: regions.find((region) => (region._id === value))\n                      }, true)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Envia <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden enviar a estas sucursales.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.sendToDays.map((venueDay) => venueDay.venue._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectVenuesSendToDays( true, value)}\n                      options={allVenues.map((venue: any) => ({\n                        value: venue._id,\n                        text: venue.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectVenuesSendToDays(false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Transportistas de envio <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden enviar de estos transportista.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.shippingCarriers.map((carrier) => carrier._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectCarriers('shippingCarriers', true, value)}\n                      options={carriers.map((carrier: any) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectCarriers('shippingCarriers', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Recibe <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\"\n                      data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden recepcionar de estas sucursales.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.receiveFrom.map((venue) => venue._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectVenues('receiveFrom', true, value)}\n                      options={allVenues.map((venue: any) => ({\n                        value: venue._id,\n                        text: venue.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectVenues('receiveFrom', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Transportistas de recepción <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden receocionar de estos transportista.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.receptionCarriers.map((carrier) => carrier._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectCarriers('receptionCarriers', true, value)}\n                      options={carriers.map((carrier: any) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectCarriers('receptionCarriers', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col col-md-12\">\n                  <div className=\"checkbox\">\n                    <label style={{paddingLeft: '0'}} onClick={this.changeTypeAction}>\n                      <Checkbox active={tempVenue.type === 'distributor'} action={this.changeTypeAction}\n                                classes=\"icheck-in-checkbox\"/>\n                      <span\n                        style={{\n                          paddingLeft: '5px',\n                          top: '2px',\n                          position: 'relative'\n                        }}\n                      >\n                        Distribuidor <i\n                        className=\"fa fa-info-circle\"\n                        data-toggle=\"tooltip\"\n                        data-placement=\"top\"\n                        title=\"Activa funcionalidades a la sucursal.\"\n                      />\n                </span>\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </div>\n            { tempVenue.sendToDays.length > 0 ? <div id=\"diasSucursales\" className=\"tab-pane fade\">\n              { tempVenue.sendToDays.map( (venueDay: IVenueDay) => {\n                const venueIndex = tempVenue.sendToDays.findIndex(v => v.venue._id === venueDay.venue._id);\n                  return <div className=\"row\" key={venueDay.venue._id}>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label>{tempVenue.name} - {venueDay.venue.name}</label>\n                        <input\n                          type=\"number\"\n                          name={venueDay.venue._id}\n                          step=\"any\"\n                          className=\"form-control\"\n                          min={1}\n                          value={venueDay.shippingMaxDays || ''}\n                          onChange={\n                            (e: React.ChangeEvent<HTMLInputElement>) => {\n                              tempVenue.sendToDays[venueIndex].shippingMaxDays = parseInt(e.target.value);\n                              changeTempVenueAction(tempVenue, true);\n                            }\n                          }\n                        />\n                      </div>\n                    </div>\n                  </div>;\n                }\n              )}\n            </div> : null}\n          </div>\n        </React.Fragment>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  private handleSelectVenuesSendToDays(all: boolean, value: string | boolean){\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, allVenues} = this.props.venues;\n      let values : IVenueDay[]= [];\n      if (all) {\n        values = value ? allVenues.map((venue: IVenue) => {\n          return {_id: null, shippingMaxDays : undefined, venue};}) :\n          [];\n      } else {\n        const add = tempVenue.sendToDays.find((venueDay : IVenueDay) => venueDay.venue._id === value) === undefined;\n        const venueDay : IVenueDay = {\n          _id: null,\n          venue:allVenues.find((venue) => venue._id === value)!,\n          shippingMaxDays: undefined\n        };\n        if (add) {\n          values = [...tempVenue.sendToDays, venueDay];\n        } else {\n          values = tempVenue.sendToDays.filter((venueDay) => venueDay.venue._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        sendToDays: values\n      }, true);\n    }\n\n  }\n  private handleSelectResponsible(all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, users} = this.props.venues;\n      if (all) {\n        this.props.changeTempVenueAction({\n          ...tempVenue,\n          responsible: value ? users : []\n        }, true);\n      } else {\n        let new_user = users.find(u => u._id === value)\n        if (new_user)\n          this.props.changeTempVenueAction({\n            ...tempVenue,\n            responsible: tempVenue.responsible.concat([new_user])\n          }, true);\n      }\n    }\n  }\n\n  private handleSelectVenues(where: 'receiveFrom' | 'sendTo', all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, allVenues} = this.props.venues;\n      let values = [];\n      if (all) {\n        values = value ? allVenues : [];\n      } else {\n        const add = tempVenue[where].find((venue) => venue._id === value) === undefined;\n        const venue = allVenues.find((venue) => venue._id === value);\n        if (add) {\n          values = [...tempVenue[where], venue];\n        } else {\n          values = tempVenue[where].filter((venue) => venue._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        [where]: values\n      }, true);\n    }\n  }\n  private handleSelectCarriers(where: 'shippingCarriers' | 'receptionCarriers', all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, carriers} = this.props.venues;\n      let values = [];\n      if (all) {\n        values = value ? carriers : [];\n      } else {\n        const add = tempVenue[where].find((carrier) => carrier._id === value) === undefined;\n        const carrier = carriers.find((carrier) => carrier._id === value);\n        if (add) {\n          values = [...tempVenue[where], carrier];\n        } else {\n          values = tempVenue[where].filter((carrier) => carrier._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        [where]: values\n      }, true);\n    }\n  }\n\n  private changeTypeAction() {\n    if (this.props.venues && this.props.changeTempVenueAction) {\n      const {changeTempVenueAction} = this.props;\n      const {tempVenue} = this.props.venues;\n      changeTempVenueAction({\n        ...tempVenue,\n        type: tempVenue.type === 'receiver' ? 'distributor' : 'receiver'\n      }, true);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { venues: IVenuesState }) => {\n  return {\n    venues: state.venues\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempVenueAction: (venue: IBaseVenue, noDelay?: boolean) => dispatch(changeTempVenueAction(venue, noDelay)),\n    getVenueUsersAction: (page: number, venue: IVenue) => dispatch(getVenueUsersAction(page, venue))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(VenueFormView);\n","import { default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as mapboxgl from 'mapbox-gl';\nimport ApiService from '../../utils/axios';\nimport { IBaseVenue, IVenue } from '../../../../../../src/app/interfaces/venue.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  changeSearchAction,\n  changeTempVenueAction,\n  createVenueAction,\n  deleteVenueAction,\n  getVenuesAction,\n  IVenuesState,\n  updateVenueAction,\n  VenueReduxAction\n} from '../../actions/venues.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport VenueFormView from './VenueFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { debounce } from 'throttle-debounce';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\n// var mapboxgl = require('mapbox-gl/dist/mapbox-gl.js');\n\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<VenueReduxAction>;\n  venues: IVenuesState;\n\n  getVenuesAction(page: number): VenueReduxAction;\n  createVenueAction(): VenueReduxAction;\n  updateVenueAction(): VenueReduxAction;\n  deleteVenueAction(id?: string): VenueReduxAction;\n  changeTempVenueAction(venue: IBaseVenue): VenueReduxAction;\n  changeSearchAction(searchText: string): VenueReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass VenuesListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private socket: Socket;\n  private map: any;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de sucursales';\n    this.changePage = this.changePage.bind(this);\n    this.createVenue = this.createVenue.bind(this);\n    this.processCreateVenue = this.processCreateVenue.bind(this);\n    this.updateVenue = this.updateVenue.bind(this);\n    this.processUpdateVenue = this.processUpdateVenue.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.onChangeTab = this.onChangeTab.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.venues;\n    this.props.getVenuesAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `venue-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const {pagination} = this.props.venues;\n        this.props.getVenuesAction(pagination.page);\n      }\n    });\n  }\n\n  public exportExcel() {\n    this.setState({\n      exporing: true\n    });\n    this.trackClick(\"Exportar\");\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/settings/venues/export-access/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-acceso-sucursales.xlsx`;\n        // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n        //   // IE workaround for \"HTML7007: One or more blob URLs were\n        //   // revoked by closing the blob for which they were created.\n        //   // These URLs will no longer resolve as the data backing\n        //   // the URL has been freed.\"\n        //   window.navigator.msSaveBlob(blob, fileName);\n        // } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          this.setState({\n            exporing: false\n          });\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n        // }\n      })\n      .catch((err) => {\n        this.setState({\n          exporing: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n        }\n      });\n  }\n\n  private onChangeTab() {\n\n    const {allVenues: venues} = this.props.venues;\n\n    const geojson = {\n      type: 'FeatureCollection',\n      features: venues\n        .filter((venue)=>(venue.lng && venue.lat))\n        .map((venue: any) => {\n        return {\n          type: 'Feature',\n          geometry: {\n            type: 'Point',\n            coordinates: [venue.lng, venue.lat]\n          },\n          properties: {\n            title: 'Sucursal',\n            name: venue.name,\n            logo: venue.company.marker && venue.company.marker.hasOwnProperty('url') ? `url(\"${venue.company.marker.url}\")` : 'url(\"/static/images/files/pin_osa.svg\")'\n          }\n        }\n      })\n    };\n\n    const $map = this.map;\n    $('#map').css('width', $('#tab_2').width() as any);\n    const bounds = new mapboxgl.LngLatBounds();\n    geojson.features.forEach((marker) => {\n\n      // create a HTML element for each feature\n      const el: HTMLDivElement = document.createElement('div');\n      // here set class use in the marker\n      // el.className = 'marker';\n      el.style.backgroundImage = marker.properties.logo;\n      el.style.backgroundSize = 'cover';\n      el.style.width = '50px';\n      el.style.height = '50px';\n      el.style.borderRadius = '50p%';\n      el.style.cursor = 'pointer%';\n\n      // make a marker for each feature and add to the map\n      if(Math.abs(marker.geometry.coordinates[0]) > 0.1) // skip sucursales sin lat, lng\n      {\n        new mapboxgl.Marker(el)\n          .setLngLat((marker.geometry.coordinates as [number, number]))\n          .setPopup(new mapboxgl.Popup({offset: 25}).setHTML(`<p>${marker.properties.name}</p>`))\n          .addTo($map);\n\n        bounds.extend((marker.geometry.coordinates as [number, number]));\n      }\n    });\n    $map.resize();\n    $map.fitBounds(bounds);\n\n  }\n\n  public componentDidMount() {\n    // mapboxgl.accessToken = 'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw';\n    this.map = new mapboxgl.Map({\n      accessToken: 'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw',\n      container: 'map',\n      style: 'mapbox://styles/mapbox/streets-v11',\n      center: [-70.593536, -33.509243],\n      zoom: 10,\n      trackResize: true\n    });\n    this.map.addControl(new mapboxgl.NavigationControl(), 'bottom-right');\n\n    $('a[href=\\'#tab_2\\']').on('shown.bs.tab', () => {\n      this.onChangeTab();\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.venues.pagination !== prevProps.venues.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.venues.source) {\n      this.props.venues.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {exporing} = this.state;\n    const {loading, venues, pagination, searchText} = this.props.venues;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.4\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Sucursales <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                {\n                  hasPermission(window.user, 'addVenue') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createVenue}><i className=\"fa fa-plus\" />  Crear sucursal</button>\n                    : null\n                }\n                <button\n                  className=\"btn btn-sm btn-primary  hidden-xs\"\n                  onClick={this.exportExcel}\n                  disabled={exporing}\n                  style={{marginLeft: '5px'}}\n                >\n                  {\n                    exporing ?\n                      <React.Fragment>\n                        <i className=\"fa fa-spin fa-spinner\"/> Exportando\n                      </React.Fragment>\n                      : <React.Fragment>\n                        <i className=\"fa fa-fw fa-download\"/> Exportar\n                      </React.Fragment>\n                  }\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div className=\"nav-tabs-custom\">\n                <ul className=\"nav nav-tabs\">\n                  <li className=\"active\">\n                    <a href=\"#tab_1\" data-toggle=\"tab\" aria-expanded=\"true\">Listado</a>\n                  </li>\n                  <li>\n                    <a href=\"#tab_2\" data-toggle=\"tab\" aria-expanded=\"true\">Mapa</a>\n                  </li>\n                </ul>\n                <div className=\"tab-content\">\n                  <div className='tab-pane active' id='tab_1'>\n                    <div className='box-body table-responsive no-padding'>\n                      <div className='row'>\n                        <div className='col-md-offset-8 col-md-4'>\n                          <div className='input-group input-group-sm'\n                               style={{ padding: '10px' }}\n                          >\n                            <input\n                              type='text'\n                              value={searchText}\n                              className='form-control pull-right'\n                              onChange={this.onChangeSearch}\n                              placeholder='Buscar' />\n                            <div className='input-group-btn'>\n                              <button className='btn btn-default'><i className='fa fa-search' /></button>\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n                      <table className='table table-andes table-striped'>\n                        <thead>\n                        <tr>\n                          <th style={{width: '40%'}} className=\"middle\">Nombre</th>\n                          <th style={{width: '10%'}} className=\"middle\">Código</th>\n                          <th style={{width: '10%'}} className=\"middle-center hidden-xs\">Ubicación</th>\n                          <th style={{width: '10%'}} className=\"middle-center hidden-xs\">Distribuidor</th>\n                          <th style={{width: '10%'}} className=\"middle\">Asignaciones</th>\n                          <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                          {\n                            hasPermission(window.user, 'changeVenue') ?\n                              <th style={{width: '1%'}} className=\"width-10\"/> : null\n                          }\n                          {\n                            hasPermission(window.user, 'deleteVenue') ?\n                              <th style={{width: '1%'}} className=\"width-10\"/> : null\n                          }\n                        </tr>\n                        </thead>\n                        <tbody>\n                        {\n                          venues.map((venue: IVenue) => {\n                            const canDelete = venue.users && venue.users.length === 0 && venue.participants && venue.participants.length === 0;\n                            return (\n                              <tr\n                                key={venue._id}\n                                id={`venue-${venue._id}`}\n                                className={'background-transition'}\n                              >\n                                <td className=\"middle\">{venue.name}<br/>\n                                  {\n                                    venue.company ? <span className={'text-sm text-muted'}>{venue.company.name}</span> : null\n                                  }\n                                </td>\n                                <td className=\"middle-center\">{venue.code}</td>\n                                <td className=\"middle-center\">{venue.lat}, {venue.lng}</td>\n                                <td className=\"middle-center  hidden-xs\">\n                                  {\n                                    venue.type === 'distributor' ?\n                                      <i className=\"fa fa-check-circle text-green\"/>\n                                      : <i className=\"fa fa-times-circle text-blue\"/>\n                                  }\n                                </td>\n                                <td className=\"text-sm\">\n                                  Usuarios: {venue.users ? venue.users.length : 0}<br/>\n                                  Revisiones: {venue.participants ? venue.participants.length : 0}<br/>\n                                </td>\n                                <td className=\"middle hidden-xs\">\n                                  {\n                                    moment(venue.updatedAt).format('LLL')\n                                  }\n                                </td>\n                                {\n                                  hasPermission(window.user, 'changeVenue') ?\n                                    <td\n                                      className=\"middle text-blue pointer\"\n                                      onClick={() => this.updateVenue(venue)}>\n                                      <i className=\"fa fa-pencil\"/>\n                                    </td> : null\n                                }\n                                {\n                                  hasPermission(window.user, 'deleteVenue') ?\n                                    <td\n                                      className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                      onClick={canDelete ? () => this.deleteVenue(venue) : undefined}\n                                    >\n                                      <i className=\"fa fa-minus-circle\"/>\n                                    </td> : null\n                                }\n                              </tr>\n                            );\n                          })\n                        }\n                        </tbody>\n                      </table>\n                    </div>\n                  </div>\n                  <div className=\"tab-pane\" id=\"tab_2\">\n                    <div\n                      id=\"map\"\n                      style={{\n                        position: 'relative',\n                        width: '100%',\n                        height: '80vh'\n                      }}\n                    />\n                  </div>\n                </div>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.props.changeSearchAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    this.props.getVenuesAction(1);\n  }\n\n  private createVenue(): void {\n    this.props.changeTempVenueAction({\n      _id: '',\n      lat: 0,\n      lng: 0,\n      name: '',\n      code: '',\n      abbreviation: '',\n      type: 'receiver',\n      sendTo: [],\n      sendToDays: [],\n      receiveFrom: [],\n      shippingCarriers: [],\n      responsible: [],\n      shippingMaxDays: 5,\n      receptionCarriers: []\n    });\n    this.props.loadDataAction(\n      'Agregar Sucursal',\n      <VenueFormView/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateVenue}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateVenue(): void {\n    const {tempVenue} = this.props.venues;\n    if (!tempVenue.name || !tempVenue.name.trim()) {\n      swal!('Agregar sucursal', 'El nombres es requerido', 'error');\n    } else if (!tempVenue.company || !tempVenue.company._id) {\n      swal!('Agregar sucursal', 'La empresa es requerida', 'error');\n    } else {\n      this.props.createVenueAction();\n    }\n  }\n\n  private updateVenue(venue: IVenue): void {\n    this.props.changeTempVenueAction({\n      _id: venue._id,\n      name: venue.name,\n      code: venue.code ?? '',\n      abbreviation: venue.abbreviation ?? '',\n      lat: venue.lat,\n      lng: venue.lng,\n      company: venue.company,\n      region: venue.region,\n      type: venue.type ? venue.type : 'receiver',\n      sendTo: venue.sendTo ? venue.sendTo : [],\n      sendToDays: venue.sendToDays ? venue.sendToDays : [],\n      shippingMaxDays : venue.shippingMaxDays,\n      receiveFrom: venue.receiveFrom ? venue.receiveFrom : [],\n      responsible: venue.responsible ? venue.responsible : [],\n      shippingCarriers: venue.shippingCarriers ? venue.shippingCarriers : [],\n      receptionCarriers: venue.receptionCarriers ? venue.receptionCarriers : []\n    });\n    this.props.loadDataAction(\n      'Editar Sucursal',\n      <VenueFormView update={true} />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateVenue}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateVenue(): void {\n    const {tempVenue} = this.props.venues;\n    if (!tempVenue.name || !tempVenue.name.trim()) {\n      swal!('Editar sucursal', 'El nombres es requerido', 'error');\n    } else if (!tempVenue.company || !tempVenue.company._id) {\n      swal!('Editar sucursal', 'La empresa es requerida', 'error');\n    } else {\n      this.props.updateVenueAction();\n    }\n  }\n\n  private deleteVenue(venue: IVenue): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal ${venue.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteVenueAction(venue._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getVenuesAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { venues: IVenuesState }) => {\n  return {\n    venues: state.venues\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getVenuesAction: (page: number) => dispatch(getVenuesAction(page)),\n    createVenueAction: () => dispatch(createVenueAction()),\n    updateVenueAction: () => dispatch(updateVenueAction()),\n    deleteVenueAction: (id: string) => dispatch(deleteVenueAction(id)),\n    changeSearchAction: (searchText: string) => dispatch(changeSearchAction(searchText)),\n    changeTempVenueAction: (venue: IBaseVenue) => dispatch(changeTempVenueAction(venue)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{venues: IVenuesState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(VenuesListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\n\ninterface IPropsType {\n  changeTempVersion: (tempVersion: ITempVersion) => void;\n}\n\ninterface ITempVersion {\n  ios: string;\n  android: string;\n  description: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tempVersion: ITempVersion;\n  currentUser: string;\n}\n\nclass VersionFormView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    currentUser: '',\n    tempVersion: {\n      description: '',\n      ios: '',\n      android: ''\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChangeDescription = this.onChangeDescription.bind(this);\n    this.onChangeiOS = this.onChangeiOS.bind(this);\n    this.onChangeAndroid = this.onChangeAndroid.bind(this);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    this.props.changeTempVersion(this.state.tempVersion);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    return (\n      <div className={'row'}>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Descripción</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeDescription}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>iOS</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeiOS}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Android</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeAndroid}\n            />\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeDescription(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        description: e.target.value.trim()\n      }\n    });\n  }\n\n  private onChangeiOS(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        ios: e.target.value.trim()\n      }\n    });\n  }\n\n  private onChangeAndroid(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        android: e.target.value.trim()\n      }\n    });\n  }\n\n}\n\nexport default VersionFormView;\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {createVersionAction, IVersionsState, getVersionsAction} from '../../actions/versions.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {statusFooterButttonsModal} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport VersionFormView from './VersionFormView';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  versions: IVersionsState;\n  dispatch: Dispatch<ModalReduxAction>;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  getVersionsAction(): ModalReduxAction;\n\n  createVersionAction(version: ITempVersion): ModalReduxAction;\n}\n\ninterface ITempVersion {\n  ios: string;\n  android: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  dragging: string;\n  draggingLocation: number;\n  completed: string[];\n  users: string[];\n  tempVersion: ITempVersion;\n}\n\nclass VersionListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   alerts: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  state = {\n    error: null,\n    dragging: '',\n    draggingLocation: -1,\n    completed: [],\n    users: ['One', 'Two', 'Three', 'Four', 'Five'],\n    tempVersion: {\n      ios: '',\n      android: ''\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de versiones';\n    this.changeTempVersion = this.changeTempVersion.bind(this);\n    this.onDragStart = this.onDragStart.bind(this);\n    this.onDragEnd = this.onDragEnd.bind(this);\n    this.onDragOver = this.onDragOver.bind(this);\n    this.onDrop = this.onDrop.bind(this);\n    this.onDropChangeIndex = this.onDropChangeIndex.bind(this);\n    this.onDragOverChange = this.onDragOverChange.bind(this);\n    this.onDragEndChange = this.onDragEndChange.bind(this);\n\n    this.addVersion = this.addVersion.bind(this);\n    this.processAddAlert = this.processAddAlert.bind(this);\n\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount() {\n    this.props.getVersionsAction();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.versions.source) {\n      this.props.versions.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n\n    const {versions, loading} = this.props.versions;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"200\" cSubMenu=\"200.100\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Versiones <small>{versions.length}</small></h3>\n              <div className=\"pull-right box-tools\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.addVersion}><i className='fa fa-plus' /> Crear versión</button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Descripción</th>\n                    <th className=\"middle text-center\">iOS Version</th>\n                    <th className=\"middle text-center\">Android Version</th>\n                    <th className=\"middle\">Creada por</th>\n                    <th className=\"middle\">Fecha creación</th>\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  versions.length ?\n                    versions.map((version: any) => {\n                      return (\n                        <tr\n                          key={version._id}\n                          id={`alert-${version._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{version.description}</td>\n                          <td className=\"middle text-center\">{version.ios}</td>\n                          <td className=\"middle text-center\">{version.android}</td>\n                          <td className=\"middle\">\n                            {\n                              version.createdBy ? version.createdBy.firstName + ' ' + version.createdBy.lastName : '-'\n                            }\n                          </td>\n                          <td className=\"middle\">{moment(version.createdAt).format('LLL')}</td>\n                        </tr>\n                      );\n                    }) : <tr>\n                      <td colSpan={5}>Aún no se han ingresado versiones</td>\n                    </tr>\n                }\n                </tbody>\n              </table>\n              <Row>\n                <div className=\"col-md-6\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th className=\"middle\">Nombre</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        this.state.users.map((user, index)=>{\n                          return (\n                            <tr\n                              draggable\n                              key={index}\n                              className={`pointer ${this.state.draggingLocation === index ? 'bg-aqua-active' : ''}`}\n                              style={{\n                                opacity: this.state.dragging === user || this.state.draggingLocation === index ? 0.5 : 1\n                              }}\n                              onDragStart = {(e) => this.onDragStart(e, user, index)}\n                              onDragEnter={this.onDragEnter}\n                              onDragEnd = {this.onDragEndChange}\n                              onDrop={(e) =>this.onDropChangeIndex(e, index)}\n                              onDragOver={(e)=>this.onDragOverChange(e, index)}\n                            >\n                              <td\n                              ><i className=\"fa fa-arrows-v text-muted font-md\" /> {\n                                this.state.draggingLocation === index ? this.state.dragging : user\n                              }</td>\n                            </tr>\n\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                <div className=\"col-md-6\" style={{height: '150px', overflowY: 'auto'}}>\n                  <div\n                    onDragOver={this.onDragOver}\n                    onDrop={(e) =>this.onDrop(e, 'completed')}\n                    onDragEnter={this.onDragEnter}\n                    style={{width: 200, minHeight: 100, border: '1px solid #CCC'}}\n                  >\n                    completed\n                    {this.state.completed.map((item, index)=><div key={index}>{item}</div>)}\n                  </div>\n                  <div\n                    onDragOver={this.onDragOver}\n                    onDragEnter={this.onDragEnter}\n                    onDrop={(e) =>this.onDrop(e, 'incompleted')}\n                    style={{width: 200,  minHeight: 100, border: '1px solid #CCC'}}\n                  >\n                    incompleted\n                  </div>\n                </div>\n              </Row>\n            </div>\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onDragStart(ev: React.DragEvent<HTMLTableRowElement>, id:string, index: number) {\n    console.log(`onDragStart: ${id}`);\n    ev.dataTransfer.setData('id', id);\n    ev.dataTransfer.setData('type', 'type');\n    ev.dataTransfer.setData('index', index.toString());\n\n    ev.dataTransfer.dropEffect = 'move';\n\n    const dragIcon = document.createElement('img');\n    dragIcon.src = 'https://www.automotrizcumbre.cl/wp-content/uploads/2018/08/chevrolet-sail-sedan-detalles-personaliza-648x240-4-300x180.jpg';\n    dragIcon.width = 100;\n    ev.dataTransfer.setDragImage(dragIcon, -10, -10);\n\n    this.setState({\n      dragging: id\n    });\n  }\n\n  private onDragEnd(ev: React.DragEvent<HTMLTableRowElement>) {\n    console.log(`onDragEnd`);\n    this.setState({\n      dragging: ''\n    });\n  }\n\n  private onDragEnter(ev: React.DragEvent<HTMLElement>) {\n    console.log(`onDragEnter`);\n    ev.preventDefault();\n    ev.stopPropagation();\n  }\n\n  private onDragOver(ev: React.DragEvent<HTMLElement>) {\n    console.log(`onDragOver`);\n    ev.preventDefault();\n    ev.stopPropagation();\n  }\n\n  private onDragOverChange(ev: React.DragEvent<HTMLElement>, index: number) {\n    console.log(`onDragOverChange`);\n    ev.dataTransfer.dropEffect = 'move';\n    ev.preventDefault();\n    ev.stopPropagation();\n    this.setState({\n      draggingLocation: index\n    });\n  }\n\n  private onDragEndChange(ev: React.DragEvent<HTMLElement>){\n    console.log(`onDragEndChange`);\n    this.setState({\n      draggingLocation: -1,\n      dragging: ''\n    });\n  }\n\n  private onDrop(ev: React.DragEvent<HTMLElement>, cat: string){\n    const id = ev.dataTransfer.getData('id');\n    const type = ev.dataTransfer.getData('type');\n    console.log(`onDrop: id: ${id} cat: ${cat}`);\n    console.log(id);\n    if (cat === 'completed') {\n      this.setState({\n        completed: [id, ...this.state.completed]\n      });\n    } else {\n      alert(`${id} se a soltado en ${cat}`);\n\n    }\n  }\n\n  private onDropChangeIndex(ev: React.DragEvent<HTMLElement>, newIndex: number) {\n    let {users} = this.state;\n    let index = parseInt(ev.dataTransfer.getData('index'));\n    console.log(`onDropChangeIndex newIndex:${newIndex} index:${index}`);\n    const data = users[index];\n    if (newIndex > index) {\n      for (let i = 0; i < users.length; i++) {\n        if (i >= index && i < newIndex) {\n          users[i] = users[i + 1];\n        }\n      }\n    } else {\n      for (let i = users.length - 1; i >= 0; i--) {\n        if (i > newIndex && i <= index) {\n          console.log(`2 ${users[i]} -> ${users[i - 1]}`);\n          users[i] = users[i - 1];\n        }\n      }\n    }\n    users[newIndex] = data;\n    this.setState({\n      users\n    });\n  }\n\n\n  private addVersion() {\n    this.props.loadDataAction(\n      'Agregar Alerta',\n        <VersionFormView changeTempVersion={this.changeTempVersion} />\n      ,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-primary\" onClick={this.processAddAlert}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private changeTempVersion(tempVersion: ITempVersion) {\n    this.setState({\n      tempVersion\n    });\n  }\n\n  private processAddAlert() {\n\n    const {tempVersion} = this.state;\n\n    if(tempVersion.ios.trim().length === 0)\n    {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    }\n    else if(tempVersion.android.trim().length === 0)\n    {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    }\n    else\n    {\n      statusFooterButttonsModal(true);\n      this.props.createVersionAction(tempVersion);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { versions: IVersionsState }) => {\n  return {\n    versions: state.versions\n  };\n};\n\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    getVersionsAction: () => dispatch(getVersionsAction()),\n    createVersionAction: (version: ITempVersion) => dispatch(createVersionAction(version))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(VersionListView);\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport BreadcrumbApp from './BreadcrumbApp';\nimport FooterApp from './FooterApp';\nimport HeaderApp from './HeadeApp';\nimport MenuApp from './MenuApp';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport moment = require('moment');\nimport ShowIf from '../components/Utils/ShowIf';\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  children: JSX.Element;\n  router: any;\n  title: any;\n  cMenu: string;\n  cSubMenu: string;\n  cAction?: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass AppContainer extends React.Component<IPropsType, IStateType> {\n\n  static propTypes = {\n    title: PropTypes.any.isRequired,\n    cMenu: PropTypes.string.isRequired,\n    cSubMenu: PropTypes.string.isRequired,\n    cAction: PropTypes.string\n  };\n\n  componentDidMount() {\n    const { location: { query } } = this.props.router;\n    if (query?.integration === 'webview') {\n      const $body = $('body');\n      $body\n        .removeClass('skin-purple')\n        .css({ 'background-color': '#ecf0f5' });\n      $body.append( `<div class=\"text-muted text-center\" style=\"position: absolute; height: 30px; width: 100%;\">Copyright (c) ${moment().format('YYYY')} <a href=\"http://www.osacontrol.com\" target=\"_blank\">OSA SPA</a>. All rights reserved.</div>` );\n\n    }\n  }\n\n  public render() {\n    const { title, cMenu, cSubMenu, cAction } = this.props;\n    const { location: { query } } = this.props.router;\n    if (query?.integration === 'webview') {\n      return (\n        <React.Fragment>\n          {this.props.children}\n        </React.Fragment>\n      );\n    }\n    return (\n      <React.Fragment>\n        <HeaderApp />\n        <MenuApp cMenu={cMenu} cSubMenu={cSubMenu} />\n        <div className='content-wrapper' style={{ minHeight: `${window.innerHeight - 51}px` }}>\n          <section className='content-header'>\n            <ShowIf condition={typeof title === 'string'} alternative={title}>\n              <h1>{title ? title: '\\u00A0'}</h1>\n            </ShowIf>\n            <BreadcrumbApp cMenu={cMenu} cSubMenu={cSubMenu} cAction={cAction} />\n          </section>\n          {this.props.children}\n        </div>\n        <FooterApp />\n      </React.Fragment>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { router: any }) => {\n  return {\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(AppContainer);\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {Link} from 'react-router-dom';\nimport menus from '../utils/menus';\n\ninterface IPropsType {\n  cMenu: string;\n  cSubMenu: string;\n  cAction?: string;\n}\n\nconst BreadcrumbApp: React.FunctionComponent<IPropsType> = (props) => {\n  const menu = menus.find((menu: any) => menu.id === props.cMenu);\n  if (menu) {\n    const subMenu = menu.items.find((item: any) => item.id === props.cSubMenu);\n    return (\n      <ol className=\"breadcrumb\">\n        <li><Link to={menu.url}><i className={`fa ${menu.icon}`}/>{menu.text}</Link></li>\n        {\n          props.cAction && props.cAction.length ?\n            subMenu ? <li><Link to={subMenu.url}>{subMenu.text}</Link></li> : null :\n            subMenu ? <li className=\"active\">{subMenu.text}</li> : null\n        }\n        {props.cAction && props.cAction.length && <li className=\"active\">{props.cAction}</li>}\n      </ol>\n    );\n  }\n  return null;\n};\n\n// BreadcrumbApp.propTypes = {\n//   cMenu: PropTypes.string.isRequired,\n//   cSubMenu: PropTypes.string.isRequired,\n//   cAction: PropTypes.string\n// };\n\nexport default BreadcrumbApp;\n","import * as React from 'react';\nimport * as moment from 'moment-timezone';\n\nconst FooterApp: React.StatelessComponent<{}> = () => {\n  return (\n    <footer className=\"main-footer\">\n      <div className=\"pull-right hidden-xs\"><b>Version</b> 2.1.3 stable</div>\n      <strong>Copyright (c) {moment().format('YYYY')} <a href=\"https://www.osa-app.cl\" target={'_blank'}>OSA SPA.</a></strong> All rights\n      reserved.\n    </footer>\n  );\n};\n\nFooterApp.propTypes = {\n};\n\nexport default FooterApp;\n","// import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {IWindow} from '../interfaces/window';\n\ndeclare let window: IWindow;\n\nclass HeaderApp extends React.Component<{}, {}> {\n  protected channel: BroadcastChannel;\n  protected existBC: boolean = window.hasOwnProperty('BroadcastChannel');\n\n  constructor(props: {}) {\n    super(props);\n    this.closeSesion = this.closeSesion.bind(this);\n  }\n\n  public componentDidMount() {\n    if (this.existBC) {\n      this.channel = new BroadcastChannel('andes');\n      this.channel.onmessage = (e) => {\n        if (e.data.close) {\n          location.href = '/account/logout/';\n        }\n      };\n    }\n  }\n\n  public componentWillUnmount() {\n    if (this.existBC) {\n      this.channel.close();\n    }\n  }\n\n  public render() {\n    return (\n      <header className=\"main-header\">\n        <a className=\"logo\" href=\"/\" style={{padding: '5px 15px'}}>\n          <span className=\"logo-mini\">&nbsp;</span>\n          <span className=\"logo-lg\"><img src=\"/static/images/OSA_andes_logo_horizontal.svg\" style={{maxHeight: '40px', verticalAlign: 'baseline'}}/></span>\n        </a>\n        <nav className=\"navbar navbar-static-top\">\n          <a className=\"sidebar-toggle hidden-sm hidden-md hidden-lg\" href=\"#\" data-toggle=\"push-menu\" role=\"button\">\n          {/*<a className=\"sidebar-toggle\" href=\"#\" data-toggle=\"push-menu\" role=\"button\">*/}\n            <span className=\"sr-only\">Toggle navigation</span>\n            <span className=\"icon-bar\"/>\n            <span className=\"icon-bar\"/>\n            <span className=\"icon-bar\"/>\n          </a>\n          <div className=\"navbar-custom-menu\">\n            <ul className=\"nav navbar-nav\">\n              {/*<li className=\"dropdown messages-menu\">*/}\n              {/*<a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">*/}\n              {/*<i className=\"fa fa-envelope-o\" />*/}\n              {/*<span className=\"label label-success\">4</span>*/}\n              {/*</a>*/}\n              {/*<ul className=\"dropdown-menu\">*/}\n              {/*<li className=\"header\">You have 4 messages</li>*/}\n              {/*<li>*/}\n              {/*<ul className=\"menu\">*/}\n              {/*<li><a href=\"#\">*/}\n              {/*<div className=\"pull-left\">*/}\n              {/*<img className=\"img-circle\" src=\"/static/theme/dist/img/user2-160x160.jpg\" alt=\"User Image\" />*/}\n              {/*</div>*/}\n              {/*<h4>Support Team*/}\n              {/*<small><i className=\"fa fa-clock-o\" /> 5 mins</small>*/}\n              {/*</h4>*/}\n              {/*<p>Why not buy a new awesome theme?</p></a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"footer\"><a href=\"#\">See All Messages</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"dropdown notifications-menu\">*/}\n              {/*<a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">*/}\n              {/*<i className=\"fa fa-bell-o\" />*/}\n              {/*<span className=\"label label-warning\">10</span>*/}\n              {/*</a>*/}\n              {/*<ul className=\"dropdown-menu\">*/}\n              {/*<li className=\"header\">You have 10 notifications</li>*/}\n              {/*<li>*/}\n              {/*<ul className=\"menu\">*/}\n              {/*<li><a href=\"#\"><i className=\"fa fa-users text-aqua\" /> 5 new members joined today</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"footer\"><a href=\"#\">View all</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              <li className=\"dropdown user user-menu\">\n                <a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">\n                  <img className=\"user-image\" src=\"/static/images/icon_circular.png\" alt=\"User Image\"/>\n                  <span\n                    className=\"hidden-xs\">{`${window.user.firstName || ''} ${window.user.lastName || ''}${!window.user.firstName && !window.user.lastName ? 'Unknown User' : ''}`}</span>\n                </a>\n                <ul className=\"dropdown-menu\">\n                  <li className=\"user-header\">\n                    <img className=\"img-circle\" src=\"/static/images/icon_circular.png\" alt=\"User Image\"/>\n                    <p>{`${window.user.firstName || ''} ${window.user.lastName || ''}${!window.user.firstName && !window.user.lastName ? 'Unknown User' : ''}`}\n                      <small>{window.user.email || ''}</small>\n                    </p>\n                  </li>\n                  {/*<li className=\"user-body\">*/}\n                  {/*<div className=\"row\">*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Followers</a></div>*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Sales</a></div>*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Friends</a></div>*/}\n                  {/*</div>*/}\n                  {/*</li>*/}\n                  <li className=\"user-footer\">\n                    {/*<div className=\"pull-left\"><a className=\"btn btn-default btn-flat\" href=\"#\">Profile</a></div>*/}\n                    <div className=\"pull-right\">\n                      <a\n                        className=\"btn btn-sm btn-default btn-flat\"\n                        href=\"/account/logout/\"\n                        onClick={this.closeSesion}\n                      >\n                        Cerrar sesión\n                      </a>\n                    </div>\n                  </li>\n                </ul>\n              </li>\n              {/*<li><a href=\"#\" data-toggle=\"control-sidebar\"><i className=\"fa fa-gears\"></i></a></li>*/}\n            </ul>\n          </div>\n        </nav>\n      </header>\n    );\n  }\n  private closeSesion() {\n    if (this.existBC) {\n      this.channel.postMessage({\n        close: true\n      });\n    }\n  }\n}\n\nexport default HeaderApp;\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {Link} from 'react-router-dom';\nimport menus from '../utils/menus';\n\ninterface IPropsType {\n  cMenu: string;\n  cSubMenu: string;\n}\n\nclass MenuApp extends React.Component<IPropsType, {}> {\n\n  static propTypes = {\n    cMenu: PropTypes.string.isRequired,\n    cSubMenu: PropTypes.string.isRequired\n  };\n\n  public componentDidMount(): void {\n    ($('.sidebar-menu') as any).tree();\n  }\n\n  public render() {\n    const {cMenu, cSubMenu} = this.props;\n\n    return (\n      <aside className=\"main-sidebar\">\n        <section className=\"sidebar\">\n          <ul className=\"sidebar-menu\" data-widget=\"tree\">\n            <li className=\"header\">MENÚ</li>\n            {\n              menus.map((menu: any) => {\n                return (\n                  <li className={`treeview ${menu.id === cMenu ? 'active menu-open' : ''}`} key={menu.id}>\n                    <a href=\"#\">\n                      <i className={`fa ${menu.icon}`}/> <span>{menu.text}</span>\n                      <span className=\"pull-right-container\">\n                      <i className=\"fa fa-angle-left pull-right\"/>\n                    </span>\n                    </a>\n                    <ul className=\"treeview-menu\">\n                      {\n                        menu.items.map((item: any) => {\n                          return (\n                            <li key={item.id} className={item.id === cSubMenu ? 'active' : ''}>\n                              <Link to={item.url}><i className={`fa ${item.icon}`}/> {item.text}</Link>\n                            </li>\n                          );\n                        })\n                      }\n                    </ul>\n                  </li>\n                );\n              })\n            }\n          </ul>\n        </section>\n      </aside>\n    );\n  }\n}\n\nexport default MenuApp;\n","import {AlertReduxAction, IAlertsState} from '../actions/alerts.actions';\n\nconst initialState: IAlertsState = {\n  alerts: [],\n  users: [],\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function alertsReducer(state = initialState, action: AlertReduxAction): IAlertsState {\n  switch (action.type) {\n    case '/ALERTS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/ALERTS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/ALERTS/DELETE':\n      return {\n        ...state,\n        alerts: state.alerts.filter((alert) => alert._id !== action.payload.id)\n      };\n    case '/ALERTS/CREATE':\n      return {\n        ...state,\n        alerts: [action.payload.alert, ...state.alerts]\n      };\n    case '/ALERTS/LOAD_DATA':\n      return {\n        ...state,\n        users: action.payload.users,\n        alerts: action.payload.alerts\n      };\n    default:\n      return state;\n  }\n}\n","import {BillingReduxAction, IBillingState} from \"../actions/billing.actions\";\n\nconst initialState: IBillingState = {\n  invoices: [],\n  source: null,\n  loading: true,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function billingReducer(state = initialState, action: BillingReduxAction): any {\n  switch (action.type) {\n    case '/BILLING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/BILLING/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/BILLING/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/BILLING/LOAD_BILLING':\n      return {\n        ...state,\n        invoices: action.payload.invoices,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {CarrierReduxAction, ICarriersState} from '../actions/carriers.actions';\n\nconst initialState: ICarriersState = {\n  carriers: [],\n  tempCarrier: {\n    name: ''\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function carriersReducer(state = initialState, action: CarrierReduxAction): ICarriersState {\n  switch (action.type) {\n    case '/CARRIERS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/CARRIERS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/CARRIERS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/CARRIERS/CHANGE_TEMP_CARRIER':\n      return {\n        ...state,\n        tempCarrier: action.payload.carrier\n      };\n    case '/CARRIERS/LOAD_CARRIERS':\n      return {\n        ...state,\n        carriers: action.payload.carriers,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import * as moment from 'moment';\nimport {ICar} from '../../../../../src/app/interfaces/car.interface';\nimport {CarReduxAction, ICarsState} from '../actions/cars.actions';\n\nconst initialState: ICarsState = {\n  cars: [],\n  car: null,\n  carEvents: {} ,\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function carsReducer(state = initialState, action: CarReduxAction): ICarsState {\n  switch (action.type) {\n    case '/CARS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/CARS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/CARS/LOAD_CARS':\n      return {\n        ...state,\n        cars: action.payload.cars,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/CARS/LOAD_CAR':\n      return {\n        ...state,\n        car: action.payload.car,\n        carEvents: groupCarEvents(action.payload.car)\n      };\n    case '/CARS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    default:\n      return state;\n  }\n}\n\nfunction groupCarEvents(car: ICar): any[] {\n  const events: any[] = [];\n  events.push({\n    _id: car._id,\n    createdAt: moment(car.createdAt).seconds(0),\n    typeEvent: 'created'\n  });\n  if (car.participants && car.participants.length) {\n    for (const participant of car.participants) {\n      events.push({\n        ...participant,\n        createdAt: moment(participant.createdAt),\n        typeEvent: 'revision'\n      });\n    }\n  }\n  if (car.inventories && car.inventories.length) {\n    for (const inventory of car.inventories) {\n      events.push({\n        ...inventory,\n        createdAt: moment(inventory.createdAt),\n        typeEvent: 'inventory'\n      });\n    }\n  }\n\n  return events\n    .sort((a, b) => {\n      return b.createdAt.unix() - a.createdAt.unix();\n    })\n    .reduce((acc: any, cur: any) => {\n    const key = moment(cur.createdAt).startOf('month').format('YYYY-MM-DD');\n    acc[key] = acc[key] || [];\n    acc[key].push(cur);\n    return acc;\n  }, {});\n}\n","import {\n  IColorState,\n  ColorReduxActions,\n  COLOR_CANCEL,\n  COLOR_CHANGE_ORDER,\n  COLOR_IS_LOADING,\n  COLOR_LOAD,\n  COLOR_UDPATE, COLOR_CREATE, COLOR_DELETE\n} from '../actions/color.types';\n\nconst initialState: IColorState = {\n  colors: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function colorsReducer(state = initialState, action: ColorReduxActions): IColorState {\n  switch (action.type) {\n    case COLOR_CANCEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case COLOR_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case COLOR_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case COLOR_CREATE:\n      return {\n        ...state,\n        colors: [...state.colors, action.payload.color]\n      };\n     case COLOR_DELETE:\n       return {\n         ...state,\n         colors: [...state.colors.filter((color) => color._id !== action.payload.color)]\n       };\n     case COLOR_UDPATE:\n      return {\n        ...state,\n        colors: [...state.colors.map((color) => {\n          if (color._id === action.payload.color._id) {\n            return {\n              color,\n              ...action.payload.color\n            };\n          }\n          return color;\n        })]\n      };\n\n    case COLOR_LOAD:\n      return {\n        ...state,\n        colors: action.payload.colors,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {ICompany} from '../../../../../src/app/interfaces/company.interface';\nimport {CompaniesReduxAction, ICompaniesState} from '../actions/companies.actions';\n\nconst initialState: ICompaniesState = {\n  companies: [],\n  tempCompany: {\n    name: '',\n    businessName: '',\n    rut: '',\n    imageURI: null,\n    image: null,\n    markerURI: null,\n    marker: null,\n    billing: {\n      active: false,\n      inventoryPrice: 0.0,\n      checklistPrice: 0.0,\n      requestPrice: 0.0\n    },\n    notifications:[]\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function companiesReducer(state = initialState, action: CompaniesReduxAction): ICompaniesState {\n  switch (action.type) {\n    case '/COMPANIES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/COMPANIES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/COMPANIES/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/COMPANIES/CHANGE_TEMP_COMPANY':\n      return {\n        ...state,\n        tempCompany: action.payload.company\n      };\n    case '/COMPANIES/CHANGE_COMPANY':\n      return {\n        ...state,\n        companies: state.companies.map((company: ICompany) => {\n          if (company._id === action.payload.company._id) {\n            company.name = action.payload.company.name;\n            company.businessName = action.payload.company.businessName;\n            company.rut = action.payload.company.rut;\n            company.billing = action.payload.company.billing;\n            company.notifications = action.payload.company.notifications;\n            company.image = action.payload.company.image;\n            company.marker = action.payload.company.marker;\n          }\n          return company;\n        })\n      };\n    case '/COMPANIES/DELETE_COMPANY':\n      return {\n        ...state,\n        companies: state.companies.filter((company: ICompany) => company._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/COMPANIES/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardReduxAction, IDashboardState} from '../actions/dashboard.actions';\n\nconst initialState: IDashboardState = {\n  loading: true,\n  source: null,\n  participants: [],\n  requests: [],\n  companies:[],\n  car: null,\n  carEvents: {} ,\n  forms: [],\n  searchForms: [],\n  participantsReceivedPerDate: [],\n  participantsSentPerDate: [],\n  participantPerRange: [],\n  carsPerDate: [],\n  planningPerDate: [],\n  planningProcessPerDate: [],\n  searchText: '',\n  searchFrom: '',\n  searchTo: '',\n  carsByVenue: [],\n  totalCars: 0,\n  loadingParticipant: null,\n  revisionStats: null,\n  venueStats: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function dashboardReducer(state = initialState, action: DashboardReduxAction): IDashboardState {\n  switch (action.type) {\n    case '/DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANTS':\n      return {\n        ...state,\n        participants: action.payload.participants,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/DASHBOARD/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/DASHBOARD/CHANGE_RANGE':\n      return {\n        ...state,\n        searchFrom: action.payload.from,\n        searchTo: action.payload.to,\n      };\n    case '/DASHBOARD/LOADING_PARTICIPANT':\n      return {\n        ...state,\n        loadingParticipant: action.payload.loadingParticipant\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANTS_PER_DATE':\n      return {\n        ...state,\n        companies: action.payload.companies,\n        participantsReceivedPerDate: action.payload.participantsReceivedPerDate,\n        participantsSentPerDate: action.payload.participantsSentPerDate,\n        carsPerDate: action.payload.carsPerDate,\n        planningPerDate: action.payload.planningPerDate,\n        planningProcessPerDate: action.payload.planningProcessPerDate,\n        totalCars: action.payload.totalCars,\n        carsByVenue: action.payload.carsByVenue,\n        participantPerRange: action.payload.participantPerRange\n      };\n    case '/DASHBOARD/LOAD_CAR':\n      return {\n        ...state,\n        car: action.payload.car,\n      };\n    case '/DASHBOARD/LOAD_REQUESTS_IN_CAR':\n      return {\n        ...state,\n        requests: action.payload.requests\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANT_IN_CAR':\n      if (state.car && state.car.participants) {\n        return {\n          ...state,\n          car: {\n            ...state.car,\n            participants: [action.payload.participant, ...state.car.participants]\n          }\n        };\n      } else {\n        return state;\n      }\n    case '/DASHBOARD/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/DASHBOARD/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/DASHBOARD/LOAD_VENUES_STATS':\n      return {\n        ...state,\n        venueStats: action.payload.venuesStats\n      };\n    case '/DASHBOARD/LOAD_REVISION_STATS':\n      return {\n        ...state,\n        revisionStats: action.payload.revisionStats\n      };\n    case '/DASHBOARD/LOAD_FORMS':\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case '/DASHBOARD/CHANGE_FORM_SEARCH':\n      return {\n        ...state,\n        searchForms: action.payload.searchForms\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardDamagesReduxAction, IDashboardDamagesState} from \"../actions/dashboardDamages.actions\";\n\nconst initialState: IDashboardDamagesState = {\n  data: {},\n  venues: [],\n  loading: true\n};\n\nexport function dashboardDamagesReducer(state = initialState, action: DashboardDamagesReduxAction): IDashboardDamagesState {\n  switch (action.type) {\n    case '/DASHBOARD/DAMAGES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/DAMAGES/LOAD_DATA':\n      return {\n        ...state,\n        data: action.payload.data\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardDercoReduxAction, IDashboardDercoState} from \"../actions/dashboardDerco.actions\";\n\nconst initialState: IDashboardDercoState = {\n  cleaning: {\n    loading: false,\n    days: [],\n    clean: [],\n    notClean: [],\n  }\n};\n\nexport function dashboardDercoReducer(state = initialState, action: DashboardDercoReduxAction): IDashboardDercoState {\n  switch (action.type) {\n    case '/DASHBOARD/CLEANING/IS_LOADING':\n      return {\n        ...state,\n        cleaning: {\n          ...state.cleaning,\n          loading: true\n        },\n      };\n    case '/DASHBOARD/CLEANING/LOAD_DATA_DAILY':\n      return {\n        ...state,\n        cleaning: {\n          ...action.payload.cleaning,\n          loading: false\n        },\n\n      };\n\n    default:\n      return state;\n  }\n}\n","import {DashboardTimingReduxAction, IDashboardTimingState} from '../actions/dashboardTiming.actions';\n\nconst initialState: IDashboardTimingState = {\n  data: {\n    months: [],\n    overdue: [],\n    ontime: []\n  },\n  perVenue: {},\n  venues: [],\n  venuesDict: {},\n  loading: true,\n  loadingPerVenue: false\n};\n\nexport function dashboardTimingReducer(state = initialState, action: DashboardTimingReduxAction): IDashboardTimingState {\n  switch (action.type) {\n    case '/DASHBOARD/TIMING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/TIMING/LOAD_DATA':\n      const venuesDict: any = {};\n      action.payload.venues.forEach((v: any) => venuesDict[v._id] = v );\n      return {\n        ...state,\n        loading: false,\n        venues: action.payload.venues,\n        venuesDict,\n        data: action.payload.data\n      };\n    case '/DASHBOARD/TIMING/IS_LOADING_PER_VENUE':\n      return {\n        ...state,\n        loadingPerVenue: true\n      };\n    default:\n      return state;\n  }\n}\n","import { IFormsState,\n  FormReduxActions,\n  FORM_CANCEL_STATUS,\n  FORM_CHANGE_ORDER,\n  FORM_IS_LOADING,\n  FORM_LOAD_STATUS,\n  FORM_LOAD_REQUEST_STATUS\n} from '../actions/form.types';\nimport { MILESTONE_LOAD_REQUEST_STATUS } from '../actions/milestone.types';\n\nconst initialState: IFormsState = {\n  forms: [],\n  requestStatus: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function formsReducer(state = initialState, action: FormReduxActions): IFormsState {\n  switch (action.type) {\n    case FORM_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case FORM_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case FORM_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case FORM_LOAD_REQUEST_STATUS:\n      return {\n        ...state,\n        requestStatus: action.payload.requestStatus\n      };\n    case FORM_LOAD_STATUS:\n      return {\n        ...state,\n        forms: action.payload.forms,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { connectRouter } from 'connected-react-router';\nimport { combineReducers } from 'redux';\nimport { reducer as formReducer } from 'redux-form';\nimport { alertsReducer } from './alerts.reducer';\nimport { billingReducer } from './billing.reducers';\nimport { carriersReducer } from './carriers.reducer';\nimport { carsReducer } from './cars.reducer';\nimport { companiesReducer } from './companies.reducer';\nimport { dashboardReducer } from './dashboard.reducer';\nimport { dashboardDamagesReducer } from './dashboardDamages.reducer';\nimport { dashboardDercoReducer } from './dashboardDerco.reducer';\nimport { dashboardTimingReducer } from './dashboardTiming.reducer';\nimport { inventoriesReducer } from './inventory.reducer';\nimport { inventoriesDashboardReducer } from './inventoryDashboard.reducer';\nimport { labelsReducer } from './labels.reducer';\nimport { modalReducer } from './modal.reducer';\nimport { planningReducer } from './planning.reducer';\nimport { reasonsReducers } from './reasons.reducer';\nimport { regionsReducer } from './regions.reducer';\nimport { requestItemsReducers } from './requestItems.reducer';\nimport { requestsReducers } from './requests.reducer';\nimport { stockReducer } from './stock.reducer';\nimport { usersReducer } from './users.reducer';\nimport { requestStatusReducer } from './requestStatus.reducer';\nimport { requestChannelReducer } from './requestChannel.reducer';\nimport { paymentMethodReducer } from './paymentMethod.reducer';\nimport { venuesReducer } from './venues.reducer';\nimport { versionsReducer } from './versions.reducer';\nimport transmittalReducer from \"./transmittal.reducer\";\nimport { operationTypeReducer } from './operationType.reducer';\nimport { milestoneReducer } from './milestone.reducer';\nimport { milestoneTypeReducer } from './milestoneType.reducer';\nimport { formsReducer } from './form.reducer';\nimport { colorsReducer } from './color.reducer';\nimport {statsDashboardReducer} from \"./statsDashboard.reducer\";\n\nexport default (history: any) => combineReducers({\n  users: usersReducer,\n  cars: carsReducer,\n  forms: formsReducer,\n  colors: colorsReducer,\n  transmittal: transmittalReducer,\n  modal: modalReducer,\n  carriers: carriersReducer,\n  dashboard: dashboardReducer,\n  dashboardDamages: dashboardDamagesReducer,\n  dashboardTiming: dashboardTimingReducer,\n  billing: billingReducer,\n  dashboardDerco: dashboardDercoReducer,\n  inventories: inventoriesReducer,\n  inventoryDashboard: inventoriesDashboardReducer,\n  alerts: alertsReducer,\n  reasons: reasonsReducers,\n  versions: versionsReducer,\n  requestStatus: requestStatusReducer,\n  paymentMethod: paymentMethodReducer,\n  requestChannel: requestChannelReducer,\n  venues: venuesReducer,\n  companies: companiesReducer,\n  labels: labelsReducer,\n  requests: requestsReducers,\n  requestItems: requestItemsReducers,\n  operationType: operationTypeReducer,\n  milestone: milestoneReducer,\n  milestoneType: milestoneTypeReducer,\n  regions: regionsReducer,\n  stock: stockReducer,\n  statsDashboard: statsDashboardReducer,\n  planning: planningReducer,\n  form: formReducer,\n  router: connectRouter(history)\n});\n","import * as unorm from 'unorm';\nimport {\n  IInventoryCar\n} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport {IInventoryState, InventoryReduxAction} from '../actions/inventory.actions';\n\nconst initialState: IInventoryState = {\n  inventories: [],\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  loading: true,\n  inventoryCar: null,\n  source: null,\n  loadingDetail: true,\n  fetchingDetail: false,\n  summary: {\n    _id: '',\n    name: '',\n    status: '',\n    createdAt: null,\n    finalizedAt: null\n  },\n  detail: {\n    venues: [],\n    cars: []\n  },\n  labels: [],\n  detailByVenue: [],\n  detailByBrand: [],\n  carsTable: [],\n  cardTypes: [],\n  cardProperties: [],\n  selectedItems: {},\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    states: []\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport interface IFilterCar {\n  text: string;\n  type: string;\n  property: string;\n  venues: string[];\n  states: string[];\n}\n\nexport function inventoriesReducer(state = initialState, action: InventoryReduxAction): IInventoryState {\n  switch (action.type) {\n    case '/INVENTORIES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/INVENTORIES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/INVENTORIES/LOAD_DATA':\n      return {\n        ...state,\n        inventories: action.payload.inventories,\n        inventorySettings: action.payload.inventorySettings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case '/INVENTORIES/UPDATE_INVENTORY_CAR':\n      return {\n        ...state,\n        inventoryCar: action.payload.inventoryCar\n      };\n    case '/INVENTORIES/CHANGE_FILTER':\n      return {\n        ...state,\n        carsTable: processCars(state.detail.cars, state.selectedItems, action.payload.filter),\n        filter: action.payload.filter\n      };\n    case '/INVENTORIES/CHANGE_SELECTED':\n      const newSelected = processSelected(state.selectedItems, action.payload.item);\n      return {\n        ...state,\n        selectedItems: newSelected,\n        carsTable: processCars(state.detail.cars, newSelected, state.filter)\n      };\n    case '/INVENTORIES/LOADING_INVENTORY_DETAIL':\n      return {\n        ...state,\n        loadingDetail: action.payload.loadingDetail\n      };\n    case '/INVENTORIES/FETCHING_INVENTORY_DETAIL':\n      return {\n        ...state,\n        fetchingDetail: action.payload.fetchingDetail\n      };\n    case '/INVENTORIES/LOAD_INVENTORY_DATA':\n      const selectedItems = action.payload.resetFilter ? initialState.selectedItems : state.selectedItems;\n      const filter = action.payload.resetFilter ? initialState.filter : state.filter;\n      return {\n        ...state,\n        ...processPropertyCars(action.payload.detail.cars),\n        carsTable: processCars(action.payload.detail.cars, selectedItems, filter),\n        selectedItems,\n        filter,\n        labels: action.payload.labels,\n        summary: action.payload.summary,\n        inventorySettings: action.payload.inventorySettings,\n        detailByVenue: action.payload.detailByVenue,\n        detail: action.payload.detail,\n        detailByBrand: action.payload.detailByBrand\n      };\n    case '/INVENTORIES/ADD_COMMENT':\n      if (state.inventoryCar) {\n        return {\n          ...state,\n          inventoryCar: {\n            ...state.inventoryCar,\n            comments: [...state.inventoryCar.comments, action.payload.inventoryComment]\n          }\n        };\n      } else {\n        return state;\n      }\n    default:\n      return state;\n  }\n}\n\nfunction processSelected(selectedItems: any, item: string) {\n  let newSelectedItems = {...selectedItems};\n  if (newSelectedItems.hasOwnProperty(item)) {\n    delete (newSelectedItems as any)[item];\n  } else {\n    newSelectedItems = {\n      ...newSelectedItems,\n      [item]: true\n    };\n  }\n  return newSelectedItems;\n}\n\ninterface IPropertyCar {\n  cardProperties: string[];\n  cardTypes: string[];\n}\n\nfunction processPropertyCars(cars: IInventoryCar[]): IPropertyCar {\n  const propertyCars: IPropertyCar = {\n    cardProperties: [],\n    cardTypes: []\n  };\n  for (const car of cars) {\n    if (car.car?.property && !propertyCars.cardProperties.includes(car.car.property)) {\n      propertyCars.cardProperties.push(car.car.property);\n    }\n    if (car.car?.type && !propertyCars.cardTypes.includes(car.car.type)) {\n      propertyCars.cardTypes.push(car.car.type);\n    }\n  }\n  return propertyCars;\n}\n\nfunction processCars(cars: IInventoryCar[], selectedItems: { [key: string]: any }, filter: IFilterCar) {\n  const products: any[] = [];\n  // const missincars = [];\n  for (const car of cars) {\n    let add = true;\n    if (filter && filter.venues && filter.venues.length && car.venue) {\n      add = (filter.venues as any).includes(car.venue._id);\n      if (!add && car.venueFound) {\n        add = (filter.venues as any).includes(car.venueFound._id);\n      }\n    }\n    if (add && filter && filter.states && filter.states.length && car.status) {\n      add = (filter.states as any).includes(car.status);\n    }\n    if (add && filter && filter.property && filter.property.length) {\n      add = car.car.property === filter.property;\n    }\n    if (add && filter && filter.type && filter.type.length) {\n      add = car.car.type === filter.type;\n    }\n    if (add && filter && filter.text && filter.text.length) {\n      const result: boolean[] = filter.text.toLowerCase().split(' ').map((text) => (\n        unorm.nfd(`${car.car.vin}${car.car.brand}${car.car.denomination}${car.car.patent}${car.car.internalNumber}`)\n          .replace(/[\\u0300-\\u036f]/g, '')\n          .toLowerCase()\n          .includes(text.toLowerCase())\n      ));\n      add = result.every((element: boolean) => element);\n      /*add = `${car.car.vin}${car.car.brand}${car.car.denomination}${car.car.patent}`.normalize('NFD')\n        .replace(/[\\u0300-\\u036f]/g, '')\n        .toLowerCase()\n        .includes(filter.text.toLowerCase());*/\n    }\n    const patent: string = car.car?.patent ? car.car.patent : '';\n    // if (add && filter && filter && filter.type.length) {\n    //   if (filter.type === 'new') {\n    //     add = patent.length === 0;\n    //   } else if (filter.type === 'used') {\n    //     add = patent.length !== 0;\n    //   }\n    // }\n    if (add && (car as any).car?._id) {\n      products.push({\n        _id: (car as any)._id,\n        carID: (car as any).car._id,\n        vin: car.car.vin,\n        brand: car.car.brand,\n        denomination: car.car.denomination,\n        internalNumber: car.car.internalNumber,\n        label: car.label,\n        labelName: car.label && car.label.hasOwnProperty('name') ? car.label.name : 'z',\n        labelBy: car.labelBy,\n        color: car.car.color,\n        labelText: car.labelText,\n        venue: car.venue ? car.venue.name : '-',\n        files: car.files && car.files.length ? car.files : [],\n        images: car.images && car.images.length ? car.images : [],\n        comments: car.comments && car.comments.length ? car.comments : [],\n        countComments: car.comments && car.comments.length ? car.comments.length : 0,\n        venueFound: car.venueFound ? car.venueFound.name : '-',\n        patent,\n        inventoriedBy: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n        selected: selectedItems.hasOwnProperty((car as any)._id),\n        status: car.status,\n        option: car.status\n      });\n    } else {\n      // if(car.status !==\"pending\"){\n        // console.log('car', car);\n        // missincars.push(car)\n      // }\n    }\n  }\n  // console.log('missincars', missincars);\n  return products;\n}\n","import {\n  IInventoryDashboardState,\n  InventoryDashboardReduxAction\n} from '../actions/inventoryDashboard.actions';\n\nconst initialState: IInventoryDashboardState = {\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    states: []\n  },\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  venues: [],\n  monthlyReport: [],\n  loading: true\n};\n\nexport function inventoriesDashboardReducer(state = initialState, action: InventoryDashboardReduxAction): IInventoryDashboardState {\n  switch (action.type) {\n    case '/INVENTORY_DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/INVENTORY_DASHBOARD/LOAD_DATA':\n      return {\n        ...state,\n        loading: false,\n        venues: action.payload.venues,\n        inventorySettings: action.payload.inventorySettings,\n        monthlyReport: action.payload.monthlyReport\n      };\n    case '/INVENTORY_DASHBOARD/LOAD_DATA_FILTERED':\n      return {\n        ...state,\n        inventorySettings: action.payload.inventorySettings,\n        filter: {\n          ...action.payload.filter,\n          venues: action.payload.filter.venues,\n        },\n        monthlyReport: action.payload.monthlyReport\n      };\n    default:\n      return state;\n  }\n}\n","import {ILabelsState, LabelsReduxAction} from '../actions/labels.actions';\n\nconst initialState: ILabelsState = {\n  labels: [],\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  loading: true,\n  tempLabel: {\n    _id: '',\n    description: '',\n    name: '',\n    color: '',\n    affected: [],\n    sendTo: '',\n    requireCustomText: false,\n    isExhibition: false,\n    active: true\n  },\n  source: null,\n  pagination: {\n     count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function labelsReducer(state = initialState, action: LabelsReduxAction): ILabelsState {\n  switch (action.type) {\n    case '/LABELS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/LABELS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/LABELS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/LABELS/CHANGE_TEMP_LABEL':\n      return {\n        ...state,\n        tempLabel: action.payload.tempLabel\n      };\n    case '/LABELS/CREATE_LABEL':\n      return {\n        ...state,\n        labels: [action.payload.label, ...state.labels],\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count + 1\n        }\n      };\n    case '/LABELS/CHANGE_LABEL':\n      return {\n        ...state,\n        labels: state.labels.map((label) => {\n          if (label._id === action.payload.label._id) {\n            return action.payload.label;\n          }\n          return label;\n        })\n      };\n    case '/LABELS/DELETE_LABEL':\n      return {\n        ...state,\n        labels: state.labels.filter((label: any) => label._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/LABELS/LOAD_LABELS':\n      return {\n        ...state,\n        labels: action.payload.labels,\n        inventorySettings: action.payload.inventorySettings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IMilestoneState,\n  MilestoneReduxActions,\n  MILESTONE_CANCEL_STATUS,\n  MILESTONE_CHANGE_ORDER,\n  MILESTONE_IS_LOADING,\n  MILESTONE_LOAD_STATUS,\n  MILESTONE_LOAD_FORMS,\n  MILESTONE_LOAD_REQUEST_STATUS,\n  MILESTONE_UDPATE_STATUS,\n  MILESTONE_LOAD_TYPES\n} from '../actions/milestone.types';\n\nconst initialState: IMilestoneState = {\n  milestones: [],\n  milestoneTypes: [],\n  requestStatus: [],\n  forms: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function milestoneReducer(state = initialState, action: MilestoneReduxActions): IMilestoneState {\n  switch (action.type) {\n    case MILESTONE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case MILESTONE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case MILESTONE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n     case MILESTONE_UDPATE_STATUS:\n      return {\n        ...state,\n        milestones: [...state.milestones.map((milestone) => {\n          if (milestone._id === action.payload.milestone._id) {\n            return {\n              milestone,\n              ...action.payload.milestone\n            };\n          }\n          return milestone;\n        })]\n      };\n    case MILESTONE_LOAD_FORMS:\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case MILESTONE_LOAD_TYPES:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes\n      };\n    case MILESTONE_LOAD_REQUEST_STATUS:\n      return {\n        ...state,\n        requestStatus: action.payload.requestStatus\n      };\n    case MILESTONE_LOAD_STATUS:\n      return {\n        ...state,\n        milestones: action.payload.milestones,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { IMilestoneTypeState,\n  MilestoneTypeReduxActions,\n  MILESTONE_TYPE_CANCEL_STATUS,\n  MILESTONE_TYPE_CHANGE_ORDER,\n  MILESTONE_TYPE_IS_LOADING,\n  MILESTONE_TYPE_LOAD_STATUS\n} from '../actions/milestoneType.types';\n\nconst initialState: IMilestoneTypeState = {\n  milestoneTypes: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function milestoneTypeReducer(state = initialState, action: MilestoneTypeReduxActions): IMilestoneTypeState {\n  switch (action.type) {\n    case MILESTONE_TYPE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case MILESTONE_TYPE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case MILESTONE_TYPE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case MILESTONE_TYPE_LOAD_STATUS:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IModalState, ModalReduxAction} from '../actions/modal.actions';\n\nconst initialState: IModalState = {\n  title: '',\n  body: null,\n  footer: null\n};\n\nexport function modalReducer(state = initialState, action: ModalReduxAction): IModalState {\n  switch (action.type) {\n    case '/MODAL/LOAD_DATA':\n      setTimeout(() => {\n        ($('#andesModal') as any).modal('show');\n      }, 100);\n      return {\n        ...state,\n        title: action.payload.title,\n        body: action.payload.body,\n        footer: action.payload.footer ? action.payload.footer : null\n      };\n    case '/MODAL/CLEAR':\n      return initialState;\n    default:\n      return state;\n  }\n}\n","import { IOperationTypeState,\n  OperationTypeReduxActions,\n  OPERATION_TYPE_CANCEL_STATUS,\n  OPERATION_TYPE_CHANGE_ORDER,\n  OPERATION_TYPE_IS_LOADING,\n  OPERATION_TYPE_LOAD_STATUS\n} from '../actions/operationType.types';\n\nconst initialState: IOperationTypeState = {\n  operationTypes: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function operationTypeReducer(state = initialState, action: OperationTypeReduxActions): IOperationTypeState {\n  switch (action.type) {\n    case OPERATION_TYPE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case OPERATION_TYPE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case OPERATION_TYPE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case OPERATION_TYPE_LOAD_STATUS:\n      return {\n        ...state,\n        operationTypes: action.payload.operationTypes,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IPaymentMethodState,\n  PAYMENT_METHOD_CANCEL,\n  PAYMENT_METHOD_CHANGE_ORDER,\n  PAYMENT_METHOD_IS_LOADING,\n  PAYMENT_METHOD_LOAD,\n  PaymentMethodReduxActions\n} from '../actions/paymentMethod.types';\n\nconst initialState: IPaymentMethodState = {\n  paymentMethods: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function paymentMethodReducer(state = initialState, action: PaymentMethodReduxActions): IPaymentMethodState {\n  switch (action.type) {\n    case PAYMENT_METHOD_CANCEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case PAYMENT_METHOD_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case PAYMENT_METHOD_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case PAYMENT_METHOD_LOAD:\n      return {\n        ...state,\n        paymentMethods: action.payload.paymentMethods,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IPlanningState, PlanningReduxAction} from \"../actions/planning.action\";\n\nconst initialState: IPlanningState = {\n  plannings: [],\n  loading: true,\n  source: null,\n  pagination: {\n     count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function planningReducer(state = initialState, action: PlanningReduxAction): IPlanningState {\n  switch (action.type) {\n    case '/PLANNING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/PLANNING/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/PLANNING/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/PLANNING/LOAD_PLANNING':\n      return {\n        ...state,\n        plannings: action.payload.plannings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IReasonsState,\n  ReasonsReduxActions,\n  REASON_CANCEL_REASON,\n  REASON_CHANGE_ORDER,\n  REASON_IS_LOADING,\n  REASON_LOAD_REASONS\n} from '../actions/reasons.types';\n\nconst initialState: IReasonsState = {\n  reasons: [],\n  reason: {},\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function reasonsReducers(state = initialState, action: ReasonsReduxActions): IReasonsState {\n  switch (action.type) {\n    case REASON_CANCEL_REASON:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REASON_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REASON_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REASON_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {RegionReduxAction, IRegionsState} from '../actions/regions.actions';\n\nconst initialState: IRegionsState = {\n  regions: [],\n  tempRegion: {\n    name: '',\n    code: ''\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function regionsReducer(state = initialState, action: RegionReduxAction): IRegionsState {\n  switch (action.type) {\n    case '/REGIONS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/REGIONS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/REGIONS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/REGIONS/CHANGE_TEMP_REGION':\n      return {\n        ...state,\n        tempRegion: action.payload.region\n      };\n    case '/REGIONS/LOAD_REGIONS':\n      return {\n        ...state,\n        regions: action.payload.regions,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { ISalesChannelState,\n  RequestChannelReduxActions,\n  REQUEST_CANCEL_CHANNEL,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CHANNEL\n} from '../actions/requestChannel.types';\n\nconst initialState: ISalesChannelState = {\n  channels: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestChannelReducer(state = initialState, action: RequestChannelReduxActions): ISalesChannelState {\n  switch (action.type) {\n    case REQUEST_CANCEL_CHANNEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_CHANNEL:\n      return {\n        ...state,\n        channels: action.payload.channels,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IRequestItemsState,\n  RequestItemsReduxActions,\n  REQUEST_ITEMS_CANCEL_REQUEST,\n  REQUEST_ITEMS_CHANGE_FILTER,\n  REQUEST_ITEMS_CHANGE_ORDER,\n  REQUEST_ITEMS_CREATE_ITEM,\n  REQUEST_ITEMS_DELETE_ITEM,\n  REQUEST_ITEMS_IS_LOADING,\n  REQUEST_ITEMS_LOAD_CARRIERS,\n  REQUEST_ITEMS_LOAD_ITEM_STATUS,\n  REQUEST_ITEMS_LOAD_PROPERTIES,\n  REQUEST_ITEMS_LOAD_REASONS,\n  REQUEST_ITEMS_LOAD_REQUESTS_ITEMS,\n  REQUEST_ITEMS_LOAD_VENUES,\n  REQUEST_ITEMS_UPDATE_ITEM, REQUEST_ITEMS_LOAD_SETTINGS, REQUEST_ITEMS_LOAD_USERS\n} from '../actions/requestItems.types';\nimport { requestSettings } from '../components/Request/defaults';\nimport * as moment from 'moment';\n\nconst initialState: IRequestItemsState = {\n  requestItems: [],\n  reasons: [],\n  carriers: [],\n  venues: [],\n  users: [],\n  properties: [],\n  requestItemStatus: [],\n  requestItemStatusMin: 0,\n  requestItemStatusMax: 100,\n  loading: true,\n  source: null,\n  requestSettings,\n  filters: {\n    request: '',\n    ticket: '',\n    conectaID: '',\n    entry: '',\n    text: '',\n    sellerText: '',\n    venues: [],\n    users: [],\n    properties: [],\n    status: [],\n    from: moment().subtract(6, 'months'),\n    to: null\n  },\n  options: {\n    orderBy: 'meta.request.number',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestItemsReducers(state = initialState, action: RequestItemsReduxActions): IRequestItemsState {\n  switch (action.type) {\n    case REQUEST_ITEMS_CANCEL_REQUEST:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_ITEMS_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_ITEMS_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons\n      };\n    case REQUEST_ITEMS_LOAD_CARRIERS:\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case REQUEST_ITEMS_LOAD_VENUES:\n      return {\n        ...state,\n        venues: action.payload.venues\n      };\n    case REQUEST_ITEMS_LOAD_USERS:\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    case REQUEST_ITEMS_LOAD_PROPERTIES:\n        return {\n          ...state,\n          properties: action.payload.properties\n        };\n    case REQUEST_ITEMS_LOAD_SETTINGS:\n      return {\n        ...state,\n        requestSettings: action.payload.requestSettings\n      };\n    case REQUEST_ITEMS_LOAD_ITEM_STATUS:\n      return {\n        ...state,\n        requestItemStatus: action.payload.requestItemStatus,\n        requestItemStatusMin: action.payload.min,\n        requestItemStatusMax: action.payload.max\n      };\n    case REQUEST_ITEMS_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_ITEMS_CHANGE_FILTER:\n      return {\n        ...state,\n        filters: {\n          ...state.filters,\n          [action.payload.key]: action.payload.value\n        }\n      };\n    case REQUEST_ITEMS_LOAD_REQUESTS_ITEMS:\n      return {\n        ...state,\n        requestItems: action.payload.requestItems,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case REQUEST_ITEMS_CREATE_ITEM:\n      return {\n        ...state,\n        requestItems: [action.payload.item, ...state.requestItems]\n      };\n    case REQUEST_ITEMS_UPDATE_ITEM:\n      return {\n        ...state,\n        requestItems: [...state.requestItems.map((item) => {\n          if (item._id === action.payload.item._id) {\n            return {\n              item,\n              ...action.payload.item\n            };\n          }\n          return item;\n        })]\n      };\n    case REQUEST_ITEMS_DELETE_ITEM:\n      return {\n        ...state,\n        requestItems: [...state.requestItems.filter((item) => {\n          return item._id !== action.payload.item._id;\n        })]\n      };\n    default:\n      return state;\n  }\n}\n","import { IRequestStatusState,\n  RequestStatusReduxActions,\n  REQUEST_CANCEL_STATUS,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_STATUS\n} from '../actions/requestStatus.types';\n\nconst initialState: IRequestStatusState = {\n  status: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestStatusReducer(state = initialState, action: RequestStatusReduxActions): IRequestStatusState {\n  switch (action.type) {\n    case REQUEST_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_STATUS:\n      return {\n        ...state,\n        status: action.payload.status,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import * as moment from 'moment-timezone';\nimport {\n  IRequestsState,\n  REQUEST_CANCEL_REQUEST,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_CREATE_REQUEST_ITEM_IN_LIST,\n  REQUEST_DELETE_REQUEST_IN_LIST,\n  REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_DELETE_REQUEST_ITEM_IN_LIST,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CARRIERS, REQUEST_LOAD_ITEMS,\n  REQUEST_LOAD_REASONS,\n  REQUEST_LOAD_REQUEST,\n  REQUEST_LOAD_REQUEST_ITEM_STATUS,\n  REQUEST_LOAD_REQUESTS,\n  REQUEST_LOAD_SETTINGS,\n  REQUEST_TAB_STATUS,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_LIST,\n  RequestsReduxActions\n} from '../actions/requests.types';\nimport { requestSettings } from '../components/Request/defaults';\n\nconst initialState: IRequestsState = {\n  requests: [],\n  requestItems: [],\n  reasons: [],\n  carriers: [],\n  requestOpen: [],\n  requestItemsById: {},\n  requestItemStatus: [],\n  requestItemStatusMin: 0,\n  requestItemStatusMax: 100,\n  request: {},\n  loading: true,\n  source: null,\n  requestSettings,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestsReducers(state = initialState, action: RequestsReduxActions): IRequestsState {\n  switch (action.type) {\n    case REQUEST_CANCEL_REQUEST:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons\n      };\n    case REQUEST_LOAD_CARRIERS:\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case REQUEST_LOAD_SETTINGS:\n      return {\n        ...state,\n        requestSettings: action.payload.requestSettings\n      };\n    case REQUEST_TAB_STATUS:\n      return {\n        ...state,\n        requestOpen: state.requestOpen.includes(action.payload.request)\n          ? [...state.requestOpen.filter(request => request !== action.payload.request)]\n          : [...state.requestOpen, action.payload.request]\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_REQUEST_ITEM_STATUS:\n      return {\n        ...state,\n        requestItemStatus: action.payload.requestItemStatus,\n        requestItemStatusMin: action.payload.min,\n        requestItemStatusMax: action.payload.max\n      };\n    case REQUEST_LOAD_REQUESTS:\n      return {\n        ...state,\n        requests: action.payload.requests,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case REQUEST_CREATE_REQUEST_ITEM_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].map((request) => {\n          if (request._id === action.payload.idRequest) {\n            request.updatedAt = moment().toDate();\n            request.items = [...request.items, action.payload.item];\n          }\n          return request;\n        })\n      };\n    case REQUEST_LOAD_ITEMS:\n      return {\n        ...state,\n        requestItemsById: {\n          ...state.requestItemsById,\n          [action.payload.request]: action.payload.items\n        }\n      };\n    case REQUEST_UDPATE_REQUEST_ITEM_IN_LIST:\n      let updateItem: any = {};\n      if(state.requestItemsById.hasOwnProperty(action.payload.request)){\n        updateItem[action.payload.request] = state.requestItemsById[action.payload.request].map((item:any)=>{\n          if(item._id === action.payload.item._id){\n            return action.payload.item\n          }\n          return item;\n        })\n      }\n      return {\n        ...state,\n        requestItemsById: {\n          ...state.requestItemsById,\n          ...updateItem\n        }\n      };\n    case REQUEST_DELETE_REQUEST_ITEM_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].map((request) => {\n          if (request._id === action.payload.idRequest) {\n            request.updatedAt = moment().toDate();\n            request.items = request.items.filter((item) => {\n              return item._id !== action.payload.item._id;\n            });\n          }\n          return request;\n        })\n      };\n    case REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request.items!, action.payload.item]\n        }\n      };\n    case REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request!.items!.map((item) => {\n            if (item._id === action.payload.item._id) {\n              return {\n                item,\n                ...action.payload.item\n              };\n            }\n            return item;\n          })]\n        }\n      };\n    case REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request.items!.filter((item) => {\n            return item._id !== action.payload.item._id;\n          })]\n        }\n      };\n    case REQUEST_DELETE_REQUEST_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].filter((request) => {\n          return request._id !== action.payload.id;\n        })\n      };\n    case REQUEST_LOAD_REQUEST:\n      return {\n        ...state,\n        request: action.payload.request\n      };\n    default:\n      return state;\n  }\n}\n","import {IStatsDashboardState, StatsDashboardReducerAction} from '../actions/statsDashboard.actions';\n\nconst initialState : IStatsDashboardState = {\n  loading: true,\n  studios: [],\n  users: [],\n  currentStudio: null,\n  tempStudio: {\n    _id: '',\n    users: [],\n    name: '',\n    type: '',\n    embedURL: '',\n    team: null\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\n\nexport function statsDashboardReducer(state: IStatsDashboardState = initialState, action: StatsDashboardReducerAction) {\n  switch (action.type) {\n    case '/STATS_DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/STATS_DASHBOARD/LOAD_STUDIOS':\n      return {\n        ...state,\n        studios: action.payload.studios\n      };\n    case '/STATS_DASHBOARD/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/STATS_DASHBOARD/CHANGE_TEMP_STUDIO':\n      return {\n        ...state,\n        tempStudio: action.payload.tempStudio\n      };\n    case '/STATS_DASHBOARD/DELETE_USER':\n      return state;\n    case '/STATS_DASHBOARD/LOAD_STUDIOS_USERS':\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    default:\n      return state;\n  }\n\n}\n\n","import {IStockState, StockReducerAction} from \"../actions/stock.actions\";\nimport * as unorm from \"unorm\";\nimport {IInventoryCar} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport * as moment from 'moment-timezone';\n\nconst initialState: IStockState = {\n  cars: [],\n  carsTable: [],\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    colors: [],\n    brands: [],\n    denominations: []\n  },\n  dataFilters:{\n    venues:[],\n    colors:[],\n    brands:[],\n    denominations:[],\n    types:[],\n    properties:[],\n  },\n  vinInStock: {},\n  searching: false,\n  message: \"\",\n  loading: true,\n  source: null\n};\n\nexport interface IFilterStock {\n  text: string;\n  type: string;\n  property: string;\n  venues: string[];\n  colors: string[];\n  brands: string[];\n  denominations: string[];\n}\n\n\nexport function stockReducer(state = initialState, action: StockReducerAction) {\n  switch (action.type) {\n    case '/STOCK/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/STOCK/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n     case '/STOCK/CHANGE_FILTER':\n      return {\n        ...state,\n        ...processCars(state.cars, action.payload.filter),\n        filter: action.payload.filter,\n        searching: isSearching(action.payload.filter)\n      };\n    case '/STOCK/LOAD':\n      return {\n        ...state,\n        cars: action.payload.cars,\n        ...processCars(action.payload.cars, state.filter),\n        dataFilters: processfilters(action.payload.cars),\n        message: action.payload.message\n      };\n    default:\n      return state;\n  }\n}\n\nfunction isSearching(filter: IFilterStock){\n  const {text, brands, venues, colors, denominations, property, type} = filter;\n  if(text.length || brands.length || venues.length || colors.length || denominations.length || property.length || type.length) {\n    return true\n  }\n  return false;\n\n}\n\nfunction processfilters(cars:IInventoryCar[]){\n  const venues: any[] = [],\n    colors: any[] = [],\n    brands: any[] = [],\n    denominations: any[] = [],\n    types: any[] = [],\n    properties: any[] = [];\n  const venuesKeys: string[] = [],\n    colorsKeys: string[] = [],\n    brandsKeys: string[] = [],\n    denominationsKeys: string[] = [],\n    typesKeys: string[] = [],\n    propertiesKeys: string[] = [];\n\n  for (const car of cars) {\n    const {color, property, type, brand, denomination} = car.car;\n    const {venueFound, venue} = car;\n    if (brand && brand.length && !brandsKeys.includes(brand)) {\n      brandsKeys.push(brand);\n      brands.push(brand);\n    }\n    if (color && color.length && !colorsKeys.includes(color)) {\n      colorsKeys.push(color);\n      colors.push(color);\n    }\n    if (denomination && denomination.length && !denominationsKeys.includes(denomination)) {\n      denominationsKeys.push(denomination);\n      denominations.push(denomination);\n    }\n    if (type && type.length && !typesKeys.includes(type)) {\n      typesKeys.push(type);\n      types.push(type);\n    }\n    if (property && property.length && !propertiesKeys.includes(property)) {\n      propertiesKeys.push(property);\n      properties.push(property);\n    }\n    if (venueFound && !venuesKeys.includes(venueFound._id)) {\n      venuesKeys.push(venueFound._id);\n      venues.push(venueFound);\n    }\n    if (venue && !venuesKeys.includes(venue._id)) {\n      venuesKeys.push(venue._id);\n      venues.push(venue);\n    }\n\n  }\n  return {\n    venues: venues.sort(function(a, b){\n      if(a.name < b.name) { return -1; }\n      if(a.name > b.name) { return 1; }\n      return 0;\n    }),\n    colors: colors.sort(),\n    brands: brands.sort(),\n    denominations: denominations.sort(),\n    types: types.sort(),\n    properties: properties.sort()\n  }\n}\n\nfunction processCars(cars: IInventoryCar[], filter: IFilterStock): { carsTable: any[]; vinInStock: any; } {\n  const data: any[] = [];\n  let vinInStock: any = {};\n  for (const car of cars) {\n    let add = true;\n    if (filter && filter.venues && filter.venues.length && car.venue) {\n      add = (filter.venues as any).includes(car.venue._id);\n      if (!add && car.venueFound) {\n        add = (filter.venues as any).includes(car.venueFound._id);\n      }\n    }\n    if (add && filter && filter.brands && filter.brands.length && car.car.brand) {\n      add = (filter.brands as any).includes(car.car.brand);\n    }\n    if (add && filter && filter.denominations && filter.denominations.length && car.car.denomination) {\n      add = (filter.denominations as any).includes(car.car.denomination);\n    }\n    if (add && filter && filter.colors && filter.colors.length && car.car.color) {\n      add = (filter.colors as any).includes(car.car.color);\n    }\n    if (add && filter && filter.property && filter.property.length) {\n      add = car.car.property === filter.property;\n    }\n    if (add && filter && filter.type && filter.type.length) {\n      add = car.car.type === filter.type;\n    }\n    if (add && filter && filter.text && filter.text.length) {\n      const result: boolean[] = filter.text.toLowerCase().split(' ').map((text) => (\n        unorm.nfd(`${car.car.vin}${car.car.brand}${car.car.color}${car.car.denomination}${car.car.patent}${car.car.internalNumber}`)\n          .replace(/[\\u0300-\\u036f]/g, '')\n          .toLowerCase()\n          .includes(text.toLowerCase())\n      ));\n      add = result.every((element: boolean) => element === true) === true;\n    }\n\n    const patent: string = car.car.patent ? car.car.patent : '';\n    if (add) {\n      const {vin} = car.car;\n      if (!vinInStock.hasOwnProperty(vin)) {\n        vinInStock[vin] = {\n        }\n      }\n      const venueFoundID = car.venueFound ? car.venueFound._id : '-';\n      let daysInVenue = null;\n      let receptionVenue = null;\n      if (car.car?.meta?.location?.venue && car.car.meta.location.venue._id === venueFoundID) {\n        receptionVenue = car.car.meta.location.checkedDate;\n        daysInVenue = moment().diff(moment(receptionVenue), 'days');\n      }\n\n      data.push({\n        _id: (car as any)._id,\n        carID: (car as any).car._id,\n        vin: car.car.vin,\n        brand: car.car.brand,\n        denomination: car.car.denomination,\n        internalNumber: car.car.internalNumber,\n        label: car.label,\n        labelName: car.label && car.label.hasOwnProperty('name') ? car.label.name : 'z',\n        labelBy: car.labelBy,\n        color: car.car.color,\n        labelText: car.labelText,\n        meta: car.car.meta,\n        venue: car.venue ? car.venue.name : '-',\n        images: car.images && car.images.length ? car.images : [],\n        comments: car.comments && car.comments.length ? car.comments : [],\n        countComments: car.comments && car.comments.length ? car.comments.length : 0,\n        venueFoundID,\n        venueFound: car.venueFound ? car.venueFound.name : '-',\n        receptionVenue,\n        daysInVenue,\n        patent,\n        inventoriedBy: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n        status: car.status,\n        option: car.status\n      });\n    }\n  }\n  return {\n    carsTable: data,\n    vinInStock\n  };\n}\n\n","import {\n  CANCEL_REQUEST_TRANSMITTAL,\n  CHANGE_ORDER_TRANSMITTAL, CREATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_ITEM_TRANSMITTAL, DELETE_TRANSMITTAL_TRANSMITTAL,\n  FILTER_REQUEST_ITEMS_TRANSMITTAL,\n  ITransmittalActionTypes,\n  ITransmittalState,\n  LOAD_CARRIERS_TRANSMITTAL,\n  LOAD_DRIVERS_TRANSMITTAL, LOAD_MILESTONE_TYPES_TRANSMITTAL,\n  LOAD_REQUEST_ITEMS_TRANSMITTAL,\n  LOAD_TRANSMITTAL,\n  LOAD_VENUES_TRANSMITTAL,\n  LOADING_REQUEST_ITEMS_TRANSMITTAL,\n  LOADING_TRANSMITTAL,\n  TOOGLE_TAB_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_TRANSMITTAL,\n  TRANSPORT_MILESTONE_LOAD_STATUS\n} from '../actions/transmittal.types';\nimport {ITransmittal} from '../../../../../src/distribution/interfaces/transmittal.interface';\n\nconst initialState: ITransmittalState<ITransmittal> = {\n  loading: true,\n  requestItemsLoading: true,\n  data: [],\n  carriers: [],\n  venues: [],\n  drivers: [],\n  milestoneTypes: [],\n  milestones: [],\n  transmittalOpen: [],\n  source: null,\n  requestItems: [],\n  requestItemsfilters: {\n    request: '',\n    entry: '',\n    text: '',\n    venues: [],\n    properties: [],\n    status: [],\n    from: null,\n    to: null\n  },\n  requestItemsPagination: {\n    count: 0,\n    page: 1,\n    pages: 0\n  },\n  options: {\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 0\n  }\n};\n\nexport default function transmittalReducer(state= initialState, action: ITransmittalActionTypes): ITransmittalState {\n  switch (action.type) {\n    case LOADING_TRANSMITTAL:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case LOAD_TRANSMITTAL:\n      return {\n        ...state,\n        data: action.payload.data,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case DELETE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return  {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: transmittal.items.filter((item: any) => {\n                return item._id !== action.payload.transmittalItem._id;\n              })\n            };\n          }\n          return transmittal;\n        })\n      };\n    case DELETE_TRANSMITTAL_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.filter((transmittal: any) => {\n          return transmittal._id !== action.payload.transmittal._id;\n        })\n      };\n    case UPDATE_TRANSMITTAL_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittal._id) {\n            return {\n              ...transmittal,\n              ...action.payload.transmittal\n            };\n          } else {\n            return transmittal;\n          }\n        })\n      };\n    case CREATE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: [...transmittal.items, action.payload.transmittalItem]\n            };\n          }\n          return transmittal;\n        })\n      };\n    case UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return  {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: transmittal.items.map((item: any) => {\n                if (item._id === action.payload.transmittalItem._id) {\n                  return {\n                    ...item,\n                    ...action.payload.transmittalItem\n                  };\n                }\n                return item;\n              })\n            };\n          }\n          return transmittal;\n        })\n      };\n    case LOAD_CARRIERS_TRANSMITTAL:\n      return {\n        ...state,\n        carriers: action.payload.carriers,\n      };\n    case LOAD_DRIVERS_TRANSMITTAL:\n      return {\n        ...state,\n        drivers: action.payload.drivers,\n      };\n    case LOAD_MILESTONE_TYPES_TRANSMITTAL:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes,\n      };\n    case LOAD_VENUES_TRANSMITTAL:\n      return {\n        ...state,\n        venues: action.payload.venues,\n      };\n    case TOOGLE_TAB_TRANSMITTAL:\n      return {\n        ...state,\n        transmittalOpen: state.transmittalOpen.includes(action.payload.transmittalId) ?\n          state.transmittalOpen.filter(id => id !== action.payload.transmittalId) :\n          [...state.transmittalOpen, action.payload.transmittalId]\n      };\n    case CHANGE_ORDER_TRANSMITTAL:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case CANCEL_REQUEST_TRANSMITTAL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case LOADING_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItemsLoading: action.payload.requestItemsLoading\n      };\n    case FILTER_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItemsfilters: {\n          ...state.requestItemsfilters,\n          [action.payload.key]: action.payload.value\n        }\n      };\n    case LOAD_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItems: action.payload.requestItems,\n        requestItemsPagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case TRANSPORT_MILESTONE_LOAD_STATUS:\n      return {\n        ...state,\n        milestones: action.payload.milestones\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IUsersState,\n  UserReduxAction\n} from '../actions/users.actions';\n\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\n\nconst initialState: IUsersState = {\n  users: [],\n  venues: [],\n  companies: [],\n  searchText: '',\n  permissions: [],\n  forms: [],\n  channels: [],\n  loading: true,\n  tempUser: {\n    _id: '',\n    isAdmin: false,\n    isDriver: false,\n    firstName: '',\n    company: null,\n    lastName: '',\n    email: '',\n    settings: {},\n    userPermissions: [],\n    userForms: [],\n    venuesAccess: []\n  },\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function usersReducer(state = initialState, action: UserReduxAction): IUsersState {\n  switch (action.type) {\n    case '/USERS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/USERS/LOAD_VENUES':\n      return {\n        ...state,\n        venues: action.payload.venues\n      };\n    case '/USERS/LOAD_PERMISSIONS':\n      return {\n        ...state,\n        permissions: action.payload.permissions\n      };\n    case '/USERS/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/USERS/LOAD_FORMS':\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case '/USERS/LOAD_CHANNELS':\n      return {\n        ...state,\n        channels: action.payload.channels\n      };\n    case '/USERS/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case '/USERS/CHANGE_TEMP_USER':\n      return {\n        ...state,\n        tempUser: action.payload.user\n      };\n    case '/USERS/CHANGE_USER':\n      return {\n        ...state,\n        users: state.users.map((user) => (user._id === action.payload.user._id ? action.payload.user : user))\n      };\n    case '/USERS/LOAD_USERS':\n      return {\n        ...state,\n        users: action.payload.users,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/USERS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/USERS/DELETE_USER':\n      return {\n        ...state,\n        users: state.users.filter((user: IUser) => user._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/USERS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IVenue} from '../../../../../src/app/interfaces/venue.interface';\nimport {IVenuesState, VenueReduxAction} from '../actions/venues.actions';\n\nconst initialState: IVenuesState = {\n  venues: [],\n  allVenues: [],\n  companies: [],\n  carriers: [],\n  regions: [],\n  searchText: '',\n  loading: true,\n  source: null,\n  users: [],\n  tempVenue: {\n    _id: '',\n    lat: 0,\n    lng: 0,\n    name: '',\n    code: '',\n    abbreviation: '',\n    type: 'receiver',\n    responsible: [],\n    sendToDays: [],\n    sendTo: [],\n    shippingMaxDays: 5,\n    receiveFrom: [],\n    shippingCarriers: [],\n    receptionCarriers: []\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function venuesReducer(state = initialState, action: VenueReduxAction): IVenuesState {\n  switch (action.type) {\n    case '/VENUES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/VENUES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/VENUES/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/VENUES/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/VENUES/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case '/VENUES/LOAD_ALL_VENUES':\n      return {\n        ...state,\n        allVenues: action.payload.allVenues\n      };\n    case '/VENUES/LOAD_CARRIERS':\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case '/VENUES/LOAD_REGIONS':\n      return {\n        ...state,\n        regions: action.payload.regions\n      };\n    case '/VENUES/CHANGE_VENUE':\n      return {\n        ...state,\n        venues: state.venues.map((venue: IVenue) => {\n          if (venue._id === action.payload.venue._id) {\n            venue.name = action.payload.venue.name;\n            venue.code = action.payload.venue.code;\n            venue.abbreviation = action.payload.venue.abbreviation;\n            venue.company = action.payload.venue.company;\n            venue.type = action.payload.venue.type;\n            venue.sendToDays = action.payload.venue.sendToDays;\n            venue.sendTo = action.payload.venue.sendTo;\n            venue.shippingMaxDays = action.payload.venue.shippingMaxDays;\n            venue.receiveFrom = action.payload.venue.receiveFrom;\n          }\n          return venue;\n        })\n      };\n    case '/VENUES/CHANGE_TEMP_VENUE':\n      return {\n        ...state,\n        tempVenue: action.payload.venue\n      };\n    case '/VENUES/DELETE_VENUE':\n      return {\n        ...state,\n        venues: state.venues.filter((venue: IVenue) => venue._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/VENUES/LOAD_VENUES':\n      return {\n        ...state,\n        venues: action.payload.venues,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case \"/VENUES/LOAD_USERS\":\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    default:\n      return state;\n  }\n}\n","import {IVersionsState, VersionReduxAction} from \"../actions/versions.actions\";\n\nconst initialState: IVersionsState = {\n  versions: [],\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function versionsReducer(state = initialState, action: VersionReduxAction): IVersionsState {\n  switch (action.type) {\n    case '/VERSIONS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/ALERTS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/VERSIONS/CREATE':\n      return {\n        ...state,\n        versions: [action.payload.version, ...state.versions]\n      };\n    case '/VERSIONS/LOAD_DATA':\n      return {\n        ...state,\n        versions: action.payload.versions\n      };\n    default:\n      return state;\n  }\n}\n","import { routerMiddleware } from 'connected-react-router';\nimport * as createRavenMiddleware from 'raven-for-redux';\nimport * as Raven from 'raven-js';\nimport {applyMiddleware, createStore} from 'redux';\nimport createDebounce from 'redux-debounced';\nimport {composeWithDevTools} from 'redux-devtools-extension';\n// import LogerMiddleware from 'redux-logger';\nimport ThunkMiddleware from 'redux-thunk';\nimport {IWindow} from '../interfaces/window';\nimport createRootReducer from '../reducers/index.reducer';\nimport browserHistort from '../utils/history';\n\ndeclare let window: IWindow;\n\nexport const history = browserHistort;\n\nconst configureStore = () => {\n  let enhancers: any;\n  const middlewares: any[] = [routerMiddleware(history)];\n\n  if (process.env.NODE_ENV === 'development') {\n    middlewares.push(ThunkMiddleware);\n    // middlewares.push(LogerMiddleware);\n    middlewares.push(createDebounce());\n    const composeEnhancers = composeWithDevTools({trace: true, traceLimit: 10 });\n    enhancers = composeEnhancers(applyMiddleware(...middlewares));\n  } else {\n    middlewares.push(ThunkMiddleware);\n    middlewares.push(createDebounce());\n    Raven.config('https://7cb5eacf6f8249b888468a1b72bd7632@sentry.osacontrol.com/5').install();\n    const context = {\n        id: window.user._id,\n        name: `${window.user.firstName} ${window.user.lastName}`,\n        email: window.user.email\n    };\n    Raven.setUserContext(context);\n    Raven.setTagsContext({\n        environment: process.env.NODE_ENV\n    });\n    Raven.setExtraContext({\n        app: 'Andes'\n    });\n    middlewares.push(createRavenMiddleware(Raven));\n    enhancers = applyMiddleware(...middlewares);\n  }\n\n  return createStore(createRootReducer(history), enhancers);\n};\n\nexport default configureStore;\n","import Axios, {AxiosError, AxiosInstance, AxiosPromise, AxiosRequestHeaders, CancelTokenSource, CancelTokenStatic } from 'axios';\nimport * as Raven from 'raven-js';\nimport * as swal from 'sweetalert';\nimport { IBaseCarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IBaseCompany } from '../../../../../src/app/interfaces/company.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IBaseRegion } from '../../../../../src/app/interfaces/region.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport * as queryString  from 'query-string';\nimport { ISalesChannel } from '../../../../../src/request/interfaces/salesChannel.interface';\nimport { IPaymentMethod } from '../../../../../src/request/interfaces/paymentMethod.interface';\nimport { IBaseVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport { ITempUser } from '../actions/users.actions';\nimport { IFilterCar } from '../reducers/inventory.reducer';\nimport { ITransmittalItem } from '../../../../../src/distribution/interfaces/transmittalItem.interface';\nimport { ITransmittal } from '../../../../../src/distribution/interfaces/transmittal.interface';\nimport { IOperationType } from '../../../../../src/request/interfaces/operationType.interface';\nimport { IMilestone } from '../../../../../src/distribution/interfaces/milestone.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\nimport { ITempStudio } from '../actions/statsDashboard.actions';\nimport { getUsersParams } from './axios.types';\n\nexport default class ApiService {\n\n  private readonly instance: AxiosInstance;\n  private CancelToken: CancelTokenStatic;\n  private source: CancelTokenSource;\n\n  constructor(private headers: AxiosRequestHeaders = {}) {\n    this.instance = Axios.create({\n      headers: this.headers\n    });\n    this.CancelToken = Axios.CancelToken;\n  }\n\n  public errorHandler(err: AxiosError): void {\n    if (err.response) {\n      if ([500].includes(err.response.status)) {\n        Raven.captureException(JSON.stringify(err.response));\n        swal!('Ups ha ocurrido un error', err.response.data.message ? err.response.data.message : err.response.data.errmsg, 'error');\n      } else {\n        swal!('Ups ha ocurrido un error', err.response.data.message ? err.response.data.message : err.response.data.errmsg, 'error');\n      }\n    } else if (err.request) {\n      Raven.captureException(JSON.stringify(err.request));\n    } else {\n      Raven.captureException(JSON.stringify(err));\n    }\n  }\n\n  public getProperties(): AxiosPromise {\n    return this.instance.get(\n      `/api/cars/properties/`\n      , {\n        cancelToken: this.source.token\n      });\n  }\n\n  public getUsers({\n      page, search, type, venue, minified = false, limit = 20\n    }: getUsersParams\n  ): AxiosPromise {\n    const params = queryString.stringify({\n      page, search, type, venue, minified, limit\n    });\n    return this.instance.get(\n      `/api/admin/users?${params}`\n      , {\n        cancelToken: this.source.token\n      });\n  }\n\n  public createUser(user: ITempUser): AxiosPromise {\n    delete user._id;\n    return this.instance.post(\n      `/api/admin/users/`\n      , user);\n  }\n\n  public changePasswordUser(user: string, password: string): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/users/change-password/`\n      , {\n        user,\n        password\n      });\n  }\n\n  public updateUser(user: ITempUser): AxiosPromise {\n    return this.instance.patch(\n      `/api/admin/users/${user._id}/`\n      , user);\n  }\n\n  public deleteUser(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/users/${id}/`\n    );\n  }\n\n  public createIntegration(user: any): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/integrations/`\n      , user);\n  }\n\n  public updateIntegration(user: ITempUser): AxiosPromise {\n    return this.instance.patch(\n      `/api/admin/integrations/${user._id}/`\n      , user);\n  }\n\n  public deleteIntegration(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/integrations/${id}/`\n    );\n  }\n\n  public getParticipantsPerDate(onlyControls: Boolean, companies?: string) {\n    return this.instance.get(\n      `/api/participants-per-date${ onlyControls ? `?only_controls=1` : `?only_controls=0`}${companies ? `&companies=${companies}` : ''}`\n    );\n  }\n\n  public getParticipant(id: string) {\n    return this.instance.get(\n      `/api/participant/${id}/`\n    );\n  }\n\n  public getCompanies(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/companies?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public createCompany(company: IBaseCompany): AxiosPromise {\n    const formData = new FormData();\n    formData.append('name', company.name);\n    formData.append('businessName', company.businessName);\n    formData.append('rut', company.rut);\n    formData.append('billing', JSON.stringify(company.billing));\n    formData.append('notifications', JSON.stringify(company.notifications));\n    if (company.image) {\n      formData.append('image', company.image);\n    }\n    if (company.marker) {\n      formData.append('marker', company.marker);\n    }\n    this.instance.defaults.headers.common['Content-Type'] = 'multipart/form-data';\n    return this.instance.post(\n      `/api/admin/companies/`, formData\n    );\n  }\n\n  public updateCompany(company: IBaseCompany): AxiosPromise {\n    const formData = new FormData();\n    formData.append('name', company.name);\n    formData.append('businessName', company.businessName);\n    formData.append('rut', company.rut);\n    formData.append('billing', JSON.stringify(company.billing));\n    formData.append('notifications', JSON.stringify(company.notifications));\n    if (company.image) {\n      formData.append('image', company.image);\n    }\n    if (company.marker) {\n      formData.append('marker', company.marker);\n    }\n    this.instance.defaults.headers.common['Content-Type'] = 'multipart/form-data';\n    return this.instance.patch(\n      `/api/admin/companies/${company._id}/`, formData\n    );\n  }\n\n  public deleteCompany(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/companies/${id}/`\n    );\n  }\n\n  public createVenue(venue: IBaseVenue): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/venues/`, venue\n    );\n  }\n\n  public updateVenue(venue: IBaseVenue): AxiosPromise {\n    return this.instance.patch(\n      `/api/admin/venues/${venue._id}/`, venue\n    );\n  }\n\n  public deleteVenue(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/venues/${id}/`\n    );\n  }\n\n  public getVenues({page, pageSize, noPopulate, filted, search}:{ page: number, pageSize?: number, noPopulate?: boolean, filted?: boolean, search?:string }): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/venues?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}${noPopulate ? `&noPopulate=${noPopulate}` : ''}${filted ? `&filted=${filted}` : ''}${search ? `&search=${search}` : ''}`\n    );\n  }\n  public getCompanyVenues(): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/company-venues/`\n    );\n  }\n\n  public createReason(reason: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/reasons/`, reason\n    );\n  }\n\n  public updateReason(reason: IReason): AxiosPromise {\n    return this.instance.patch(\n      `/api/v1/reasons/${reason._id}/`, reason\n    );\n  }\n\n  public deleteReason(reason: IReason): AxiosPromise {\n    return this.instance.delete(\n      `/api/v1/reasons/${reason._id}/`\n    );\n  }\n\n  public getReasons({ page, pageSize, orderBy, orderType }: { page: number, orderType?: string, orderBy?: string, pageSize?: number }): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/reasons?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}${orderBy ? `&orderBy=${orderBy}` : ''}${orderType ? `&orderType=${orderType}` : ''}`\n    );\n  }\n\n  public createSalesChannel(salesChannel: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/sales-channel/`, salesChannel\n    );\n  }\n\n  public updateSalesChannel(salesChannel: ISalesChannel): AxiosPromise {\n    return this.instance.patch(\n      `/api/v1/sales-channel/${salesChannel._id}/`, salesChannel\n    );\n  }\n\n  public deleteSalesChannel(salesChannel: ISalesChannel): AxiosPromise {\n    return this.instance.delete(\n      `/api/v1/sales-channel/${salesChannel._id}/`\n    );\n  }\n\n  public getSalesChannel({\n     page,\n     pageSize,\n     orderBy,\n     orderType\n   }: { page: number, orderType?: string, orderBy?: string, pageSize?: number }): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/sales-channel?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}${orderBy ? `&orderBy=${orderBy}` : ''}${orderType ? `&orderType=${orderType}` : ''}`\n    );\n  }\n\n  public createPaymentMethod(paymentMethod: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/payment-method/`, paymentMethod\n    );\n  }\n\n  public updatePaymentMethod(paymentMethod: IPaymentMethod): AxiosPromise {\n    return this.instance.patch(\n      `/api/v1/payment-method/${paymentMethod._id}/`, paymentMethod\n    );\n  }\n\n  public deletePaymentMethod(paymentMethod: IPaymentMethod): AxiosPromise {\n    return this.instance.delete(\n      `/api/v1/payment-method/${paymentMethod._id}/`\n    );\n  }\n\n  public getPaymentMethods({\n   page,\n   pageSize,\n   orderBy,\n   orderType\n }: { page: number, orderType?: string, orderBy?: string, pageSize?: number }): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/payment-method?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}${orderBy ? `&orderBy=${orderBy}` : ''}${orderType ? `&orderType=${orderType}` : ''}`\n    );\n  }\n\n  public createCarrier(carrier: IBaseCarrier): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/carriers/`, carrier\n    );\n  }\n\n  public updateCarrier(carrier: IBaseCarrier): AxiosPromise {\n    return this.instance.patch(\n      `/api/admin/carriers/${carrier._id}/`, carrier\n    );\n  }\n\n  public deleteCarrier(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/carriers/${id}/`\n    );\n  }\n\n  public getCarriers(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/carriers?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public getDrivers(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/users/drivers?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public createRegion(region: IBaseRegion): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/regions/`, region\n    );\n  }\n\n  public updateRegion(region: IBaseRegion): AxiosPromise {\n    return this.instance.patch(\n      `/api/admin/regions/${region._id}/`, region\n    );\n  }\n\n  public deleteRegion(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/regions/${id}/`\n    );\n  }\n\n  public getRegions(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/regions?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public getPermissions(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/permissions?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n\n  public getCars(page: number, search?: string): AxiosPromise {\n    return this.instance.get(\n      `/api/cars?page=${page}${search ? `&search=${search}` : ''}`, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public getRevisions(onlyControls : boolean, page: number, search?: string, from?: string, to?: string, forms?: String[]): AxiosPromise {\n    let query = `?page=${page}&only_controls=${onlyControls ? '1' : '0'}`;\n    if (search)\n      query += `&search=${search}`;\n\n    if (from)\n      query += `&from=${from}`;\n\n    if (to)\n      query += `&to=${to}`;\n\n    if (forms)\n      query += `&forms=${forms.join(\",\")}`;\n\n    return this.instance.get(\n      `/api/revisions${query}`, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public getAdminCars(page?: number, search?: string): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/cars?page=${page}${search ? `&search=${search}` : ''}`, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public getCar(id: string): AxiosPromise {\n    return this.instance.get(\n      `/api/cars/${id}/`, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n\n\n  public sendImportCars(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/import-cars/`, data, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public getInventories(page: number): AxiosPromise {\n    return this.instance.get(\n      `/api/inventory?page=${page}`, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public getInventory(id: string): AxiosPromise {\n    return this.instance.get(\n      `/api/inventory/${id}/`, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public addComment(id: string, carId: string, comment: string): AxiosPromise {\n    return this.instance.post(\n      `/api/inventory/${id}/comment/`, {\n        _id: carId,\n        comment\n      }\n    );\n  }\n\n  // public createInventory({carsByVenue: any, name: string, notification: boolean, file: File, backup: File | null}): AxiosPromise {\n  public createInventory(\n    {\n      carsByVenue, name, notification, file, backupFile, manualPhoto, reportPhoto\n    }: {\n      carsByVenue: any, name: string, notification: boolean, file: File | null, backupFile: File | null, manualPhoto: number, reportPhoto: number\n  }): AxiosPromise {\n    const formData = new FormData();\n    formData.append('carsByVenue', JSON.stringify(carsByVenue));\n    formData.append('name', name);\n    formData.append('notification', notification.toString());\n    formData.append('file', file!);\n    formData.append('manualPhoto', manualPhoto.toString());\n    formData.append('reportPhoto', reportPhoto.toString());\n    if (backupFile) {\n      formData.append('backup', backupFile);\n    }\n    this.instance.defaults.headers.common['Content-Type'] = 'multipart/form-data';\n    return this.instance.post(\n      `/api/inventory/`, formData, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public importPlanning(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/planning/`, data, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public updateMassiveRequest(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/requests/update-massive/`, data, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public importRequests(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/requests/import/`, data, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public finishInventory(id: string): AxiosPromise {\n    return this.instance.post(\n      `/api/inventory/${id}/finish/`, {}\n    );\n  }\n\n  public deleteInventory(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/inventory/${id}/`, {}\n    );\n  }\n\n  public getAlerts(): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/alerts/`, {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public createAlert(alert: any): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/alerts/`,\n      alert\n    );\n  }\n\n  public deleteAlert(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/alerts/${id}/`\n    );\n  }\n  public preMassAllocation(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/requests/pre-mass-allocation/`,\n      data\n    );\n  }\n\n  public checkItemMassAllocation(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/requests/check-item-mass-allocation/`,\n      data\n    );\n  }\n\n  public processItemMassAllocation(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/requests/process-item-mass-allocation/`,\n      data\n    );\n  }\n\n  public getSource(): CancelTokenSource {\n    this.source = this.CancelToken.source();\n    return this.source;\n  }\n\n  public setLabel(inventory: string, car: string, carID: string, label: string, custom?: string): AxiosPromise {\n    return this.instance.post(\n      `/api/inventory/${inventory}/set-label/`, {\n        car,\n        label,\n        carID,\n        custom\n      });\n  }\n\n  public getInstance(): AxiosInstance {\n    return this.instance;\n  }\n\n  public getLabels(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/labels?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public createLabel(label: any): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/labels/`, label\n    );\n  }\n\n  public updateLabel(label: any): AxiosPromise {\n    return this.instance.put(\n      `/api/admin/labels/${label._id}/`, label\n    );\n  }\n\n  public deleteLabel(id: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/labels/${id}/`\n    );\n  }\n\n  public getInventoryDashboard(filter?: IFilterCar): AxiosPromise {\n    return this.instance.post(\n      '/api/inventory/dashboard/', filter ? { venues: filter.venues } : {}\n    );\n  }\n\n  public getDashboardDamagesPerVenue(): AxiosPromise {\n    return this.instance.get(\n      '/api/dashboard/damages/per-venue/'\n    );\n  }\n\n  public getDashboardTiming(from: string, to: string): AxiosPromise {\n    return this.instance.get(\n      `/api/dashboard/timing?start=${from}&end=${to}`\n    );\n  }\n\n  public getDashboardCleaning(): AxiosPromise {\n    return this.instance.get(\n      '/api/dashboard/cleaning/'\n    );\n  }\n\n  public getVersions(): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/versions/`, {\n        cancelToken: this.source.token\n      });\n  }\n\n  public loadStock({ carsByVenue }: { carsByVenue: any }): AxiosPromise {\n    return this.instance.post(\n      `/api/load-stock/`, {\n        carsByVenue\n      }, {\n        cancelToken: this.source.token\n      });\n  }\n\n  public getStock(): AxiosPromise {\n    return this.instance.get(\n      `/api/current-stock/`, {\n        cancelToken: this.source.token\n      });\n  }\n\n  public getPlanning(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/planning?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public getBilling(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/billing?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public createVersion(version: any): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/versions/`,\n      version\n    );\n  }\n\n  public getRequest(id: string): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/requests/${id}/`\n    );\n  }\n\n  public getRequestsByCar(id: string): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/requests/by-car/${id}/`\n    );\n  }\n\n\n  public getRequests({ page, pageSize, orderBy, orderType }: { page: number, orderBy: string, orderType: string, pageSize?: number }): AxiosPromise {\n    let params = `?page=${page}`;\n    params = pageSize ? `${params}&pageSize=${pageSize}` : params;\n    params = orderBy ? `${params}&orderBy=${orderBy}` : params;\n    params = orderType ? `${params}&orderType=${orderType}` : params;\n    return this.instance.get(\n      `/api/v1/requests${params}/`\n    );\n  }\n\n  public getRequestItems(\n    {\n      page,\n      pageSize,\n      orderBy,\n      orderType,\n      filters\n    }: { page: number, orderBy?: string, orderType?: string, pageSize: number, filters: any }): AxiosPromise {\n    let body: any = {\n      page,\n      filters\n    };\n    body = pageSize ? { ...body, pageSize } : body;\n    body = orderBy ? { ...body, orderBy } : body;\n    body = orderType ? { ...body, orderType } : body;\n    return this.instance.post(\n      `/api/v1/requests-item/`,\n      body\n    );\n  }\n\n  public createRequest(data: any) {\n    return this.instance.post(\n      `/api/v1/requests/`,\n      data\n    );\n  }\n\n  public deleteRequest(id: string) {\n    return this.instance.delete(\n      `/api/v1/requests/${id}/`\n    );\n  }\n\n  public createRequestItem(idRequest: string, car: any) {\n    return this.instance.post(\n      `/api/v1/add-requests-item/`, {\n        idRequest,\n        car\n      });\n  }\n\n  public uppdateRequestItemVin(item: any, vin: string) {\n    return this.instance.patch(\n      `/api/v1/requests-item/${item._id}/change-vin/`, {\n        item,\n        vin\n      });\n  }\n\n  public create